/*! 注家分片 虞翻（集解 942 / 折中 5）*/
window.YJ_ZJ_ZJ = window.YJ_ZJ_ZJ || {};
window.YJ_ZJ_ZJ["zj_yufan"] = {"id":"zj_yufan","name":"虞翻","jijieQuotes":[{"gua":"乾","guaId":"g01","yaoIdx":2,"position":"九三：君子终日乾乾，夕惕，若厉，无咎。","text":"谓阳息至三，二变成离。离为日，坤为夕。","locator":{"book":"周易集解","gua":"乾","pos":"九三"},"citation":"《周易集解》·乾卦·九三","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":4,"position":"九五：飞龙在天，利见大人。","text":"谓四已变，则五体离。离为飞，五在天，故“飞龙在天，利见大人”也。谓若庖牺观象于天，造作八卦，备物致用，以利天下，故曰“飞龙在天”。天下之所利见也。","locator":{"book":"周易集解","gua":"乾","pos":"九五"},"citation":"《周易集解》·乾卦·九五","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":11,"position":"云行雨施，品物流形。","text":"已成既济，上坎为云，下坎为雨，故“云行雨施”。乾以云雨，流坤之形，万物化成，故曰“品物流形”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":18,"position":"君子以自强不息。","text":"君子谓三。乾健，故强。天一日一夜过周一度，故自强不息。老子曰：自胜者强。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":21,"position":"终日乾乾，反复道也。","text":"至三体复，故“反复道”，谓否泰反其类也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":40,"position":"乐则行之，忧则违之，","text":"阴出初震，为乐为行，故“乐则行之”。坤死称忧，隐在坤中，遁世无逆流，故“忧则违之”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":41,"position":"确乎其不可拔，潜龙也。","text":"确，刚貌也。乾刚潜初，坤乱于上。君子弗用，隐在下位。确乎难拔，潜龙之志也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":42,"position":"九二曰：见龙在田，利见大人，何谓也？子曰","text":"中下之中，二非阳位，故明言能“正中”也。","locator":{"book":"周易集解","gua":"乾","pos":"九二"},"citation":"《周易集解》·乾卦·九二","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":48,"position":"：见龙在田，利见大人，君德也。","text":"阳始触阴，当升五为君。时舍于二，宜利天下。直方而大德，无不利。明言君德，地数始二。故称“易曰”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":49,"position":"九三曰：君子终日乾乾，夕惕若，厉，无咎。","text":"乾为德，坤为业，以乾通坤，谓为“进德修业”。","locator":{"book":"周易集解","gua":"乾","pos":"九三"},"citation":"《周易集解》·乾卦·九三","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":54,"position":"是故居上位而不骄。","text":"天道三才。一乾而以至三乾成，故为“上”。“夕惕若厉”，故“不骄”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":55,"position":"在下位而不忧。","text":"“下位”谓初。隐于初，忧则违之，故“不忧”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":60,"position":"九五曰：飞龙在天，利见大人，何谓也？子曰","text":"谓震巽也。庖牺观变而放八卦，雷风相薄，故“相应”也。","locator":{"book":"周易集解","gua":"乾","pos":"九五"},"citation":"《周易集解》·乾卦·九五","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":61,"position":"同气相求。","text":"谓艮兑山泽通气，故“相求”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":63,"position":"火就燥。","text":"离上而坎下，水火不相射。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":64,"position":"云从龙，","text":"乾为龙，云生天，故“从龙”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":65,"position":"风从虎。","text":"坤为虎，风生地，故“从虎”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":66,"position":"圣人作而万物睹。","text":"睹，见也。圣人则庖牺，合德乾五，造作八卦，以通神明之德，以类万物之情。五动成离，日出照物皆相见，故曰“圣人作而万物睹”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":69,"position":"则各从其类也。","text":"“方以类聚，物以群分”。“乾道变化，各正性命”。“触类而长”，故“各从其类”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":89,"position":"乾元者，始而亨者也。","text":"乾始开通，以阳通阴，故始通。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":91,"position":"乾始而以美利利天下，","text":"美利谓云行雨施，品物流形，故“利天下”也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":92,"position":"不言所利，大矣哉！","text":"天何言哉！四时行焉，百物生焉，故利者大也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":99,"position":"日可见之行也。","text":"谓初。乾称君子。阳出成为上德，云行雨施则成离，日新之谓上德，故“日可见之行”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":101,"position":"君子学以聚之，问以辩之，","text":"谓二。阳在二。兑在口；震为言，为讲论；坤为文，故“学以聚之，问以辩之”。兑象，君子以朋友讲习。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":102,"position":"宽以居之，仁以行之。","text":"震为宽，仁为行，谓居宽行仁，德博而化也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":103,"position":"：见龙在田，利见大人，君德也。","text":"重言君德者，大人善世不伐。信有君德，后天而奉天时，故详言之。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":104,"position":"九三：重刚而不中。","text":"以乾接乾，故“重刚”。位非二五，故“不中”也。","locator":{"book":"周易集解","gua":"乾","pos":"九三"},"citation":"《周易集解》·乾卦·九三","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":109,"position":"故或之。或之者，疑之也。故无咎。","text":"非其位，故疑之也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":115,"position":"与鬼神合其吉凶，","text":"谓乾神合吉，坤鬼合凶，以乾之坤，故“与鬼神合其吉凶”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":116,"position":"先天而天弗违，","text":"乾为天、为先。大人在乾五，乾五之坤五，天象在先。故“先天而天弗违”。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"乾","guaId":"g01","yaoIdx":117,"position":"后天而奉天时。","text":"奉，承行。乾四之坤初成震，震为后也，震春兑秋，坎冬离夏，四时象具。故“后天而奉天时”。谓承天时，行顺也。","locator":{"book":"周易集解","gua":"乾","pos":"卦辞·彖象"},"citation":"《周易集解》·乾卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":-1,"position":"卦辞","text":"谓阴极阳生，乾流坤形，坤含光大，凝乾之元，终于坤亥，出乾初子，品物咸亨，故“元亨”也。坤为牝，震为马，初动得正，故“利牝马之贞”矣。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞"},"citation":"《周易集解》·坤卦·卦辞","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":12,"position":"西南得朋，乃与类行。","text":"谓阳得其类，月朔至望，从震至乾，与时偕行，故“乃与类行”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":13,"position":"东北丧朋，乃终有庆。","text":"阳丧灭坤，坤终复生，谓月三日震象出庚，故“乃终有庆”。此指说易道阴阳消息之大要也。谓阳月三日，变而成震，出庚。至月八日成兑，见叮庚西丁南，故“西南得朋”。谓二阳为朋，故兑“君子以朋友讲习”。《文言》曰：敬义立而德不孤。《彖》曰：乃与类行。二十九日，消乙入坤，灭藏于癸，乙东癸北，故“东北丧朋”。谓之以坤灭乾，坤为丧故也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":15,"position":"安贞之吉，","text":"坤道至静，故“安”；复初得正，故“贞吉”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":16,"position":"应地无疆。","text":"震为应。阳正于初，以承坤阴；地道应，故“应地无疆”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":18,"position":"君子以厚德载物。","text":"势，力也。君子谓乾阳，为德动。在坤下，君子之德车。故“厚德载物”。老子曰：胜人者有力也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":25,"position":"六三：含章可贞。","text":"贞，正也。以阴包阳，故“含章”。三失位，发得正，故“可贞”也。","locator":{"book":"周易集解","gua":"坤","pos":"六三"},"citation":"《周易集解》·坤卦·六三","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":26,"position":"或从王事，无成有终。","text":"谓三已发成泰，乾为王，坤为事，震为从，故“或从王事”。地道无成而有终，故“无成有终”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":29,"position":"六四：括囊，无咎，无誉。","text":"括，结也。谓泰反成否。坤为囊，艮为手，巽为绳，故括囊在外多咎也。得位承五，系于包桑，故“无咎”。阴在二多誉，而远在四，故“无誉”。","locator":{"book":"周易集解","gua":"坤","pos":"六四"},"citation":"《周易集解》·坤卦·六四","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":42,"position":"后得主而有常，","text":"坤阴，先迷后顺，得常。阳出初，震为主，为常也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":45,"position":"积善之家，必有余庆；","text":"谓初。乾为积善，以坤牝。阳灭出复，震为余庆，谓“东北丧朋”，乃终有庆也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":46,"position":"积不善之家，必有余殃。","text":"坤积不善，以臣弑君，以乾通坤，极姤生巽，为余殃也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":47,"position":"臣弑其君子弑其父，","text":"坤消至二，艮子弑父。至三成否，坤臣弑君。上下不交，天下无邦。故子弑父，臣弑君也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":48,"position":"非一朝一夕之故，其所由来者渐矣。","text":"刚爻为朝，柔爻为夕；乾为寒，坤为暑，相推而成岁焉。故“非一朝一夕”，所由来渐矣。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":51,"position":"直其正也，方其义也。","text":"谓二。阳称直。乾，其静也专，其动也直，故“直其正”。方为辟，阴开为方。坤，其静也翕，其动也辟，故“方其以也”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":52,"position":"君子敬以直内，义以方外，敬义立而德不孤。","text":"阳息在二，故“敬以直内”。坤位在外，故义以方外。谓阳见兑丁，西南得朋，乃与类行，故德不孤。孔子曰：必有邻也。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":57,"position":"天地变化，草木蕃。","text":"谓阳息坤成泰。天地反，以乾变坤，坤化升乾，万物出震，“故天地变化，草木蕃”矣。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":58,"position":"天地闭，贤人隐。","text":"谓四。泰反成否，乾称贤人。隐藏坤中，以俭德避难，不荣以禄，故“贤人隐”矣。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":60,"position":"君子黄中通理，正位居体，","text":"谓五。坤息体观，地色黄，坤为理。以乾通坤，故称“通理”。五正阳位，故曰“正位”。艮为居，体谓四支也。艮为两肱，巽为两股。故曰“黄中通理，正位居体”。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"坤","guaId":"g02","yaoIdx":61,"position":"美在其中，而畅于四支，","text":"阳称美，在五中四支。谓股肱。","locator":{"book":"周易集解","gua":"坤","pos":"卦辞·彖象"},"citation":"《周易集解》·坤卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":-1,"position":"卦辞","text":"坎二之初，刚柔交震，故“元、亨”；之初得正，故“利、贞”矣。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞"},"citation":"《周易集解》·屯卦·卦辞","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":0,"position":"勿用有攸往，利建侯。","text":"之外称往。初震得正，起之欲应，动而失位，故“勿用有攸往”。震为侯，初刚难拔，故利以建侯。老子曰：善建者，拔也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":1,"position":"：屯，刚柔始交而难生。","text":"乾刚坤柔，坎二交初，故“始交”。确乎难拔，故“难生”也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":3,"position":"雷雨之动满形，","text":"震雷坎雨，坤为形也。谓三巳反正，成既济。坎水流坤，故“满形”。谓雷动雨施，品物流形也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":5,"position":"宜建侯而不宁。","text":"造，造生也。草，草创物也。坤冥为昧，故“天造草昧”。成既济定，故曰“不宁”，言宁也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":8,"position":"初九：盘桓，利居贞，利建侯。","text":"震起艮止，动乎险中，故“盘桓”。得正得民，“利居贞”。谓君子居其室，慎密而不出也。","locator":{"book":"周易集解","gua":"屯","pos":"初九"},"citation":"《周易集解》·屯卦·初九","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":12,"position":"乘马班加。","text":"屯邅盘桓，谓初也。震为马作足，二乘初，故“乘马”。班，踬也。马不进，故“班如”矣。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":13,"position":"匪寇婚媾，女子贞不字，十年乃字。","text":"匪非也。寇谓五。坎为寇盗，应在坎，故“匪寇”。阴阳德正，故“婚媾”。字，妊娠也。三失位，变复体离。离为女子，为大腹，故称“字”。今失位为坤，离象不见，故“女子贞不字”。坤数十。三动反正，离女大腹。故十年反常乃字。谓成既济定也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":16,"position":"六三：即鹿无虞，惟入于林中，","text":"即，就也。虞谓虞人，掌禽兽者。艮为山，山足称麓。麓，林也。三变体坎，坎为丛木。山下，故称“林中”。坤为兕虎；震为麋鹿，又为惊走；艮为狐狼。三变禽走入林中，故曰“即鹿无虞，惟入林中”矣。","locator":{"book":"周易集解","gua":"屯","pos":"六三"},"citation":"《周易集解》·屯卦·六三","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":17,"position":"君子几，不如舍，往吝。","text":"君子谓阳已正位。几，近。舍，置。吝，疵也。三应于上，之应历险。不可以往，动如失位。故“不如舍”之，往必吝穷矣。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":20,"position":"六四：乘马班如，","text":"乘，三也。谓三巳变坎，为马，故曰“乘马”。马在险中，故“班如”也。或说乘初，初为建侯，安得乘之也。","locator":{"book":"周易集解","gua":"屯","pos":"六四"},"citation":"《周易集解》·屯卦·六四","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":22,"position":"：求而往，明也。","text":"之外称“往”。体离，故“明也”。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":23,"position":"九五：屯其膏，","text":"坎雨称“膏”。《诗》云：阴雨膏之，是其义也。","locator":{"book":"周易集解","gua":"屯","pos":"九五"},"citation":"《周易集解》·屯卦·九五","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":25,"position":"：屯其膏，施未光也。","text":"阳陷阴中，故“未光也”。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":26,"position":"上六：乘马班如，","text":"乘，五也。坎为马，震为行，艮为止，马行而止，故“班如”也。","locator":{"book":"周易集解","gua":"屯","pos":"上六"},"citation":"《周易集解》·屯卦·上六","edition":"jijie"},{"gua":"屯","guaId":"g03","yaoIdx":28,"position":"：泣血涟如，何可长也。","text":"谓三变时，离为目。坎为血，震为出。血流出目，故“泣血涟如”。柔乘于刚，故不可长也。","locator":{"book":"周易集解","gua":"屯","pos":"卦辞·彖象"},"citation":"《周易集解》·屯卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":-1,"position":"卦辞","text":"艮三之二。亨谓二。震刚柔接，故“亨”。蒙亨，以通行时中也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞"},"citation":"《周易集解》·蒙卦·卦辞","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":0,"position":"匪我求童蒙，童蒙求我。","text":"童蒙谓五，艮为童蒙。我谓二也。震为动起，嫌求之五，故曰“匪我求童蒙”。五阴求阳，故“童蒙求我，志应也”。艮为求，二体师象，坎为经。谓礼有来学，无往教。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":2,"position":"利贞。","text":"二五失位，利变之正，故“利贞”。蒙以养正，圣功也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":9,"position":"蒙以养正，圣功也。","text":"体颐，故养。五多功。圣谓二，二志应五，变得正而亡其蒙，故“圣功也”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":10,"position":"：山下出泉，蒙。","text":"艮为山，震为出，坎象流出，故“山下出泉”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":11,"position":"君子以果行育德。","text":"君子谓二。艮为果，震为行。育，养也。二至上有颐养象，故“以果行育德”也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":12,"position":"初六：发蒙，利用刑人，用说桎梏，以往吝。","text":"发蒙之正，初为蒙始，而失其位。发蒙之正以成兑，兑为刑人，坤为用，故曰“利用刑人”矣。坎为穿木，震足艮手，互与坎连，故称“桎梏”。初发成兑，兑为说，坎象毁坏，故曰“用说桎梏”。之应历险，故“以往吝”。吝，小疵也。","locator":{"book":"周易集解","gua":"蒙","pos":"初六"},"citation":"《周易集解》·蒙卦·初六","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":13,"position":"：利用刑人，以正法也。","text":"坎为法，初发之正，故“正法也”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":14,"position":"九二：包蒙，吉。纳妇，吉。子克家。《象》","text":"坤为包。应五据初，初与三四同体，包养四阴，故“包蒙，吉”。震刚为夫，伏巽为妇，二以刚接柔，故“纳妇，吉”。二称家。震，长子，主器者。纳妇成初。故有“子克家”也。","locator":{"book":"周易集解","gua":"蒙","pos":"九二"},"citation":"《周易集解》·蒙卦·九二","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":15,"position":"六三：勿用娶女，见金夫，不有躬，无攸利。","text":"谓三诫上也。金夫谓二。初发成兑，故三称“女”。兑为见。阳称金。震为夫。三逆乘二阳，所行不顺，为二所淫。上来之三，陟阴。故曰“勿用娶女，见金夫”矣。坤身称躬，三为二所乘，兑泽动下，不得之应，故“不有躬”。失位多凶，故“无攸利”也。","locator":{"book":"周易集解","gua":"蒙","pos":"六三"},"citation":"《周易集解》·蒙卦·六三","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":16,"position":"：勿用娶女，行不顺也。","text":"失位乘刚，故“行不顺也”。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":18,"position":"六五：童蒙，吉。","text":"艮为童蒙，处贵承上，有应于二，动而成巽，故“吉”也。","locator":{"book":"周易集解","gua":"蒙","pos":"六五"},"citation":"《周易集解》·蒙卦·六五","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":20,"position":"上九：击蒙，不利为寇，利御寇。","text":"体艮为手，故“击”。谓五巳变，上动成坎，称寇。而逆乘阳，故“不利为寇”矣。御，止也。此寇谓二。坎为寇，巽为高，艮为山，登山备下，顺有师象，故“利御寇”也。","locator":{"book":"周易集解","gua":"蒙","pos":"上九"},"citation":"《周易集解》·蒙卦·上九","edition":"jijie"},{"gua":"蒙","guaId":"g04","yaoIdx":21,"position":"：利用御寇，上下顺也。","text":"自上御下，故“顺”也。","locator":{"book":"周易集解","gua":"蒙","pos":"卦辞·彖象"},"citation":"《周易集解》·蒙卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":-1,"position":"卦辞","text":"大壮四之五。孚谓五。离日为光。四之五，得位正中。故“光亨”。“贞吉”，谓“壮于大舆之辐也”。","locator":{"book":"周易集解","gua":"需","pos":"卦辞"},"citation":"《周易集解》·需卦·卦辞","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":4,"position":"利涉大川，往有功也。","text":"谓二失位，变而涉坎，坎为大川。得位应五，故“利涉大川”。五多功，故“往有功也”。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":6,"position":"君子以饮食宴乐。","text":"君子谓乾。坎水兑口。水流入口为饮。二失位，变体噬嗑，为食，故“以饮食”。阳在内，称宴。大壮，震为乐，故“宴乐”也。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":9,"position":"九二：需于沙，小有言，终吉。","text":"沙谓五。水中之阳称沙也。二变之阴，称校大壮震为言，兑为口。四之五，震象半见，故“小有言”。二变应之，故“终吉”。","locator":{"book":"周易集解","gua":"需","pos":"九二"},"citation":"《周易集解》·需卦·九二","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":10,"position":"：需于沙，衍在中也。","text":"衍，流也。中谓五也。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"需","guaId":"g05","yaoIdx":14,"position":"自我致寇，敬慎不败也。","text":"离为戎，乾为敬。阴消至五遁，臣将弑君。四上壮坤，故“敬慎不败”。","locator":{"book":"周易集解","gua":"需","pos":"卦辞·彖象"},"citation":"《周易集解》·需卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":0,"position":"窒惕，中吉，","text":"遁三之二也。孚谓二。窒，塞止也。惕，惧二也。二失位，故不言贞。遁将成否，则子弑父，臣弑君。三来之二，得中；弑不得行，故“中吉”也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":1,"position":"终凶。","text":"二失位，终止不变，则入于渊，故“终凶”也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":9,"position":"君子以作事谋始。","text":"君子谓乾。三来变坤，为作事。坎为谋。乾知大始。故“以作事谋始”。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":10,"position":"初六：不永所事，小有言，终吉。","text":"永，长也。坤为事，初失位，而为讼始，故“不永所事”也。小有言，谓初四易位成震，言三食旧德，震象半见，故“小有言”。初变得正，故“终吉”也。","locator":{"book":"周易集解","gua":"讼","pos":"初六"},"citation":"《周易集解》·讼卦·初六","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":12,"position":"九二：不克讼，归而逋。","text":"谓与四讼，坎为隐伏，故“逋”乾位刚在上，坎濡失正，故“不克”也。","locator":{"book":"周易集解","gua":"讼","pos":"九二"},"citation":"《周易集解》·讼卦·九二","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":13,"position":"其邑人三百户，无眚。","text":"眚，灾也，坎为眚，谓二变应五。乾为百，坤为户；三爻，故三百户。坎化为坤，故“无眚”。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":16,"position":"六三：食旧德，贞厉，终吉。","text":"乾为旧德。食谓初。四二已变之正。三动得位，体噬嗑食。四变食乾，故“食旧德”。三变在坎，正危贞厉，得位二，故“终吉”也。","locator":{"book":"周易集解","gua":"讼","pos":"六三"},"citation":"《周易集解》·讼卦·六三","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":17,"position":"或从王事，无成。","text":"乾为王。二变否时，坤为事，故“或从王事”。道无成而代有终，故曰“无成”。坤三同义也。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":19,"position":"九四：不克讼，复即命渝，安贞吉。","text":"失位，故“不克讼”。渝变也。不克讼，故复位。变而成巽，巽为命令，故“复即命渝”。动而得位，故“安贞吉”。谓二已变坤安也。","locator":{"book":"周易集解","gua":"讼","pos":"九四"},"citation":"《周易集解》·讼卦·九四","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":22,"position":"上九：或锡之鞶带，","text":"锡谓王之锡命。鞶带，大带。男子鞶革。初四已易位，三二之正，巽为腰带，故“鞶带”。","locator":{"book":"周易集解","gua":"讼","pos":"上九"},"citation":"《周易集解》·讼卦·上九","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":23,"position":"终朝三拕之。","text":"位终乾上。二变时，坤为终。离为日，乾为甲。日出甲上。故称“朝”。应在三，三变时，艮为手，故“终朝三拕之”。使变应已，则去其鞶带。体坎乘阳，故象曰“不足敬也”。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"讼","guaId":"g06","yaoIdx":24,"position":"：以讼受服，亦不足敬也。","text":"服谓鞶带。终朝见褫(拕)，乾象毁坏。故“不足敬”。","locator":{"book":"周易集解","gua":"讼","pos":"卦辞·彖象"},"citation":"《周易集解》·讼卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":0,"position":"：师，众也。贞，正也。能以众正，可以王矣","text":"坤为众，谓二失位，变之五，为比。故“能以众正“，乃“可以王矣”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":5,"position":"君子以容民畜众。","text":"君子谓二。容，宽也。坤为民众，又畜养也。阳在二，宽以居之，五变执言时，有颐养象。故“以容民畜众矣”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":9,"position":"六三：师或舆尸，凶。","text":"坤为尸，坎为车多眚。同人离为戈兵，为折首：失位乘刚无应，尸在车上，故“舆尸，凶”矣。","locator":{"book":"周易集解","gua":"师","pos":"六三"},"citation":"《周易集解》·师卦·六三","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":13,"position":"六五：田有禽，利执言，无咎。","text":"田谓二。阳称禽。震为言。五失位，变之正，艮为执。故“利执言，无咎”。","locator":{"book":"周易集解","gua":"师","pos":"六五"},"citation":"《周易集解》·师卦·六五","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":14,"position":"长子帅师，","text":"长子谓二，震为长子，在师中，故“帅师”也。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":15,"position":"弟子舆尸，贞凶。","text":"弟子谓三。三体坎。坎震之弟而乾之子，失位乘阳，逆，故“贞凶”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":18,"position":"上六：大君有命，","text":"同人，乾为大君巽为有命。","locator":{"book":"周易集解","gua":"师","pos":"上六"},"citation":"《周易集解》·师卦·上六","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":19,"position":"开国承家，","text":"承，受也。坤为国。二称家。谓变乾为坤，欲令二上居五，为比，故“开国承家”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":20,"position":"小人勿用。","text":"阴称小人，坤虚无君，体迷复凶，坤成乾灭，以弑君，故“小人勿用”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":21,"position":"：大君有命，以正功也。","text":"谓五多功，五动正位，故“正功也”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"师","guaId":"g07","yaoIdx":22,"position":"小人勿用，必乱邦也。","text":"坤反君道，故“乱邦也”。","locator":{"book":"周易集解","gua":"师","pos":"卦辞·彖象"},"citation":"《周易集解》·师卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":-1,"position":"卦辞","text":"师二上之五，得位，众阴顺从，比而辅之，故“吉”。与大有旁通。","locator":{"book":"周易集解","gua":"比","pos":"卦辞"},"citation":"《周易集解》·比卦·卦辞","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":3,"position":"不宁方来，上下应也。","text":"水性流动，故“不宁”。坤阴为方，上下应之，故“方来”也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":4,"position":"后夫凶，","text":"后谓上，夫谓五也。坎为后，艮为背。上位在背后，无应乘阳，故“后夫凶”也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":7,"position":"先王以建万国，亲诸侯。","text":"先王谓五。初阳已复。震为建，为诸侯。坤为万国，为腹，坎为心。腹心亲比，故“以建万国，亲诸侯”。《诗》曰：公侯腹心，是其义也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":8,"position":"初六：有孚比之，无咎。","text":"孚谓五。初失位，变来得正，故“无咎”也。","locator":{"book":"周易集解","gua":"比","pos":"初六"},"citation":"《周易集解》·比卦·初六","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":9,"position":"有孚盈缶，终来有它，吉。","text":"坤器为缶。坎水流坤。初动成屯。屯者，盈也，故“盈缶”。终变得正，故“终来有它吉”。在内称来也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":13,"position":"六三：比之匪人。","text":"匪，非也，失位无应，三又多凶，体剥伤象，弑父弑君，故曰“匪人”。","locator":{"book":"周易集解","gua":"比","pos":"六三"},"citation":"《周易集解》·比卦·六三","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":15,"position":"六四：外比之，贞吉。","text":"在外体，故称外。得位比贤，故贞吉也。","locator":{"book":"周易集解","gua":"比","pos":"六四"},"citation":"《周易集解》·比卦·六四","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":17,"position":"九五：显比。","text":"五贵多功，得位正中，初三以变体重明，故“显比”。谓显诸仁也。","locator":{"book":"周易集解","gua":"比","pos":"九五"},"citation":"《周易集解》·比卦·九五","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":18,"position":"王用三驱，失前禽，","text":"坎五称王。三驱，谓驱下三阴，不及于初，故“失前禽”。谓初已变成震，震为鹿，为惊走，鹿之斯奔，则“失前禽”也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":19,"position":"邑人不戒，吉。","text":"坤为邑师，震为人师。时坤虚无君，使师二上居五中，故不诫吉也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":20,"position":"：显比之吉，位正中也。","text":"谓离象明。正上中也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":21,"position":"舍逆取顺，失前禽也。","text":"背上六，故“舍逆”。据三阴，故“取顺”。不及初，故“失前禽”。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":22,"position":"邑人不戒，上使中也。","text":"谓二，使师二上居五中。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":23,"position":"上六：比之无首，凶。","text":"首，始也。阴道无成，而代有终，“无首，凶”。","locator":{"book":"周易集解","gua":"比","pos":"上六"},"citation":"《周易集解》·比卦·上六","edition":"jijie"},{"gua":"比","guaId":"g08","yaoIdx":24,"position":"：比之无首，无所终也。","text":"迷失道，故无所终也。","locator":{"book":"周易集解","gua":"比","pos":"卦辞·彖象"},"citation":"《周易集解》·比卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":2,"position":"健而巽，刚中而志行，乃亨。","text":"需上变为巽，与豫旁通。豫四之坤初为复，复小阳潜，所畜者少，故曰“小畜”。二失位，五刚中正，二变应之，故“志行乃亨”也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":3,"position":"密云不雨，尚往也。","text":"密，小也。兑为密。需坎升天为云，坠地称雨。上变为阳，坎象半见。故“密云不雨，尚往也”。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":4,"position":"自我西郊，施未行也。","text":"豫坤为自我。兑为西，乾为郊，雨生于西，故“自我西郊”。九二未变，故“施未行”矣。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":6,"position":"君子以懿文德。","text":"君子，谓乾。懿，美也。豫坤为文。乾为德，离为明。初至四体夬，为书契。乾离照坤，故懿文德也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":7,"position":"初九：复自道，何其咎，吉。《象》曰：复自","text":"谓从豫四之初成复卦，故复自道。出入无疾，“朋来无咎，何其咎，吉。”乾称道也。","locator":{"book":"周易集解","gua":"小畜","pos":"初九"},"citation":"《周易集解》·小畜卦·初九","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":9,"position":"：牵复在中，亦不自失也。","text":"变应五，故不自失，与比二同义也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":10,"position":"九三：车说辐，","text":"豫、坤为车，为辐。至三成乾，坤象不见，故“车说辐”。马君及俗儒皆以乾为车，非也。","locator":{"book":"周易集解","gua":"小畜","pos":"九三"},"citation":"《周易集解》·小畜卦·九三","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":11,"position":"夫妻反目。","text":"豫震为夫，为反。巽为妻。离为目。今夫妻共在四，离火动上，目象不正，巽多白眼，夫妻反目。妻当在内，夫当在外，今妻乘夫而出在外，象曰“不能正室”。三体离需，饮食之道。饮食有讼，故争而反目也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":13,"position":"六四：有孚，血去惕出，无咎。","text":"孚谓五。豫坎为血，为惕。惕，忧也。震为出，变成小畜，坎象不见，故血去惕出。得位承五，故“无咎”也。","locator":{"book":"周易集解","gua":"小畜","pos":"六四"},"citation":"《周易集解》·小畜卦·六四","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":15,"position":"九五：有孚挛如，富以其邻。","text":"孚五，谓二也。挛，引也。巽为绳。豫、艮为手。二失位，五欲其变，故曰“挛如”。以，及也。五贵，称富。邻，谓三。兑西震东，称邻。二变承三，故富以其邻，《象》曰“不独富”。二变为既济，与东西邻同义。","locator":{"book":"周易集解","gua":"小畜","pos":"九五"},"citation":"《周易集解》·小畜卦·九五","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":17,"position":"上九：既雨既处，尚得载，妇贞厉。","text":"既，已也。应在三。坎水零雨。巽为处，谓二已变，三体坎雨，故“既雨既处”。坎云复天，坎为车，积载在坎上，故上得积载。巽为妇，坎成巽坏，故“妇贞厉”。","locator":{"book":"周易集解","gua":"小畜","pos":"上九"},"citation":"《周易集解》·小畜卦·上九","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":18,"position":"月几望，君子征凶。","text":"几，近也。坎月离日，上已正，需时成坎，与离相望。兑西震东，日月象对，故“月几望”。上变阳消，之坎为疑，故“君子征，有所疑”矣。与归妹、中孚“月几望”义同也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":19,"position":"：既雨既处，得积载也。","text":"巽消承坎，故“得积载”。坎习为积也。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"小畜","guaId":"g09","yaoIdx":20,"position":"君子征凶，有所疑也。","text":"变坎为盗，故“有所疑也”。","locator":{"book":"周易集解","gua":"小畜","pos":"卦辞·彖象"},"citation":"《周易集解》·小畜卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":-1,"position":"卦辞","text":"谓变讼初为兑也。与谦旁通。以坤履乾，以柔履刚，谦坤为虎，艮为尾，乾为人，乾兑乘谦，震足蹈艮，故“履虎尾”。兑说而应虎口，与上绝，故“不咥人”。刚当位，故通。俗儒皆以兑为虎，乾履兑，非也。兑刚卤，非柔也。","locator":{"book":"周易集解","gua":"履","pos":"卦辞"},"citation":"《周易集解》·履卦·卦辞","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":0,"position":"：履，柔履刚也。","text":"坤柔乾刚，谦坤籍乾，故“柔履刚”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":1,"position":"说而应乎乾，","text":"说，兑也。明兑不履乾，故言应也。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":3,"position":"刚中正，履帝位而不疚，光明也。","text":"刚中正，谓五。谦震为帝。五，帝位，坎为疾病，乾为大明。五履帝位，坎象不见。故“履帝位而不疚，光明也”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":4,"position":"：上天下泽，履。君子以辩上下，定民志。","text":"君子，谓乾。辩，别也。乾天为上，兑泽为下。谦坤为民，坎为志。谦时坤在乾上，变而为履。故“辩上下，定民志也”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":5,"position":"初九：素履，往无咎。","text":"应在巽，为白，故“素”。履四失位，变往得正，故“往无咎”。初已得正，使四独变，在外称往。《象》曰：“独行愿也”。","locator":{"book":"周易集解","gua":"履","pos":"初九"},"citation":"《周易集解》·履卦·初九","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":7,"position":"九二：履道坦坦，幽人贞吉。","text":"二失位。变成震，为道、为大涂，故“履道坦坦”。讼时二在坎狱中，故称幽人。之正得位，震出兑说，幽人喜笑，故“贞吉”也。","locator":{"book":"周易集解","gua":"履","pos":"九二"},"citation":"《周易集解》·履卦·九二","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":8,"position":"：幽人贞吉，中不自乱也。","text":"虽幽讼狱中，终辩得正，故“不自乱”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":9,"position":"六三：眇而视，跛而履，","text":"离目不正，兑为小，故“眇而视”。视上应也。讼坎为曳。变震时，为足。足曳，故跛而履。俗儒多以兑刑为跛，兑折震足，为刑人见刑断足者，非为跛也。","locator":{"book":"周易集解","gua":"履","pos":"六三"},"citation":"《周易集解》·履卦·六三","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":10,"position":"履虎尾，咥人，凶。","text":"艮为尾，在兑下，故“履虎尾”。位在虎口中，故“咥人凶”。既跛又眇，视步不能，为虎所啮，故“咥人凶”。《象》曰：“位不当也”。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":11,"position":"武人为于大君。","text":"乾象在上，为武人。三失位，变而得正，成乾。故曰“武人为于大君”。志刚也。","locator":{"book":"周易集解","gua":"履","pos":"卦辞·彖象"},"citation":"《周易集解》·履卦·卦辞·彖象","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":15,"position":"九四：履虎尾，愬愬，终吉。","text":"体与下绝，四多惧，故“愬愬”。变体坎，得位，承五应初，故终吉。《象》曰：“志行也”。","locator":{"book":"周易集解","gua":"履","pos":"九四"},"citation":"《周易集解》·履卦·九四","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":17,"position":"九五：夬履，贞厉。","text":"谓三。上已变，体夬象，故“夬履”。四变五，在坎中也，为上所乘，故“贞厉”。《象》曰：“位正当也”。","locator":{"book":"周易集解","gua":"履","pos":"九五"},"citation":"《周易集解》·履卦·九五","edition":"jijie"},{"gua":"履","guaId":"g10","yaoIdx":19,"position":"上九：视履考详，其旋元吉。","text":"应在三，三先视上，故上亦视三。故曰“视履考详”矣。考，稽。详，善也。乾为积善，故“考详”。三上易位，故“其旋元吉”。《象》曰：“大有庆也”。","locator":{"book":"周易集解","gua":"履","pos":"上九"},"citation":"《周易集解》·履卦·上九","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":-1,"position":"卦辞","text":"阳息坤反，否也。坤阴诎外，为小往。乾阳信内，称大来。天地交，万物通，故“吉、亨”。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞"},"citation":"《周易集解》·泰卦·卦辞","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":7,"position":"后以财成天地之道，","text":"后，君也。阴升乾位。坤，女主，故称后。坤富，称财。守位以人，聚人以财，故曰“成天地之道”。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":8,"position":"辅相天地之宜，以左右民。","text":"相，赞。左右，助之。震为左，兑为右，坤为民，谓以阴辅阳。《诗》曰：宜民宜人，受禄于天。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":10,"position":"：拔茅征吉，志在外也。","text":"否泰反其类，否巽为茅。茹，茅根。艮为手。汇，类也。初应四，故拔茅茹以汇。震为征，得位应四，征吉。外，谓四也。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":14,"position":"：包荒，得尚于中行，以光大也。","text":"在中称包。荒，大川也。冯河，涉河。遐，远；遗，亡也。失位变得正，体坎。坎为大川，为河。震为足。故“用冯河”。乾为远，故“不遐遗”。兑为朋，坤虚无君，欲使二上，故“朋亡”。二与五易位，故得上于中行。震为行，故“光大也”。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":15,"position":"九三：无平不陂，无往不复。","text":"陂，倾。谓否上也。平，谓三。天地分，故平。天成地平，谓危者使平，易者使倾。往，谓消外。复，谓息内。从三至上，体复。终日乾乾，反复道。故“无平不陂，无生不复”。","locator":{"book":"周易集解","gua":"泰","pos":"九三"},"citation":"《周易集解》·泰卦·九三","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":16,"position":"艰贞无咎。勿恤其孚，于食有福。","text":"艰，险。贞，正。恤，忧。孚，信也。二之五，得正，在坎中，故“艰贞”。坎为忧。故“勿恤”。阳在五孚，险坎为孚，故有孚。体噬嗑食也。二上之五据四，则三乘二。故“于食有福”也。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":18,"position":"六四：翩翩，不富以其邻，","text":"二五变时，四体离飞，故“翩翩”。坤虚无阳，故“不富”。兑西震东，故称“其邻”。三阴乘阳，不得之应。《象》曰：“皆失实也。”","locator":{"book":"周易集解","gua":"泰","pos":"六四"},"citation":"《周易集解》·泰卦·六四","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":19,"position":"不戒以孚。","text":"谓坤。邑人不戒，故使二升五，信来孚邑，故“不戒以孚”。二上体坎，中正。《象》曰：“中心愿也。”与比邑人不诫同义也。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":22,"position":"六五：帝乙归妹，以祉元吉。","text":"震为帝，坤为乙。帝乙，纣父。归嫁也。震为兄，兑妹，故嫁妹。祉，福也。谓五变体离，离为大腹，则妹嫁而孕，得位正中，故“以祉元吉”也。","locator":{"book":"周易集解","gua":"泰","pos":"六五"},"citation":"《周易集解》·泰卦·六五","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":24,"position":"上六：城复于隍，","text":"否艮为城，故称城坤为积土。隍，城下沟。无水称隍，有水称池。今泰反否，乾坏为土，艮城不见，而体复象，故“城复于隍”也。","locator":{"book":"周易集解","gua":"泰","pos":"上六"},"citation":"《周易集解》·泰卦·上六","edition":"jijie"},{"gua":"泰","guaId":"g11","yaoIdx":25,"position":"勿用师，自邑告命，贞吝。","text":"谓二，动时体师。阴皆乘阳，行不顺，故“勿用师”。坤为自邑，震为言，兑为口，否巽为命。今逆陵阳，故“自邑告命”。命逆不顺，阴道先迷，失实远应，故“贞吝”。","locator":{"book":"周易集解","gua":"泰","pos":"卦辞·彖象"},"citation":"《周易集解》·泰卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":-1,"position":"卦辞","text":"阴消乾，又反泰也。谓三。比坤灭乾，以臣弑其君子弑其父，故曰“匪人”。阴来灭阳，君子道消，故“不利君子贞”。阴信阳诎，故“大往小来”。则是天地不交而万物不通，与比三同义也。","locator":{"book":"周易集解","gua":"否","pos":"卦辞"},"citation":"《周易集解》·否卦·卦辞","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":7,"position":"君子以俭德辟难，不可荣以禄。","text":"君子谓乾，坤为营，乾为禄，难谓坤为弑君故以“俭德辟难”。巽为入伏，乾为远，艮为山，体遁象，谓辟难远遁入山，故“不可营以禄”。营，或作荣。俭，或作险。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":11,"position":"：大人否享，不乱群也。","text":"否，不也”物三称群，谓坤三阴乱弑君，大人不从，故“不乱群”也。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"否","guaId":"g12","yaoIdx":20,"position":"：否终则倾，何可长也。","text":"否终必倾，盈不可久，故“先否”。下反于初，成益，体震，民说无疆，故“后喜”。以阴剥阳，故不可久也。","locator":{"book":"周易集解","gua":"否","pos":"卦辞·彖象"},"citation":"《周易集解》·否卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":2,"position":"柔得位得中，而应乎乾，曰同人。","text":"旁通师卦。巽为同，乾为野。师震为人。二得中应乾。故曰“同人于野，亨”。此孔子所以明嫌表微。师震为夫，巽为妇，所谓二人同心。故不称君臣、父子、兄弟、朋友，而故言人耳。乾四上失位，变而体坎，故曰“利涉大川，乾行也”。","locator":{"book":"周易集解","gua":"同人","pos":"卦辞·彖象"},"citation":"《周易集解》·同人卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":4,"position":"唯君子为能通天下之志。","text":"唯，独也。四变成坎。坎为通、为志。故“能通天下之志”。谓五以类族辩物，圣人作而万物睹。","locator":{"book":"周易集解","gua":"同人","pos":"卦辞·彖象"},"citation":"《周易集解》·同人卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":6,"position":"君子以类族辩物。","text":"君子谓乾。师坤为类，乾为族。辩，别也。乾，阳物。坤，阴物。体姤，天地相遇，品物咸章，以乾照坤。故“以类族辩物”。谓方以类聚，物以群分。孔子曰：君子和而不同，故于同人象见，以“类族辩物”也。","locator":{"book":"周易集解","gua":"同人","pos":"卦辞·彖象"},"citation":"《周易集解》·同人卦·卦辞·彖象","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":7,"position":"初九：同人于门，无咎。","text":"乾为门，谓同于四，四变应初，故“无咎”也。","locator":{"book":"周易集解","gua":"同人","pos":"初九"},"citation":"《周易集解》·同人卦·初九","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":11,"position":"九三：伏戎于莽，升其高陵，三岁不兴。","text":"巽为伏，震为草莽，离为戎。谓四变时三在坎中，隐伏自藏，故“伏戎于莽”也。巽为高，师震为陵，以巽股升其高陵。爻在三。乾为岁。兴，起也。动不失位，故“三岁不兴”也。","locator":{"book":"周易集解","gua":"同人","pos":"九三"},"citation":"《周易集解》·同人卦·九三","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":13,"position":"九四：乘其庸，弗克攻，吉。","text":"巽为庸，四在巽上，故“乘其庸”。变而承五。体讼，乾刚在上。故“弗克攻”，则“吉”也。","locator":{"book":"周易集解","gua":"同人","pos":"九四"},"citation":"《周易集解》·同人卦·九四","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":15,"position":"九五：同人先号咷而后笑，大师克相遇。","text":"应在二。巽为号咷，乾为先，故“先号咷”。师震在下，故“后笑”。震为后笑也。乾为大，同人反师，故“大师”。二至五，体姤遇也，故“相遇”。","locator":{"book":"周易集解","gua":"同人","pos":"九五"},"citation":"《周易集解》·同人卦·九五","edition":"jijie"},{"gua":"同人","guaId":"g13","yaoIdx":17,"position":"上九：同人于郊，无悔。","text":"乾为郊。失位无应，与乾上九同义，当有悔。同心之家。故“无悔”。","locator":{"book":"周易集解","gua":"同人","pos":"上九"},"citation":"《周易集解》·同人卦·上九","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":-1,"position":"卦辞","text":"与比旁通。柔得尊位大中，应天而时行，故“元亨”也。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞"},"citation":"《周易集解》·大有卦·卦辞","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":1,"position":"其德刚健而文明，应乎天而时行，是以元亨。","text":"谓五，以日应乾而行于天也。时，谓四时也。大有亨。比初动成震为春；至二，兑为秋。至三，离为夏。坎为冬。故曰“时行”。以乾亨坤，是以“元亨”。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":3,"position":"君子以遏恶扬善，顺天休命。","text":"遏，绝。扬，举也。乾为扬善，坤为遏恶，为顺。以乾灭坤。体夬，扬于王庭。故“遏恶扬善”。乾为天休，二变时，巽为命，故“顺天休命”。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":4,"position":"初九：无交害，匪咎，艰则无咎。","text":"害谓四。四离火，为恶人，故“无交害”。初动，震为交。比坤为害。匪，非也。艰，难，谓阳动比初成屯。屯，难也。变得位，艰则无咎。","locator":{"book":"周易集解","gua":"大有","pos":"初九"},"citation":"《周易集解》·大有卦·初九","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":5,"position":"：大有初九，无交害也。","text":"害，谓四。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":6,"position":"九二：大车以载，有攸往，无咎。","text":"比坤为大车，乾来积上，故“大车以载”。往，谓之五。二失位，变得正应五。故“有攸往无咎”矣。","locator":{"book":"周易集解","gua":"大有","pos":"九二"},"citation":"《周易集解》·大有卦·九二","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":8,"position":"九三：公用亨于天子，小人弗克。","text":"天子谓五。三，公位也。小人谓四。二变得位，体鼎象。故“公用亨于天子”。四折鼎足，覆公餗，故小人不克也。","locator":{"book":"周易集解","gua":"大有","pos":"九三"},"citation":"《周易集解》·大有卦·九三","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":9,"position":"：公用亨于天子，小人害也。","text":"小人，谓四也。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":10,"position":"九四，匪其尫，无咎。","text":"匪，非也。其位尫。足尫，体行不正，四失位，折震足，故“尫”。变而得正，故“无咎”。尫或作彭，作旁声，字之误。","locator":{"book":"周易集解","gua":"大有","pos":"九四"},"citation":"《周易集解》·大有卦·九四","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":11,"position":"：匪其尫，无咎，明辩折也。","text":"折之离，故“明辩折也”。四在乾则尫；在坤为鼠；在震噬用胏得金矢；在巽折鼎足，在坎为鬼方；在离焚死；在艮旅于处，言无所容；在兑睽孤孚厉。三百八十四爻，独无所容也。","locator":{"book":"周易集解","gua":"大有","pos":"卦辞·彖象"},"citation":"《周易集解》·大有卦·卦辞·彖象","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":12,"position":"六五：厥孚交如，威如吉。","text":"孚，信也。发而孚二，故“交加”。乾称威，发得位，故“威如吉”。","locator":{"book":"周易集解","gua":"大有","pos":"六五"},"citation":"《周易集解》·大有卦·六五","edition":"jijie"},{"gua":"大有","guaId":"g14","yaoIdx":14,"position":"上九：自天右之，吉，无不利。","text":"谓乾也。右，助也。大有通比，坤为自，乾为天，兑为右，故“自天右之”。比坤为顺，乾为信。天之所助者顺，人之所助者信。履信思顺，又以尚贤，故“自天右之，吉无不利”。","locator":{"book":"周易集解","gua":"大有","pos":"上九"},"citation":"《周易集解》·大有卦·上九","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":-1,"position":"卦辞","text":"乾上九来之坤，与履旁通。天道下济，故亨。彭城蔡景君说：剥上来之三。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞"},"citation":"《周易集解》·谦卦·卦辞","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":0,"position":"君子有终。","text":"君子谓三。艮终万物，故“君子有终”。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":4,"position":"天道亏盈而益谦，","text":"谓乾盈履上，亏之坤三，故“亏盈”。贵处贱位，故“益谦”。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":5,"position":"地道变盈而流谦，","text":"谦二以坤变乾盈。坎动而润下，水流湿，故“流谦”也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":6,"position":"鬼神害盈而福谦，","text":"鬼谓四。神谓三。坤为鬼害，乾为神福，故“鬼神害盈而福谦”也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":7,"position":"人道恶盈而好谦。","text":"乾为好，为人。坤为恶也。故人道恶盈。从上之三，故“好谦”矣。崔觐曰：满招损，谦受益，人之道也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":8,"position":"谦，尊而光，卑而不可逾，","text":"天道远，故“尊光”。三位贱，故“卑”。坎水就下，险弱难胜，故“不可逾”。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":11,"position":"君子以捋多益寡，称物平施。","text":"君子谓三。捋，取也。艮为多；坤为寡；乾为物，为施；坎为平。谦乾盈益谦，故“以捋多益寡，称物平施”。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":15,"position":"：鸣谦贞吉，中心得也。","text":"中正谓二。坎为心也。","locator":{"book":"周易集解","gua":"谦","pos":"卦辞·彖象"},"citation":"《周易集解》·谦卦·卦辞·彖象","edition":"jijie"},{"gua":"谦","guaId":"g15","yaoIdx":23,"position":"上六：鸣谦，利用行师，征邑国。","text":"应在震，故曰“鸣谦”。体师象，震为行，坤为邑国，利五之正，已得从征，故“利用行师，征邑国”。","locator":{"book":"周易集解","gua":"谦","pos":"上六"},"citation":"《周易集解》·谦卦·上六","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":-1,"position":"卦辞","text":"复初之四，与小畜旁通。坤为邦国，震为诸侯。初至五，体比象。四利复初，故“利建侯”。三至上，体师象，故“行师”。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞"},"citation":"《周易集解》·豫卦·卦辞","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":3,"position":"豫顺以动，故天地如之，","text":"小畜，乾为天。坤为地。如之者，谓天地亦动，以成四时，而况建侯行师。言其皆应而豫也。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":5,"position":"天地以顺动，","text":"豫变通小畜。坤为地。动初至三成乾，故天地以顺动也。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":6,"position":"故日月不过，而四时不忒。","text":"过谓失度，忒，差迭也。谓变初至需，离为日，坎为月，皆得其正，故“日月不过”。动初时，震为春。至四，兑为秋。至五，坎为冬。离为夏。四时位正，故“四时不忒”。通变之谓事，盖此之类。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":7,"position":"圣人以顺动，则刑罚清而民服。","text":"清，犹明也。动初至四，兑为刑。至坎，为罚。坎、兑体正，故“刑罚清”。坤为民，乾为清，以乾乘坤，故“民服”。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":8,"position":"豫之时义大矣哉。","text":"顺动天地，使日月四时，皆不过差。刑罚清而民服，故“义大”也。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":11,"position":"初六：鸣豫，凶。","text":"应震善鸣，失位，故“鸣豫，凶”也。","locator":{"book":"周易集解","gua":"豫","pos":"初六"},"citation":"《周易集解》·豫卦·初六","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":12,"position":"：初六鸣豫，志穷凶也。","text":"体剥蔑贞，故“志穷凶也”。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":13,"position":"六二：介于石，","text":"介，纤也。与四为艮，艮为石，故“介于石”。","locator":{"book":"周易集解","gua":"豫","pos":"六二"},"citation":"《周易集解》·豫卦·六二","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":14,"position":"不终日，贞吉。","text":"与小畜通，应在五。终变成离，离为日，得位。欲四争复初，已得休之。故“不终日，贞吉”。","locator":{"book":"周易集解","gua":"豫","pos":"卦辞·彖象"},"citation":"《周易集解》·豫卦·卦辞·彖象","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":17,"position":"九四：由豫，大有得，勿疑，朋盍戠。","text":"由，自从也。据有五阴，坤以众顺，故“大有得”。得群阴也。坎为疑，故“勿疑”。小畜兑为朋。盍，合也，坤为盍。戠，聚会也。坎为聚，坤为众，众阴并应，故“朋盍戠”。戠，旧读作撍，作宗也。","locator":{"book":"周易集解","gua":"豫","pos":"九四"},"citation":"《周易集解》·豫卦·九四","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":19,"position":"六五：贞疾，恒不死。","text":"恒，常也。坎为疾。应在坤，坤为死。震为反生。位在震中，与坤体绝。故“贞疾，恒不死”也。","locator":{"book":"周易集解","gua":"豫","pos":"六五"},"citation":"《周易集解》·豫卦·六五","edition":"jijie"},{"gua":"豫","guaId":"g16","yaoIdx":21,"position":"上六：冥豫，成有渝，无咎。","text":"应在三。坤为冥。渝，变也。三失位，无应，多凶。变乃得正，体艮成。故“成有渝，无咎”。","locator":{"book":"周易集解","gua":"豫","pos":"上六"},"citation":"《周易集解》·豫卦·上六","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":-1,"position":"卦辞","text":"否上之初，刚来下柔，初上得正，故“元、享、利、贞，无咎”。","locator":{"book":"周易集解","gua":"随","pos":"卦辞"},"citation":"《周易集解》·随卦·卦辞","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":0,"position":"：随，刚来而下柔，动而说，随。","text":"否乾上来之坤初，故“刚来而下柔”。动，震，说，兑也。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":2,"position":"而天下随时，","text":"乾为天，坤为下，震春兑秋。三四之正，坎冬离夏。四时位正，时行则行，故“天下随时”矣。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":8,"position":"六二：系小子，失丈夫。","text":"应在巽。巽为绳，故称系。小子谓五，兑为少，故曰“小子”。丈夫谓四，体大过老夫，故称“丈夫”。承四隔三，故“失丈夫”。三至上，有大过象，故与老妇、士夫同义。体咸象，夫死大过，故每有欲嫁之义也。","locator":{"book":"周易集解","gua":"随","pos":"六二"},"citation":"《周易集解》·随卦·六二","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":9,"position":"：系小子，弗兼与也。","text":"已系于五，不兼与四也。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":10,"position":"六三：系丈夫，失小子，随有求，得。利居贞","text":"随家阴随阳，三之上无应。上系于四，失初小子，故“系丈夫，失小子”艮为居、为求，谓求之正。得位远应，利上承四，故“利居贞”矣。","locator":{"book":"周易集解","gua":"随","pos":"六三"},"citation":"《周易集解》·随卦·六三","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":12,"position":"九四：随有获，贞凶。有孚在道，以明，何咎","text":"谓获三也，失位相据，在大过，死象，故“贞凶”。《象》曰：“其义凶矣”。孚谓五。初震为道。三已之正，四变应初，得位在离。故“有孚在道，以明，何咎”。《象》曰：“明功也”。","locator":{"book":"周易集解","gua":"随","pos":"九四"},"citation":"《周易集解》·随卦·九四","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":13,"position":"：随有获，其义凶也。","text":"死在大过，故“凶也”。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":14,"position":"有孚在道，明功也。","text":"功谓五也。三四之正，离为明，故“明功也”。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":15,"position":"九五：孚于嘉吉。","text":"坎为孚，阳称嘉，位五正，故“吉”也。","locator":{"book":"周易集解","gua":"随","pos":"九五"},"citation":"《周易集解》·随卦·九五","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":16,"position":"：孚于嘉，吉，位正中也。","text":"凡五言中正，中正皆阳得其正，以此为例矣。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":17,"position":"上六：拘系之，乃从维之。","text":"应在艮。艮手为拘，巽为绳，两系称维，故“拘系之，乃从维之”。在随之上，而无所随，故维之。《象》曰“上穷”。是其义也。","locator":{"book":"周易集解","gua":"随","pos":"上六"},"citation":"《周易集解》·随卦·上六","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":18,"position":"王用亨于西山。","text":"否乾为王，谓五也。有观象，故“亨”。兑为西，艮为山，故“王用亨于西山”也。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"随","guaId":"g17","yaoIdx":19,"position":"：拘系之，上穷也。","text":"乘刚无应，故“上穷也”。","locator":{"book":"周易集解","gua":"随","pos":"卦辞·彖象"},"citation":"《周易集解》·随卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":-1,"position":"卦辞","text":"泰初之上，与随旁通。刚上柔下，乾坤交，故“元亨”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞"},"citation":"《周易集解》·蛊卦·卦辞","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":0,"position":"利涉大川。","text":"谓二失位，动而之坎也，故“利涉大川”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":3,"position":"：蛊，刚上而柔下，巽而止，蛊。","text":"泰初之上，故“刚上”；坤上之初，故“柔下”。上艮下巽，故“巽而止蛊”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":6,"position":"先甲三日，后甲三日，终则有始，天行也。","text":"谓初变成乾，乾为甲。至二成离，离为日。谓乾三爻在前，故“先甲三日”。贲，时也。变三至四，体离。至五成乾，乾三爻在后，故“后甲三日”。无妄，时也。易出震，消息历乾坤象。乾为始，坤为终，故“终则有始”。乾为天。震为行，故“天行”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":8,"position":"君子以振民育德。","text":"君子，谓泰乾也。坤为民。初上抚坤，故“振民”。乾称德，体大畜，须养，故以“育德”也。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":9,"position":"初六：干父之蛊，有子考，无咎。厉，终吉。","text":"干，正。蛊，事也。泰乾为父，坤为事。故“干父之蛊”。初上易位，艮为子，父死大过称考，故“有子考”。变而得正，故“无咎。厉，终吉”也。","locator":{"book":"周易集解","gua":"蛊","pos":"初六"},"citation":"《周易集解》·蛊卦·初六","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":11,"position":"九二：干母之蛊，不可贞。《象》曰：干母之","text":"应在五。泰坤为母，故干母之蛊。失位。故“不可贞”。变而得正，故贞而“得中道也”。","locator":{"book":"周易集解","gua":"蛊","pos":"九二"},"citation":"《周易集解》·蛊卦·九二","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":13,"position":"六四：裕父之蛊，往见吝。","text":"裕，不能争也。孔子曰：父有争子，则身不陷于不义。四阴体大过，本末弱，故“裕父之蛊”。兑为见，变而失正，故“往见吝”。《象》曰：“往未得”。是其义也。","locator":{"book":"周易集解","gua":"蛊","pos":"六四"},"citation":"《周易集解》·蛊卦·六四","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":14,"position":"：裕父之蛊，往未得也。","text":"往失位，折鼎足，故“未得”。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":16,"position":"：干父用誉，承以德也。","text":"誉，谓二也。二五失位，变而得正，故“用誉”。变二使承五，故承以德。二乾爻，故称“德”矣。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":17,"position":"上九：不事王侯，","text":"泰乾为王，坤为事。应在于三。震为侯，坤象不见，故“不事王侯”。","locator":{"book":"周易集解","gua":"蛊","pos":"上九"},"citation":"《周易集解》·蛊卦·上九","edition":"jijie"},{"gua":"蛊","guaId":"g18","yaoIdx":18,"position":"高尚其事。","text":"谓五已变，巽为高，艮阳升在坤上，故“高尚其事”。","locator":{"book":"周易集解","gua":"蛊","pos":"卦辞·彖象"},"citation":"《周易集解》·蛊卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":-1,"position":"卦辞","text":"阳息至二，与遁旁通。刚浸而长，乾来交坤，动则成乾，故“元、亨、利、贞”。","locator":{"book":"周易集解","gua":"临","pos":"卦辞"},"citation":"《周易集解》·临卦·卦辞","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":0,"position":"至于八月有凶。","text":"与遁旁通，临消于遁，六月卦也。于周为八月。遁弑君父，故“至于八月有凶”。荀公以兑为八月，兑于周为十月。言八月，失之甚矣。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":1,"position":"：临，刚浸而长。","text":"刚，谓二也。兑为水泽，自下浸上，故“浸而长”也。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":2,"position":"说而顺，刚中而应。大亨以正，天之道也。","text":"说，兑。顺，坤也。刚中，谓二也。四阴皆应之，故曰“而应”。大享以正，谓三动成乾。天得正为泰，天地交通。故“亨以正，天之道也”。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":5,"position":"君子以教思无穷，容保民无疆。","text":"君子，谓二也。震为言，兑口讲习。学以聚之，问以辩之。坤为思，刚浸长，故“以教思无穷”。容，宽也。二宽以居之，仁以行之；坤为容，为民，故“保民无疆”矣。","locator":{"book":"周易集解","gua":"临","pos":"卦辞·彖象"},"citation":"《周易集解》·临卦·卦辞·彖象","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":6,"position":"初九：咸临，贞吉。","text":"咸，感也。得正应四，故“贞吉”也。","locator":{"book":"周易集解","gua":"临","pos":"初九"},"citation":"《周易集解》·临卦·初九","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":8,"position":"九二：咸临，吉，无不利。","text":"得中多誉。兼有四阴。体复初。元吉。故“无不利”。","locator":{"book":"周易集解","gua":"临","pos":"九二"},"citation":"《周易集解》·临卦·九二","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":10,"position":"六三：甘临，无攸利，既忧之，无咎。《象》","text":"兑为口，坤为土，土爰稼穑作甘。兑口衔坤，故曰“甘临”。失位乘阳，故“无攸利”。言三失位无应，故“忧之”。动而成泰，故“咎不可长也”。","locator":{"book":"周易集解","gua":"临","pos":"六三"},"citation":"《周易集解》·临卦·六三","edition":"jijie"},{"gua":"临","guaId":"g19","yaoIdx":11,"position":"六四：至临，无咎。","text":"至，下也。谓下至初，应当位，有实，故“无咎”。","locator":{"book":"周易集解","gua":"临","pos":"六四"},"citation":"《周易集解》·临卦·六四","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":1,"position":"顺而巽，中正以观天下。","text":"谓阳息临二，直方大。临者，大也。在观上，故称“大观”。顺，坤也。中正谓五。五以天神道观示天下，咸服其化，宾于王庭。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":2,"position":"观，盥而不荐，有孚颙若，下观而化也。","text":"观，反临也。以五阳观示坤民，故称“观”。盥，沃盥。荐，羞牲也。孚，信，谓五。颙颙，君德，有威容貌。若，顺也。坎为水，坤为器，艮手临坤，坎水沃之，盥之象也。故“观盥而不荐”。孔子曰：谛自既灌，吾不欲观之矣。巽为进退，容止可观，进退可度，则下观其德而顺其化。上之三，五在坎中，故“有孚颙若，下观而化”。《诗》曰：颙颙卬卬，如珪如璋。君德之义也。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":3,"position":"观天之神道，而四时不忒。","text":"忒，差也。神道谓五。临，震兑为春秋，三上易位，坎冬离夏，日月象正。故“四时不忒”。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":4,"position":"圣人神道设教，而天下服矣。","text":"圣人谓乾，退藏于密，而齐于巽，以神明其德教，故“圣人设教”，坤民顺从，而天下服矣。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":6,"position":"初六：童观，小人无咎，君子吝。","text":"艮为童。阴，小人。阳，君子。初位贱，以小人承君子，故“无咎”。阳伏阴下，故“君子吝”矣。","locator":{"book":"周易集解","gua":"观","pos":"初六"},"citation":"《周易集解》·观卦·初六","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":8,"position":"六二：窥观，利女贞。","text":"临兑为女。窃观称窥兑女反成巽。巽四五得正，故“利女贞”。艮为宫室，坤为阖户，小人而应五。故“窥观女贞利”，不淫视也。","locator":{"book":"周易集解","gua":"观","pos":"六二"},"citation":"《周易集解》·观卦·六二","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":10,"position":"六三：观我生，进退。","text":"坤为我，临震为生。生，谓坤生民也；巽为进退，故“观我生进退”。临震进之五，得正居中，故《象》曰“未失道”。","locator":{"book":"周易集解","gua":"观","pos":"六三"},"citation":"《周易集解》·观卦·六三","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":12,"position":"六四：观国之光，利用宾于王。","text":"坤为国。临阳至二，天下文明。反上成观，进显天位，故“观国之光”。王谓五阳。阳尊宾坤。坤为用、为臣，四在王庭，宾事于五。故“利用宾于王”矣。《诗》曰：莫敢不来宾，莫敢不来王。是其义也。","locator":{"book":"周易集解","gua":"观","pos":"六四"},"citation":"《周易集解》·观卦·六四","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":14,"position":"九五：观我生，君子无咎。","text":"我，身也，谓我生。生，谓生民。震生象。反坤，为死丧。嫌非生民，故不言民。阳为君子，在临二，失位之五，得道处中，故“君子无咎”矣。","locator":{"book":"周易集解","gua":"观","pos":"九五"},"citation":"《周易集解》·观卦·九五","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":15,"position":"：观我生，观民也。","text":"坤为民，谓三也。坤体成，故观民也。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":16,"position":"上九：观其生，君子无咎。","text":"应在三，三体临震，故“观其生”。君子谓三，之三得正，故“无咎”矣。","locator":{"book":"周易集解","gua":"观","pos":"上九"},"citation":"《周易集解》·观卦·上九","edition":"jijie"},{"gua":"观","guaId":"g20","yaoIdx":17,"position":"：观其生，志未平也。","text":"坎为志，为平，上来之三，故“志未平”矣。","locator":{"book":"周易集解","gua":"观","pos":"卦辞·彖象"},"citation":"《周易集解》·观卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":-1,"position":"卦辞","text":"否五之坤初，坤初之五，刚柔交，故“亨”也。坎为狱，艮为手，离为明，四以不正，而系于狱。上当之三，蔽四成丰，折狱致刑，故“利用狱”。坤为用也。","locator":{"book":"周易集解","gua":"噬嗑","pos":"卦辞"},"citation":"《周易集解》·噬嗑卦·卦辞","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":0,"position":"：颐中有物，曰噬嗑。","text":"物谓四，则所噬干脯也。颐中无物，则口不噬。故先举“颐中有物曰噬嗑”也。","locator":{"book":"周易集解","gua":"噬嗑","pos":"卦辞·彖象"},"citation":"《周易集解》·噬嗑卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":6,"position":"初九：屦校灭趾，无咎。","text":"屦，贯。趾，足也。震为足，坎为校；震没坎下，故“屦校灭趾”。初位得正，故“无咎”。","locator":{"book":"周易集解","gua":"噬嗑","pos":"初九"},"citation":"《周易集解》·噬嗑卦·初九","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":7,"position":"：屦校灭趾，不行也。","text":"否坤小人。以阴消阳，其亡其亡。故五变灭初，否坤杀不行也。干宝曰：不敢遂行强也。","locator":{"book":"周易集解","gua":"噬嗑","pos":"卦辞·彖象"},"citation":"《周易集解》·噬嗑卦·卦辞·彖象","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":8,"position":"六二：噬肤灭鼻，无咎。","text":"噬，食也。艮为肤，为鼻；鼻没坎水中，隐藏不见，故“噬肤灭鼻”。乘刚，又得正多誉，故“无咎”。","locator":{"book":"周易集解","gua":"噬嗑","pos":"六二"},"citation":"《周易集解》·噬嗑卦·六二","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":10,"position":"六三：噬昔肉，遇毒，小吝，无咎。","text":"三在肤里，故称肉。离日 之，为昔；坎为毒，故“噬昔肉遇毒”。毒谓矢毒也。失位承四，故“小吝”。与上易位，利用狱成丰，故“无咎”也。","locator":{"book":"周易集解","gua":"噬嗑","pos":"六三"},"citation":"《周易集解》·噬嗑卦·六三","edition":"jijie"},{"gua":"噬嗑","guaId":"g21","yaoIdx":13,"position":"六五：噬干肉，得黄金，贞厉，无咎。","text":"阴称肉，位当离，日中烈，故干肉也。干金黄，故“得黄金”。贞，正。厉，危也。变而得正，故“无咎”。","locator":{"book":"周易集解","gua":"噬嗑","pos":"六五"},"citation":"《周易集解》·噬嗑卦·六五","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":-1,"position":"卦辞","text":"泰上之乾二，乾二之坤上，柔来文刚，阴阳交，故“亨”也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞"},"citation":"《周易集解》·贲卦·卦辞","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":0,"position":"小利有攸往。","text":"小谓五。五失正，动得位。体离，以刚文柔。故“小利有攸往”。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":2,"position":"天文也。","text":"谓五。利变之正，成巽，体离。艮为星，离日坎月，巽为高。五，天位。离为文明，日月星辰，高丽于上。故称天之文也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":3,"position":"文明以止，人文也。","text":"人谓三。乾为人。文明，离。止，艮也。震动离明。五变据四，二五分则止文三。故以三为人文也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":4,"position":"观乎天文，以察时变。","text":"日月星辰，为天文也。泰震春，兑秋。贲坎冬，离夏。巽为进退，日月星辰，进退盈缩，谓朓侧朏也。历象在天成变，故“以察时变”矣。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":5,"position":"观乎人文，以化成天下。","text":"泰乾为人。五上动，体既济。贲离象，重明丽正，故“以化成天下”也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":7,"position":"君子以明庶政，无敢折狱。","text":"君子谓乾。离为明，坤为庶政，故“明庶政”。坎为狱，三在狱得正，故“无敢折狱”。噬嗑四不正，故“利用狱”也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":8,"position":"初九：贲其趾，","text":"应在震，震为足，故“贲其趾”也。","locator":{"book":"周易集解","gua":"贲","pos":"初九"},"citation":"《周易集解》·贲卦·初九","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":9,"position":"舍车而徒。","text":"应在艮。艮为舍，坎为车；徒，步行也。位在下，故“舍车而徒”。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":16,"position":"六五：贲于邱园，束帛戋戋，吝。终吉。","text":"艮为山。五半山，故称邱；木果曰园，故“贲于邱园”也。六五失正，动之成巽。巽为帛、为绳。艮手持，故“束帛”。以艮断巽，故“戋戋”。失位无应，故“吝”。变而得正，故“终吉”矣。","locator":{"book":"周易集解","gua":"贲","pos":"六五"},"citation":"《周易集解》·贲卦·六五","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":17,"position":"：六五之吉，有喜也。","text":"五变之阳，故有喜。凡言喜庆，皆阳爻。束帛戋戋，委积之貌。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":18,"position":"上九：白贲，无咎。","text":"在巽上，故曰“白贲”。乘五，阴变而得位，故“无咎”矣。","locator":{"book":"周易集解","gua":"贲","pos":"上九"},"citation":"《周易集解》·贲卦·上九","edition":"jijie"},{"gua":"贲","guaId":"g22","yaoIdx":19,"position":"：白贲无咎，上得志也。","text":"上之五得位，体成既济，故曰“得志”。坎为志也。","locator":{"book":"周易集解","gua":"贲","pos":"卦辞·彖象"},"citation":"《周易集解》·贲卦·卦辞·彖象","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":-1,"position":"卦辞","text":"阴消乾也，与夬旁通。以柔变刚，小人道长；子弑其父，臣弑其君，故“不利有攸往”也。","locator":{"book":"周易集解","gua":"剥","pos":"卦辞"},"citation":"《周易集解》·剥卦·卦辞","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":3,"position":"顺而止之，观象也。","text":"坤顺艮止，谓五消观成剥，故“观象”也。","locator":{"book":"周易集解","gua":"剥","pos":"象传"},"citation":"《周易集解》·剥卦·象传","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":4,"position":"君子尚消息盈虚，天行也。","text":"乾为君子，乾息为盈，坤消为虚，故“君子尚消息盈虚，天行也”。则出入无疾，反复其道。易亏巽消艮，出震息兑，盈乾虚坤，故于是见之耳。","locator":{"book":"周易集解","gua":"剥","pos":"卦辞·彖象"},"citation":"《周易集解》·剥卦·卦辞·彖象","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":7,"position":"初六：剥床以足，蔑贞凶。","text":"此卦坤变乾也。动初成巽，巽木为床；复震在下，为足，故“剥床以足”。蔑，无。贞，正也。失位无应，故“蔑贞凶”。震在阴下，《象》曰：以灭下也。","locator":{"book":"周易集解","gua":"剥","pos":"初六"},"citation":"《周易集解》·剥卦·初六","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":9,"position":"六二：剥床以辨，蔑贞凶。","text":"指间称辨剥。剥二成艮。艮为指，二在指间。故“剥床以辨”。无应在剥，故“蔑贞，凶”也。","locator":{"book":"周易集解","gua":"剥","pos":"六二"},"citation":"《周易集解》·剥卦·六二","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":12,"position":"六四：剥床以肤，凶。","text":"辨上称肤。艮为肤。以阴变阳，至四乾毁，故“剥床以肤”。臣弑君，子弑父，故“凶”矣。","locator":{"book":"周易集解","gua":"剥","pos":"六四"},"citation":"《周易集解》·剥卦·六四","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":14,"position":"六五：贯鱼，以宫人宠，无不利。","text":"剥消观五。巽为鱼，为绳；艮手持绳贯巽，故“贯鱼”也。艮为宫室，人谓乾；五以阴代阳，五贯乾，为宠人，阴得丽之，故“以宫人宠”。动得正成观，故“无不利”也。","locator":{"book":"周易集解","gua":"剥","pos":"六五"},"citation":"《周易集解》·剥卦·六五","edition":"jijie"},{"gua":"剥","guaId":"g23","yaoIdx":16,"position":"上九：硕果不食。君子德车，小人剥庐。","text":"艮为硕果，谓三已复位，有颐象。颐中无物，故“不食”也。夬乾为君子，为德；坤为车，为民；乾在坤，故以德为车。小人谓坤，艮为庐；上变灭艮，坤阴迷乱，故“小人剥庐”也。","locator":{"book":"周易集解","gua":"剥","pos":"上九"},"citation":"《周易集解》·剥卦·上九","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":0,"position":"出入无疾，朋来无咎。","text":"谓出震成乾，入巽成坤。坎为疾，十二消息，不见坎象，故“出入无疾”。兑为朋，在内称来；五阴从初，初阳正息而成兑，故“朋来无咎”矣。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":2,"position":"利有攸往。","text":"阳息临成乾，小人道消，君子道长，故“利有攸往”矣。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":3,"position":"：复亨，","text":"阳息坤，与垢旁通。刚反交初，故“亨”。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":4,"position":"刚反动，而以顺行，","text":"刚从艮入坤，从反震，故曰“反动”也。坤顺震行，故“而以顺行”。阳不从上来反初，故不言刚自外来。是以明不远之复，入坤出震义也。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":6,"position":"反复其道，七日来复，天行也。","text":"谓乾成坤，反出于震而来复，阳为道，故“复其道”。刚为昼日。消乾六爻。为六日。刚来反初，故“七日来复，天行也”。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":8,"position":"复，其见天地之心乎。","text":"坤为复。谓三复位时，离为见，坎为心。阳息临成泰，乾天坤地。故“见天地之心”也。荀爽曰：复者，冬至之卦。阳起初九，为天地心。万物所始，吉凶之先，故曰“见天地之心”矣。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":9,"position":"：雷在地中，复。先王以至日闭关，商旅不行","text":"先王谓乾初。至日冬至之日。坤阖为闭关。巽为商旅，为近利市三倍，姤巽伏初，故商旅不行。姤象曰：后以施命诰四方。今隐复下，故后不省方，复为阳始，姤则阴始。天地之始，阴阳之首。已言先王，又更言后，后，君也。六十四卦，唯此重耳。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":13,"position":"六三：频复，厉，无咎。","text":"频蹙也。三失位，故“频复，厉”。动而之正，故“无咎”也。","locator":{"book":"周易集解","gua":"复","pos":"六三"},"citation":"《周易集解》·复卦·六三","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":15,"position":"六四：中行独复。《象》曰：中行独复，以从","text":"中谓初。震为行。初一阳爻，故称“独”。四得正应初，故曰“中行独复，以从道也”。俗说以四位在五阴之中，而独应复，非也。四在外体，又非内象，不在二五，何得称“中行”耳？","locator":{"book":"周易集解","gua":"复","pos":"六四"},"citation":"《周易集解》·复卦·六四","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":17,"position":"上六：迷复，凶、有灾眚。","text":"坤冥为迷，高而无应，故“凶”。五变正时，坎为灾眚，故“有灾眚”也。","locator":{"book":"周易集解","gua":"复","pos":"上六"},"citation":"《周易集解》·复卦·上六","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":18,"position":"用行师，终有大败，以其国君凶，","text":"三复位时，而体师象，故“用行师”。阴逆不顺，坤为死丧，坎流血，故“终有大败”。姤乾为君灭藏于坤，坤为异邦，故“国君凶”矣。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":19,"position":"至于十年不克征。","text":"坤为至，为十年。阴逆坎临，故“不克征”。谓五变设险，故帅师败丧，君而无征也。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"复","guaId":"g24","yaoIdx":20,"position":"：迷复之凶，反君道也。","text":"姤乾为君，坤阴灭之，以国君凶，故曰“反君道”也。","locator":{"book":"周易集解","gua":"复","pos":"卦辞·彖象"},"citation":"《周易集解》·复卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":0,"position":"元享，利贞。","text":"遁上之初。此所谓四阳二阴，非大壮则遁来也。刚来交初，体乾，故“元亨”。三四失位，故“利贞”也。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":1,"position":"其匪正有眚，不利有攸往。","text":"非正谓上也。四已之正，上动成坎，故“有眚”。变而逆乘，天命不右，故“不利有攸往”矣。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":3,"position":"动而健，刚中而应。大享以正，天之命也。其","text":"动，震也。舰大亨谓乾。刚中谓五，而应二。大亨以正，变四承五；乾为天，巽为命，故曰“大亨以正，天之命也”。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":4,"position":"无妄之往，何之矣。","text":"谓四已变，上动体屯，坎为泣血涟如，故“何之矣”。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":5,"position":"天命不右，行矣哉。","text":"天，五也。巽为命。右，助也。四已变成坤，天道助顺。上动，逆乘巽命。故“天命不右，行矣哉”。言不可行也。马君云：天命不右行，非矣。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":6,"position":"：天下雷行，物与无妄，","text":"与，谓举。妄，亡也。谓雷以动之，震为反生，万物出震，无妄者也，故曰“物与无妄”。《序卦》曰：复则不妄矣。故受之以无妄。而京氏及俗儒，以为大旱之卦，万物皆死，无所复望，失之远矣。有无妄然后可畜，不死明矣。若物皆死，将何畜聚，以此疑也。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":7,"position":"先王以茂对时育万物。","text":"先王谓乾。乾盈为茂，艮为对时。体颐养象，万物出震。故“以茂对时育万物”。言物皆死，违此甚矣。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":8,"position":"初九：无妄，往吉。","text":"谓应四也。四失位，故命变之正。四变得位，承五应初，故“往吉”。在外称往也。","locator":{"book":"周易集解","gua":"无妄","pos":"初九"},"citation":"《周易集解》·无妄卦·初九","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":9,"position":"：无妄之往，得志也。","text":"四变应初，夫妻体正，故“往得志”矣。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":10,"position":"六二：不耕获，不菑畲，则利有攸往。","text":"有益耕象，无坤田，故“不耨”。震为禾稼，艮为手，禾在手中，故称“获”。田在初，一岁曰“菑”。在二、二岁曰“畲”。初爻非坤，故不菑而畲也。得位应五，利四变之益，则坤体成，有耒耨之利，故“利有攸往”。往应五也。","locator":{"book":"周易集解","gua":"无妄","pos":"六二"},"citation":"《周易集解》·无妄卦·六二","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":11,"position":"：不耕获，未富也。","text":"四动坤虚，故“未富也”。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":12,"position":"六三：无妄之灾，或系之牛。行人之得，邑人","text":"上动体坎，故称“灾”也。四动之正，坤为牛，艮为鼻为止；巽为桑，为绳，系牛鼻而止桑下，故“或系之牛”也。乾为行人，坤为邑人，乾四据三，故“行人之得”。三系于四，故“邑人之灾”。或说：以四变刚牛应初，震坤为死丧，故曰“行人得牛，邑人灾也”。","locator":{"book":"周易集解","gua":"无妄","pos":"六三"},"citation":"《周易集解》·无妄卦·六三","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":13,"position":"九四：可贞，无咎。","text":"动得正，故“可贞”。承五应初，故“无咎”也。","locator":{"book":"周易集解","gua":"无妄","pos":"九四"},"citation":"《周易集解》·无妄卦·九四","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":14,"position":"：可贞无咎，固有之也。","text":"动阴承阳，故“固有之也”。","locator":{"book":"周易集解","gua":"无妄","pos":"卦辞·彖象"},"citation":"《周易集解》·无妄卦·卦辞·彖象","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":15,"position":"九五：无妄之疾，勿药有喜。","text":"谓四已之正，上动体坎；坎为疾，故曰“无妄之疾”也。巽为木，艮为石，故称“药”。坎为多眚，药不可试，故“勿药有喜”。康子馈药，丘未达，故不尝，此之谓也。","locator":{"book":"周易集解","gua":"无妄","pos":"九五"},"citation":"《周易集解》·无妄卦·九五","edition":"jijie"},{"gua":"无妄","guaId":"g25","yaoIdx":17,"position":"上九：无妄行，有眚，无攸利。","text":"动而成坎，故“行有眚”。乘刚逆命，故“无攸利”。天命不右，行矣哉。","locator":{"book":"周易集解","gua":"无妄","pos":"上九"},"citation":"《周易集解》·无妄卦·上九","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":-1,"position":"卦辞","text":"大壮初之上，其德刚上也。与萃旁通。二五失位，故“利贞”。此萃五之复二，成临。临者。大也。至上有颐养之象，故名大畜也。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞"},"citation":"《周易集解》·大畜卦·卦辞","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":0,"position":"不家食，吉。利涉大川。","text":"二称家，谓二五易位，成家人。家人体噬嗑食，故“利涉大川，应乎天也”。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":1,"position":"：大畜，刚健笃实，辉光日新。","text":"刚健谓乾，笃实谓艮。二已之五，利涉大川。互体离坎，离为日，故“辉光日新”也。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":3,"position":"能健止，大正也。","text":"健，乾。止，艮也。二五易位，故“大正”。旧读言能止健，误也。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":4,"position":"不家食吉，养贤也。","text":"二五易位成家人。今体颐养象，故“不家食吉，养贤也”。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":7,"position":"君子以多志前言往行，以畜其德。","text":"君子谓乾。乾为言，震为行，坎为志；乾知大始，震在乾前，故“识前言往行”。有颐养象，故“以畜其德”矣。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":9,"position":"：有厉，利已，不犯灾也。","text":"谓二变正，四体坎，故称“灾也”。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":10,"position":"九二：舆说腹。","text":"萃坤为车，为腹；坤消乾成，故“车说腹。”腹，或作辐也。","locator":{"book":"周易集解","gua":"大畜","pos":"九二"},"citation":"《周易集解》·大畜卦·九二","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":12,"position":"九三：良马逐，利艰贞，吉。日闲舆卫，","text":"乾为良马，震为惊走，故称“逐”也。谓二已变，三在坎中，故“利艰贞吉”。离为日。二至五，体师象。坎为闲习，坤为车舆；乾人在上，震为惊卫，讲武闲兵，故曰“日闲舆卫”也。","locator":{"book":"周易集解","gua":"大畜","pos":"九三"},"citation":"《周易集解》·大畜卦·九三","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":12,"position":"九三：良马逐，利艰贞，吉。日闲舆卫，","text":"谓上应也。五已变正，上动成坎，坎为志，故“利有攸往，与上合志也”。","locator":{"book":"周易集解","gua":"大畜","pos":"九三"},"citation":"《周易集解》·大畜卦·九三","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":13,"position":"六四：童牛之告，元吉。","text":"艮为童。五已之正。萃坤为牛。告谓以木楅其角。大畜，畜物之家，恶其触害。艮为手，为小木。巽为绳。绳缚小木，横着牛角，故曰“童牛之告”。得位承五，故元吉而喜，喜，谓五也。","locator":{"book":"周易集解","gua":"大畜","pos":"六四"},"citation":"《周易集解》·大畜卦·六四","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":15,"position":"六五：豮豕之牙，吉。","text":"二变时，坎为豕。剧豕称豮。令不害物。三至上，体颐象。五变之刚，巽为白；震为出；刚白从颐中出，牙之象也。动而得位，“豮豕之牙，吉”。","locator":{"book":"周易集解","gua":"大畜","pos":"六五"},"citation":"《周易集解》·大畜卦·六五","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":16,"position":"：六五之吉，有庆也。","text":"五变得正，故“有庆也”。","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":17,"position":"上九：何天之衢，享。","text":"何，当也。衢，四交道。乾为天，震艮为道。以震交艮，故“何天之衢，亨”。上变，坎为亨也。","locator":{"book":"周易集解","gua":"大畜","pos":"上九"},"citation":"《周易集解》·大畜卦·上九","edition":"jijie"},{"gua":"大畜","guaId":"g26","yaoIdx":18,"position":"：何天之衢，道大行也。","text":"谓上据二阴。乾为天道，震为行，故“道大行矣”","locator":{"book":"周易集解","gua":"大畜","pos":"卦辞·彖象"},"citation":"《周易集解》·大畜卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":-1,"position":"卦辞","text":"晋四之初。与大过旁通。养正则吉。谓三爻之正，五上易位，故“颐贞吉”。反复不衰，与乾、坤、坎、离、大过、小过、中孚同义。故不从临观四阴二阳之例。或以临二之上，兑为口，故有口实也。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞"},"citation":"《周易集解》·颐卦·卦辞","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":0,"position":"观颐，","text":"离为目，故“观颐”，观其所养也。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":1,"position":"自求口实。","text":"或以大过兑为口，或以临兑为口。坤为自，艮为求。口实，颐中物，谓其自养。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":6,"position":"圣人养贤以及万民。","text":"乾为圣人，艮为贤人，颐下养上，故“圣人养贤”。坤阴为民，皆在震上。以贵下贱，大得民，故“以及万民”。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":11,"position":"初九：舍尔灵龟，观我朵颐，凶。","text":"晋离为龟，四之初，故“舍尔灵龟”。坤为我，震为动；谓四失离入坤，远应多惧，故“凶”矣。","locator":{"book":"周易集解","gua":"颐","pos":"初九"},"citation":"《周易集解》·颐卦·初九","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":15,"position":"六三：拂颐，贞凶。十年勿用，无攸利。","text":"三失位体剥，不正相应，弑父弑君，故“贞凶”。坤为十年，动无所应，故“十年勿用，无攸利”也。","locator":{"book":"周易集解","gua":"颐","pos":"六三"},"citation":"《周易集解》·颐卦·六三","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":16,"position":"：十年勿用，道大悖也。","text":"弑父弑君，故大悖也。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":18,"position":"：颠颐之吉，上施光也。","text":"晋四之初，谓三已变，故“颠颐”。与屯四乘坎马同义。坤为虎，离为目。眈眈，下视貌。逐逐，心烦貌，坤为吝啬，坎水为欲，故“其欲逐逐”。得位应初，故“无咎”。谓上已反三成离，故“上施光也”。","locator":{"book":"周易集解","gua":"颐","pos":"卦辞·彖象"},"citation":"《周易集解》·颐卦·卦辞·彖象","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":19,"position":"六五：拂经，居贞吉，不可涉大川。","text":"失位，故拂经。无应顺上。故“居贞吉”。艮为居也。涉上成坎，乘阳无应，故“不可涉大川”矣。","locator":{"book":"周易集解","gua":"颐","pos":"六五"},"citation":"《周易集解》·颐卦·六五","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":21,"position":"上九：由颐，厉，吉。","text":"由，自从也。体剥居上，众阴顺承，故“由颐”。失位，故“厉”。以坤艮自辅，故“吉”也。","locator":{"book":"周易集解","gua":"颐","pos":"上九"},"citation":"《周易集解》·颐卦·上九","edition":"jijie"},{"gua":"颐","guaId":"g27","yaoIdx":21,"position":"上九：由颐，厉，吉。","text":"失位，故厉之。五得正成坎，坎为大川，故“利涉大川”。变阳得位，故“大有庆”也。","locator":{"book":"周易集解","gua":"颐","pos":"上九"},"citation":"《周易集解》·颐卦·上九","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":-1,"position":"卦辞","text":"大壮五之初，或兑三之初。栋桡谓三。巽为长木，称栋。初上阴柔，本末弱，故“栋桡”也。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞"},"citation":"《周易集解》·大过卦·卦辞","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":0,"position":"利有攸往，亨。","text":"谓二也。刚过而中，失位无应，利变应五；之外称往，故“利有攸往”，乃“亨”也。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":1,"position":"：大过，大者过也。","text":"阳称大，谓二也。二失位，故“大者过也”。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":3,"position":"刚过而中，巽而说行，利有攸往，乃亨。","text":"刚过而中，谓二。说，兑也。故“利有攸往”。大壮震五之初，故“亨”。与遁同义。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":4,"position":"大过之时大矣哉。","text":"国之大事，在祀与戎，藉用白茅。女妻有子，继世承祀，故“大矣哉”。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":6,"position":"君子以独立不惧，遁世无闷。","text":"君子谓乾初。阳伏巽中，体复一爻，潜龙之德，故称“独立不惧”。违则忧之，乾初同义，故“遁世无闷”也。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":7,"position":"初六：藉用白茅，无咎。","text":"位在下称藉，巽柔白为茅，故“藉用白茅”。失位，咎也。承二过四，应五士夫，故“无咎”矣。","locator":{"book":"周易集解","gua":"大过","pos":"初六"},"citation":"《周易集解》·大过卦·初六","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":11,"position":"：老夫女妻，过以相与也。","text":"谓二过初与五，五过上与二。独大过之爻得过其应，故“过以相与也”。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":12,"position":"九三：栋桡，凶。《象》曰：栋桡之凶，不可","text":"本末弱，故桡。辅之益桡，故“不可以有辅”。阳以阴为辅也。","locator":{"book":"周易集解","gua":"大过","pos":"九三"},"citation":"《周易集解》·大过卦·九三","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":13,"position":"九四：栋隆，吉。有他吝。","text":"隆，上也。应在于初。已与五，意在于上。故“栋隆，吉”。失位动，入险而陷于井，故“有他吝”。","locator":{"book":"周易集解","gua":"大过","pos":"九四"},"citation":"《周易集解》·大过卦·九四","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":14,"position":"：栋隆之吉，不桡乎下也。","text":"乾为动直，远初近上，故“不桡下也”。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":15,"position":"九五：枯杨生华，老妇得其士夫，无咎无誉。","text":"阳在五也。夬三月时，周之五月。枯杨得泽，故生华矣。老妇谓初，巽为妇，乾为老，故称“老妇”也。士夫谓五。大壮震为夫，兑为少，故称“士夫”。五过二，使应上。二过五，使取初。五得位，故“无咎”。阴在二多誉，今退伏初，故“无誉”。体姤淫女，故“过以相与”。使应少夫。《象》曰：“亦可丑也。”旧说以初为女妻，上为老妇，误矣。马君亦然。荀公以初阴失正，当变，数六，为女妻。二阳失正，数九，为老夫。以五阳得正位，不变，数七，为士夫。上阴得正，数八，为老妇。此何异俗说也。悲夫学之难，而以初本为小，反以上末为老。后之达者，详其义焉。","locator":{"book":"周易集解","gua":"大过","pos":"九五"},"citation":"《周易集解》·大过卦·九五","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":16,"position":"：枯杨生华，何可久也。老妇士夫，亦可丑也","text":"乾为久，枯而生华，故不可久也。妇体姤淫，故“可丑”也。","locator":{"book":"周易集解","gua":"大过","pos":"卦辞·彖象"},"citation":"《周易集解》·大过卦·卦辞·彖象","edition":"jijie"},{"gua":"大过","guaId":"g28","yaoIdx":17,"position":"上六：过涉灭顶，凶，无咎。","text":"大壮震为足，兑为水泽。震足没水，故“过涉”也。顶，首也。乾为顶，顶没兑水中，故“灭顶凶”。乘刚，咎也。得位，故“无咎”。与灭耳同义也。","locator":{"book":"周易集解","gua":"大过","pos":"上六"},"citation":"《周易集解》·大过卦·上六","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":-1,"position":"卦辞","text":"乾二五之坤，与离旁通。于爻，观上之二。习，常也。孚，信，谓二五。水行往来，朝宗于海，不失其时，如月行天，故习坎为孚也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞"},"citation":"《周易集解》·坎卦·卦辞","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":0,"position":"维心亨，","text":"坎为心。乾二五旁行流坤，阴阳会合，故“亨”也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":1,"position":"行有尚。","text":"行谓二，尚谓五也。二体震，为行动得正应五，故“行有尚，往有功也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":2,"position":"：习坎，重险也。","text":"两象也。天险地险，故曰“重险也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":4,"position":"行险而不失其信。","text":"信，谓二也。震为行。水性有常，消息与月相应，故“不失其信”矣。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":6,"position":"行有尚，往有功也。","text":"功谓五。二动应五，故“往有功也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":7,"position":"天险不可升也，","text":"谓五在天位。五从乾来，体屯难。故“天险不可升也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":8,"position":"地险山川丘陵也。","text":"坤为地，乾二之坤，故曰“地险”。艮为山，坎为川；半山称丘，丘下称陵。故曰“地险山川丘陵也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":9,"position":"王公设险以守其国，","text":"王公大人谓乾五。坤为邦。乾二之坤成坎险，震为守，有屯难象。故“王公设险以守其国”。离言王用出征以正邦是也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":11,"position":"：水洊至，习坎。君子以常德行习教事。","text":"君子谓乾。五在乾，称大人；在坎，为君子。坎为习、为常，乾为德，震为行，巽为教令，坤为事，故“以常德行习教事”也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":13,"position":"：习坎入坎，失道凶也。","text":"习，积也。位下，故习坎为人。坎中小穴称窞。上无其应，初二失正，故曰“失道凶”矣。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":14,"position":"九二：坎有险，求小得。","text":"阳陷阴中，故“有险”。据阴有实，故“求小得”也。","locator":{"book":"周易集解","gua":"坎","pos":"九二"},"citation":"《周易集解》·坎卦·九二","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":16,"position":"六三：来之坎坎，险且枕，入于坎窞，勿用。","text":"坎在内，称来，在坎终，故“来之坎坎”。枕，止也。艮为止。三失位乘二，则险。承五隔四，故“险且枕”。入于坎窞，体师三舆，故“勿用”。","locator":{"book":"周易集解","gua":"坎","pos":"六三"},"citation":"《周易集解》·坎卦·六三","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":18,"position":"六四：樽酒簋，贰用缶。","text":"震主祭器，故有“樽簋”。坎为酒。簋，黍稷器。三至五，有颐口象。震献在中，故为“簋”。坎为木，震为足；坎酒在上，樽酒之象。贰，副也。坤为缶，礼有副樽，故“贰用缶”耳。","locator":{"book":"周易集解","gua":"坎","pos":"六四"},"citation":"《周易集解》·坎卦·六四","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":19,"position":"内约自牖，终无咎。","text":"坎为内也。四阴小，故“约”。艮为牖，坤为户，艮小光照户牖之象；贰用缶。故“内约自牖”。得位承五，故“无咎”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":20,"position":"：樽酒簋，刚柔际也。","text":"乾刚坤柔，震为交，故曰“刚柔际也”。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":21,"position":"九五：坎不盈，禔既平，无咎。","text":"盈，溢也。艮为止，谓水流而不盈。坎为平。禔，安也。艮止坤安，故“禔既平”。得位正中，故“无咎”。","locator":{"book":"周易集解","gua":"坎","pos":"九五"},"citation":"《周易集解》·坎卦·九五","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":22,"position":"：坎不盈，中未光大也。","text":"体屯五中，故未光大也。","locator":{"book":"周易集解","gua":"坎","pos":"卦辞·彖象"},"citation":"《周易集解》·坎卦·卦辞·彖象","edition":"jijie"},{"gua":"坎","guaId":"g29","yaoIdx":23,"position":"上六：系用徽纆，寘于丛棘，三岁不得，凶。","text":"徽纆，黑索也。观巽为绳，艮为手，上变入坎。故“系用徽纆”。寘，置也。坎多心，故“丛棘”。狱外种九棘，故称“丛棘”。二变则五体剥，剥伤坤杀，故“寘于丛棘”也。不得，谓不得出狱。艮止坎狱。乾为岁，五从乾来，三非其应，故曰“三岁不得，凶”矣。","locator":{"book":"周易集解","gua":"坎","pos":"上六"},"citation":"《周易集解》·坎卦·上六","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":-1,"position":"卦辞","text":"坤二五之乾，与坎旁通。于爻，遯初之五，柔丽中正，故“利贞，亨”。","locator":{"book":"周易集解","gua":"离","pos":"卦辞"},"citation":"《周易集解》·离卦·卦辞","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":0,"position":"畜牝牛，吉。","text":"畜，养也。坤为牝牛。乾二五之坤成坎，体颐养象。故“畜牝牛，吉”。俗说皆以离为牝牛，失之矣。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":2,"position":"日月丽乎天。","text":"乾五之坤成坎，为月；离为日。日月丽天也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":3,"position":"百谷草木丽乎也。","text":"震为百谷，巽为草木，坤为地。乾二五之坤成坎。震体屯。屯者，盈也。盈天地之间者唯万物，万物出震，故“百谷草木丽乎地”。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":4,"position":"重明以丽乎正，乃化成天下。","text":"两象，故重明。正谓五阳。阳变之坤来化乾，以成万物，谓离日“化成天下”也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":5,"position":"柔丽乎中正，故亨。","text":"柔谓五阴，中正谓五伏阳。出在坤中，畜牝牛。故“中正”而“亨”也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":7,"position":"：明两作离，","text":"两谓日与月也。乾五之坤成坎，坤二之乾成离，离坎日月之象，故“明两作离”。作，成也。日月在天，动成万物，故称作矣。或以日与火为明。两作也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":8,"position":"大人以继明照于四方。","text":"阳气称大人，则乾五大人也。乾二五之光，继日之明。坤为方，二五之坤。震东兑西，离南坎北，故曰“照于四方”。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":18,"position":"戚嗟若，吉。","text":"坎为心，震为声，兑为口，故“戚嗟若”。动而得正，尊丽阳，故“吉”也。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":20,"position":"上九：王用出征，有嘉折首，获匪其丑，无咎","text":"王谓乾。乾二五之坤成坎，体师象；震为出，故“王用出征”。首谓坤。二五来折乾，故“有嘉折首”。丑，类也。乾征得坤阴类，乾阳物，故“获非其丑，无咎”矣。","locator":{"book":"周易集解","gua":"离","pos":"上九"},"citation":"《周易集解》·离卦·上九","edition":"jijie"},{"gua":"离","guaId":"g30","yaoIdx":21,"position":"：王用出征，以正邦也。","text":"乾五出征坤，故“正邦也”。","locator":{"book":"周易集解","gua":"离","pos":"卦辞·彖象"},"citation":"《周易集解》·离卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":-1,"position":"卦辞","text":"咸，感也。坤三之上成女，乾上之三成男，乾坤气交以相与。止而说，男下女。故“通利贞，取女吉”。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞"},"citation":"《周易集解》·咸卦·卦辞","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":3,"position":"圣人感人心而天下和平。","text":"乾为圣人；初四易位成既济；坎为心、为平，故“圣人感人心而天下和平”。此保合太和，品物流形也。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":4,"position":"观其所感，而天地万物之情可见矣。","text":"谓四之初，以离日见天，坎月见地，悬象着明，万物见离，故“天地万物之情可见”也。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":6,"position":"君子以虚受人。","text":"君子谓否乾。乾为人，坤为虚，谓坤虚三受上，故“以虚受人”。艮山在地下为谦，在泽下为虚。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":7,"position":"初六：咸其母。《象》曰：咸其母，志在外也","text":"母，足大指也。艮为指。坤为母，故“咸其母”。失位远应，之四得正，故“志在外”。谓四也。","locator":{"book":"周易集解","gua":"咸","pos":"初六"},"citation":"《周易集解》·咸卦·初六","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":10,"position":"：咸其股，亦不处也。志在随人，所执下也。","text":"巽为股，谓二也。巽为随，艮为手，故称“执”。三应于上，初四已变历险，故“往吝”。巽为处女也，男已下女，以艮阳入兑阴，故“不处也”。凡士与女未用，皆称“处”矣。志在于二，故“所执下也”。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":11,"position":"九四：贞吉，悔亡。憧憧往来，朋从尔思。","text":"失位悔也。应初动得正，故“贞吉”而“悔亡”矣。憧憧，怀思虑也。之内为来，之外为往。欲感上，隔五；感初，隔三，故“憧憧往来”矣。兑为朋，少女也。艮初变之四，坎心为思，故曰“朋从尔思”也。","locator":{"book":"周易集解","gua":"咸","pos":"九四"},"citation":"《周易集解》·咸卦·九四","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":12,"position":"：贞吉悔亡，未感害也。","text":"坤为害也。今未感坤，初体遯弑父，故曰“未感害”也。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":13,"position":"憧憧往来，未光大也。","text":"未动之离，故未光大也。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":14,"position":"九五：咸其脢，无悔。","text":"脢，夹脊肉也。谓四已变，坎为脊，故“咸其脢”。得正，故“无悔”。","locator":{"book":"周易集解","gua":"咸","pos":"九五"},"citation":"《周易集解》·咸卦·九五","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":16,"position":"上六：咸其辅颊舌。","text":"耳目之间称辅颊。四变之目，坎为耳，兑为口舌。故曰“咸其辅颊舌”。","locator":{"book":"周易集解","gua":"咸","pos":"上六"},"citation":"《周易集解》·咸卦·上六","edition":"jijie"},{"gua":"咸","guaId":"g31","yaoIdx":17,"position":"：咸其辅颊舌，媵口说也。","text":"媵，送也。不得之三，山泽通气，故“媵口说也”。","locator":{"book":"周易集解","gua":"咸","pos":"卦辞·彖象"},"citation":"《周易集解》·咸卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":-1,"position":"卦辞","text":"恒，久也。与益旁通。乾初之坤四，刚柔皆应，故“通，无咎，利贞”矣。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞"},"citation":"《周易集解》·恒卦·卦辞","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":0,"position":"利有攸往。","text":"初利往之四，终变成益，则初四二五皆得其正，终则有始，故“利有攸往”也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":5,"position":"天地之道，恒久而不已也。","text":"泰，乾坤为天地。谓终则复始，有亲则可久也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":7,"position":"日月得天而能久照，","text":"动初，成乾为天。至二，离为日；至三，坎为月。故“日月得天而能久照”也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":8,"position":"四时变化而久成。","text":"春夏为变，秋冬为化，变至二离夏，至三兑秋，至四震春，至五坎冬。故“四时变化而能久成”。谓乾坤成物也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":9,"position":"圣人久于其道，而天下化成。","text":"圣人谓乾。乾为道。初二已正，四五复位，成既济定。乾道变化，各正性命。有两离象，重明丽正，故“化成天下”。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":10,"position":"观其所恒，而天地万物之情可见矣。","text":"以离日照乾，坎月照坤，万物出震，故“天地万物之情可见矣”。与咸同义也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":12,"position":"君子以立不易方。","text":"君子谓乾三也。乾为易，为立；坤为方。乾初之坤四，三正不动。故“立不易方”也。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":14,"position":"：浚恒之凶，始求深也。","text":"浚，深也。初下称浚，故曰“浚恒”。乾初为渊，故“深”矣。失位变之正，乾为始。故曰“始求深也”。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":15,"position":"九二：悔亡。","text":"失位悔也，动而得正，处中多誉，故“悔亡”也。","locator":{"book":"周易集解","gua":"恒","pos":"九二"},"citation":"《周易集解》·恒卦·九二","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":19,"position":"九四：田无禽。《象》曰：久非其位，安得禽","text":"田为二也。地上称田，无禽，谓五也。九四失位，利二上之五，已变承之。故曰“田无禽”。言二五皆非其位，故《象》曰：“久非其位，安得禽也。”。","locator":{"book":"周易集解","gua":"恒","pos":"九四"},"citation":"《周易集解》·恒卦·九四","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":20,"position":"六五：恒其德，贞妇人吉，夫子凶。","text":"动正成乾，故“恒其德”。妇人谓初。巽为妇。终变成益，震四复初，妇得归阳，从一而终，故“贞妇人吉也”。震，乾之子，而为巽夫，故曰“夫子”。终变成益，震四从巽，死于坤中，故“夫子凶”也。","locator":{"book":"周易集解","gua":"恒","pos":"六五"},"citation":"《周易集解》·恒卦·六五","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":21,"position":"：妇人贞吉，从一而终也。","text":"一谓初，终变成益，以巽应初震，故“从一而终也”。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":22,"position":"夫子制义，从妇凶也。","text":"震没从巽入坤，故“从妇凶”矣。","locator":{"book":"周易集解","gua":"恒","pos":"卦辞·彖象"},"citation":"《周易集解》·恒卦·卦辞·彖象","edition":"jijie"},{"gua":"恒","guaId":"g32","yaoIdx":23,"position":"上六：震恒，凶。《象》曰：震恒在上，大无","text":"在震上，故“震恒”。五动乘阳，故“凶”。终在益上，五远应，故“无功也”。","locator":{"book":"周易集解","gua":"恒","pos":"上六"},"citation":"《周易集解》·恒卦·上六","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":-1,"position":"卦辞","text":"阴消姤二也。艮为山，巽为入，乾为远，远山入藏，故“遁”，以阴消阳，子弑其父，小人道长，避之乃通，故遁而通。则当位而应，与时行也。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞"},"citation":"《周易集解》·遁卦·卦辞","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":0,"position":"小利贞。","text":"小，阴，谓二。得位浸长，以柔变刚，故“小利贞”。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":2,"position":"刚当位而应，与时行也。","text":"刚谓五而应二，艮为时，故“与时行”矣。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":6,"position":"君子以远小人，不恶而严。","text":"君子谓乾。乾为远，为严。小人谓阴。坤为恶，为小人。故“以远小人，不恶而严”也。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":8,"position":"：遁尾之厉，不往何灾也。","text":"艮为尾也。初失位，动而得正，故“遁尾厉”。之应成坎为灾，在艮宜静，若不往于四，则无灾矣。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":9,"position":"六二：执之用黄牛之革，莫之胜说。","text":"艮为手，称执；否坤为黄牛；艮为皮。四变之初，则坎水濡皮。离日乾之。故“执之用黄牛之革”。莫，无也。胜，能。说，解也。乾为坚刚，巽为绳，艮为手，持革缚三在坎中，故“莫之胜说”也。","locator":{"book":"周易集解","gua":"遁","pos":"六二"},"citation":"《周易集解》·遁卦·六二","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":11,"position":"九三：系遁，有疾厉，畜臣妾，吉。","text":"厉，危也。巽为四变，时九三体坎，坎为疾。故“有疾厉”。遁阴剥阳，三消成坤，与上易位。坤为臣，兑为妾上来之三，据坤应兑，故“畜臣妾吉”也。","locator":{"book":"周易集解","gua":"遁","pos":"九三"},"citation":"《周易集解》·遁卦·九三","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":13,"position":"畜臣妾吉，不可大事也。","text":"三动入坤，坤为事，故“不可大事也”。","locator":{"book":"周易集解","gua":"遁","pos":"卦辞·彖象"},"citation":"《周易集解》·遁卦·卦辞·彖象","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":14,"position":"九四，好遁，君子吉，小人否。","text":"否乾为好，为君子；阴称小人。动之初，故“君子吉”。阴在四多惧，故“小人否”。得位承五，故无凶咎矣。","locator":{"book":"周易集解","gua":"遁","pos":"九四"},"citation":"《周易集解》·遁卦·九四","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":16,"position":"九五：嘉遁，贞吉。","text":"乾为嘉，刚当位应二，故“贞吉”。谓三已变，上来之三，成坎象，故曰“以正志也”。","locator":{"book":"周易集解","gua":"遁","pos":"九五"},"citation":"《周易集解》·遁卦·九五","edition":"jijie"},{"gua":"遁","guaId":"g33","yaoIdx":18,"position":"上九：肥遁，无不利。","text":"乾盈为肥。二不及上，故“肥遁无不利”。《象》曰：“无所疑也。”","locator":{"book":"周易集解","gua":"遁","pos":"上九"},"citation":"《周易集解》·遁卦·上九","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":-1,"position":"卦辞","text":"阳息，泰也。壮，伤也。大谓四，失位为阴所乘。兑为毁折伤，与五易位乃得正，故“利贞”也。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞"},"citation":"《周易集解》·大壮卦·卦辞","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":2,"position":"大壮利贞，大者正也。","text":"谓四进之五乃得正，故“大者正也”。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":3,"position":"正大而天地之情可见矣。","text":"正大谓四之五成需。以离日见天，坎月见地，故“天地之情可见”也矣。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":6,"position":"初九：壮于趾，征凶，有孚。","text":"趾谓四。征，行也。震足为趾，为征。初得位，四不征之五，故“凶”。坎为孚，谓四上之五成坎，已得应四，故“有孚”。","locator":{"book":"周易集解","gua":"大壮","pos":"初九"},"citation":"《周易集解》·大壮卦·初九","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":7,"position":"：壮于趾，其孚穷也。","text":"应在乾终，故“其孚穷也”。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":8,"position":"九二：贞吉。《象》曰：九二贞吉，以中也。","text":"变得位，故“贞吉”。动体离，故“以中也”。","locator":{"book":"周易集解","gua":"大壮","pos":"九二"},"citation":"《周易集解》·大壮卦·九二","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":9,"position":"九三：小人用壮，君子用罔，贞厉。","text":"应在震也。三，阳，君子。小人谓上。上逆，故“用壮”。谓二已变离，离为罔，三乘二，故“君子用罔”。体乾，夕惕，故“贞厉”也。","locator":{"book":"周易集解","gua":"大壮","pos":"九三"},"citation":"《周易集解》·大壮卦·九三","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":12,"position":"九四：贞吉，悔亡。藩决不羸，壮于大舆之腹","text":"失位悔也。之五得中，故“贞吉”而“悔亡”矣。体夬象，故“藩决”。震四上处五，则藩毁坏，故“藩决不羸”。坤为大舆、为腹；四之五折坤，故“壮于大舆之腹”。而《象》曰“尚往者”，谓上之五。","locator":{"book":"周易集解","gua":"大壮","pos":"九四"},"citation":"《周易集解》·大壮卦·九四","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":13,"position":"六五：丧羊于易，无悔。","text":"四动成泰。坤为丧也。乾为易。四上之五，兑还属乾。故“丧羊于易”动各得正，而处中和，故“无悔”矣。","locator":{"book":"周易集解","gua":"大壮","pos":"六五"},"citation":"《周易集解》·大壮卦·六五","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":15,"position":"上六：羝羊触藩，不能退，不能遂，无攸利，","text":"应在三，故“羝羊触藩”。遂，进也。谓四已之五，体坎。上能变之巽，巽为进退。故“不能退，不能遂”。退则失位，上则乘刚，故“无攸利”。坎为艰，得位应三利上，故“艰则吉”。","locator":{"book":"周易集解","gua":"大壮","pos":"上六"},"citation":"《周易集解》·大壮卦·上六","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":16,"position":"：不能退，不能遂，不详也。","text":"乾善为详，不得三应，故“不详也”。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"大壮","guaId":"g34","yaoIdx":17,"position":"艰则吉，咎不长也。","text":"巽为长。动失位，为咎。不变之巽。故“咎不长也”。","locator":{"book":"周易集解","gua":"大壮","pos":"卦辞·彖象"},"citation":"《周易集解》·大壮卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":-1,"position":"卦辞","text":"观四之五。晋，进也。坤为康。康，安也；初动体屯，震为侯，故曰“康侯”。震为马，坤为用，故“用锡马”。艮为多，坤为众，故“繁庶”。离日在上，故“昼日”。三阴在下，故“三接”矣。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞"},"citation":"《周易集解》·晋卦·卦辞","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":4,"position":"：明出地上。晋。君子以自昭明德。","text":"君子谓观乾。乾为德，坤为自，离为明。乾五动，以离日自照，故“以自昭明德”也。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":5,"position":"初六：晋如，摧如，贞吉。罔孚，裕无咎。","text":"晋，进。摧，忧愁也。应在四，故“晋如”。失位，故“摧如”。动得位，故“贞吉”。应离为罔，四坎称孚，坤弱为裕，欲四之五成巽，初受其命，故“无咎”矣。","locator":{"book":"周易集解","gua":"晋","pos":"初六"},"citation":"《周易集解》·晋卦·初六","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":6,"position":"：晋如，摧如，独行正也。","text":"初动震为行。初一称独也。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":7,"position":"裕无咎，未受命也。","text":"五未之巽，故“未受命也”。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":8,"position":"六二：晋如，愁如，贞吉。","text":"震谓应，在坎上，故“愁如”。得位处中，故“贞吉”也。","locator":{"book":"周易集解","gua":"晋","pos":"六二"},"citation":"《周易集解》·晋卦·六二","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":9,"position":"受兹介福于其王母。","text":"乾为介福，艮为手，坤为虚，故称“受”。介，大也。谓五已正中，乾为王，坤为母。故“受兹介福于其王母”。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":11,"position":"六三：众允，悔亡。","text":"坤为众。允，信也。土性信，故“众允”。三失正，与上易位，则“悔亡”，故《象》曰“上行也”。此则成小过，小过故有飞鸟之象焉。臼杵之利，见硕鼠出入坎穴，盖取诸此也。","locator":{"book":"周易集解","gua":"晋","pos":"六三"},"citation":"《周易集解》·晋卦·六三","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":12,"position":"：众允之志，上行也。","text":"坎为志。三之上成震，故曰“上行也”。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":16,"position":"：矢得勿恤，往有庆也。","text":"动之乾乾，为庆也。矢古誓字。誓，信也。勿，无。恤，忧也。五变得正，坎象不见，故“誓得勿恤，往有庆也”。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":17,"position":"上九：晋其角，","text":"五已变之乾，为首。位在首上，称角。故“晋其角”也。","locator":{"book":"周易集解","gua":"晋","pos":"上九"},"citation":"《周易集解》·晋卦·上九","edition":"jijie"},{"gua":"晋","guaId":"g35","yaoIdx":18,"position":"惟用伐邑，厉吉无咎，贞吝。","text":"坤为邑。动成震，而体师象，坎为心。故“维用伐邑”。得位乘五，故“厉吉，无咎”而“贞吝”矣。","locator":{"book":"周易集解","gua":"晋","pos":"卦辞·彖象"},"citation":"《周易集解》·晋卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":-1,"position":"卦辞","text":"夷，伤也。临二之三而反晋也。明入地中，故伤矣。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞"},"citation":"《周易集解》·明夷卦·卦辞","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":0,"position":"利艰贞。","text":"谓五也。五失位，变出成坎，为艰，故“利艰贞”矣。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":3,"position":"文王以之。","text":"以，用也。三喻文王。大难谓坤。坤为弑父，迷乱荒淫，若纣杀比干。三幽坎中，象文王之拘羑里。震为诸侯，喻从文王者，纣惧出之，故“以蒙大难”，得身全矣。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":4,"position":"利艰贞，晦其明也。内难而能正其志，箕子以","text":"箕子，纣诸父。故称内难。五乾天位，今化为坤，箕子之象。坤为晦，箕子正之。出五成坎，体离，重明丽正。坎为志，故“正其志，箕子以之”，而纣奴之矣。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":5,"position":"：明入地中，明夷。君子以莅众，用晦而明。","text":"而，如也。君子谓三。体师象。以坎莅坤。坤为众，为晦，离为明，故“用晦如明”也。","locator":{"book":"周易集解","gua":"明夷","pos":"卦辞·彖象"},"citation":"《周易集解》·明夷卦·卦辞·彖象","edition":"jijie"},{"gua":"明夷","guaId":"g36","yaoIdx":17,"position":"上六：不明晦，初登于天，后入于地。","text":"应在三。离灭坤下，故“不明晦。”晋时在上丽乾，故“登于天照四国。”今反在下，故“后入于地，失其则。”","locator":{"book":"周易集解","gua":"明夷","pos":"上六"},"citation":"《周易集解》·明夷卦·上六","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":-1,"position":"卦辞","text":"遁初之四也。女谓离巽。二四得正。故“利女贞”也。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞"},"citation":"《周易集解》·家人卦·卦辞","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":1,"position":"男女正，天地之大义也。","text":"遁乾为天，三动坤为地。男得天，正于五；女得地，正于二。故“天地之大义也”。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":3,"position":"父父，子子，兄兄，弟弟，","text":"遁乾为父，艮为子，三五位正，故“父父，子子”。三动时，震为兄，艮为弟，初位正，故“兄兄、弟弟”。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":4,"position":"夫夫，妇妇，","text":"三动时，震为夫，巽四为妇，初四位正，故“夫夫，妇妇”也。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":13,"position":"六四：富家大吉。《象》曰：富家大吉，顺在","text":"三变体艮，艮为笃实。坤为大业。得位应初，顺五乘三，比据三阳，故曰“富家大吉，顺在位也。”谓顺于五矣。","locator":{"book":"周易集解","gua":"家人","pos":"六四"},"citation":"《周易集解》·家人卦·六四","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":15,"position":"：王假有家，交相爱也。","text":"乾为爱也，二称家。三动成震。五得交二，初得交四，故“交相爱”。震为交也。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":16,"position":"上九：有孚威加，终吉。","text":"谓三已变，与上易位，成坎。坎为孚，故“有孚”。乾为威如，自上之坤，故“威如”。易则得位，故“终吉”也。","locator":{"book":"周易集解","gua":"家人","pos":"上九"},"citation":"《周易集解》·家人卦·上九","edition":"jijie"},{"gua":"家人","guaId":"g37","yaoIdx":17,"position":"：威如之吉，反身之谓也。","text":"谓三动，坤为身。上之三，成既济定，故“反身之谓”。此家道正，正家而天下定矣。","locator":{"book":"周易集解","gua":"家人","pos":"卦辞·彖象"},"citation":"《周易集解》·家人卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":-1,"position":"卦辞","text":"大壮上之三在系，盖取无妄二之五也。小谓五。阴称小，得中应刚，故“吉”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞"},"citation":"《周易集解》·睽卦·卦辞","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":0,"position":"：睽，火动而上，泽动而下。","text":"离火炎上，泽水润下也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":1,"position":"二女同居，其志不同行。","text":"二女，离兑也。坎为志。离上兑下。无妄震为行，巽为同，艮为居。二五易位，震巽象坏。故“二女同居，其志不同行也”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":2,"position":"说而丽乎明，柔进而上行，得中而应乎刚，","text":"说，兑。丽，离也。明谓乾。当言大明以丽于晋。柔谓五，无妄巽为进。从二之五，故“上行。”刚谓应乾，五伏阳，非应二也。与鼎五同义也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":4,"position":"天地睽而其事同也。","text":"五动乾为天，四动坤为地，故“天地睽”。坤为事也。五动体同人，故“事同矣”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":5,"position":"男女睽而其志通也。","text":"四动艮为男，兑为女，故“男女睽”。坎为志，为通，故“其志通也”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":6,"position":"万物睽而其事类也。","text":"四动，万物出乎震，区以别矣。故“万物睽”。坤为事，为类，故“其事类也”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":10,"position":"初九：悔亡，丧马勿逐自复，见恶人，无咎。","text":"无应，四动得位，故“悔亡”。应在于坎，坎为马。四而失位，之正入坤，坤为丧。坎象不见，故“丧马”。震为逐，艮为止，故“勿逐”。坤为自，二至五，体复象，故“自复”。四动震马来，故“勿逐自复”也。离为见。恶人谓四，动入坤初，四复正。故“见恶人，以避咎矣”。","locator":{"book":"周易集解","gua":"睽","pos":"初九"},"citation":"《周易集解》·睽卦·初九","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":11,"position":"九二：遇主于巷，无咎。","text":"二动体震。震为主，为大涂，艮为径路。大道而有径路，故称“巷”。变而得正，故“无咎”而“未失道也”。","locator":{"book":"周易集解","gua":"睽","pos":"九二"},"citation":"《周易集解》·睽卦·九二","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":12,"position":"：遇主于巷，未失道也。","text":"动得正，故“未失道”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":13,"position":"六三：见舆曳，其牛觢。","text":"离为见。坎为车，为曳。故“见舆曳”。四动坤为牛，为类。牛角一低一仰，故称“觢”。离上而坎下，“其牛觢也”。","locator":{"book":"周易集解","gua":"睽","pos":"六三"},"citation":"《周易集解》·睽卦·六三","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":14,"position":"其人天且劓，无初有终。","text":"其人谓四，恶人也。黥额为天，割鼻为劓。无妄乾为天。震二之乾五，以阴墨其天。乾五之震二，毁艮，割其劓也。兑为刑人。故“其人天且劓”。失位，动得正成乾，故“无初有终”。《象》曰：“遇刚”，是其义也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":15,"position":"：见舆曳，位不当也。无初有终，遇刚也。","text":"动正成乾，故“遇刚”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":16,"position":"九四：睽孤遇元夫，交孚，厉，无咎。","text":"孤，顾也。在两阴间，睽五顾三，故曰“睽孤”。震为元夫。谓二已变，动而应震。故“遇元夫”也。震为交，坎为孚，动而得正，故“交孚，励精图治，无咎”矣。","locator":{"book":"周易集解","gua":"睽","pos":"九四"},"citation":"《周易集解》·睽卦·九四","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":17,"position":"：交孚无咎，志行也。","text":"坎动成震，故“志行也”。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":18,"position":"六五：悔亡，厥宗噬肤，往何咎。","text":"往得位，“悔亡”也。动而之乾，乾为宗。二动体噬嗑，故曰“噬”。四变时，艮为肤。故曰“厥宗噬肤”也。变得正成乾，乾为庆，故往无咎而有庆矣。","locator":{"book":"周易集解","gua":"睽","pos":"六五"},"citation":"《周易集解》·睽卦·六五","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":20,"position":"上九：睽孤，见豕负涂，载鬼一车。","text":"睽三顾五，故曰“睽孤”也。离为见，坎为豕，为雨。四变时坤为土，土得雨，为泥涂。四动艮为背，豕背有泥，故“见豕负涂”矣。坤为鬼，坎为车，变在坎上，故“载鬼一车”也。","locator":{"book":"周易集解","gua":"睽","pos":"上九"},"citation":"《周易集解》·睽卦·上九","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":21,"position":"先张之弧，后说之壶，","text":"谓五已变，乾为先。应在三。坎为弧，离为矢，张弓之象也，故“先张之槐。四动震为后。说，犹置也。兑为口，离为大腹，坤为器。大腹有口。坎，酒在中壶之象也。之应历险以与兑。故“后说之壶”矣。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":22,"position":"匪寇婚媾。往遇雨则吉。","text":"匪，非；坎为寇，之三历坎，故“匪寇”。阴阳相应，故“婚媾”。三在坎下，故“遇雨”。与上易位，坎象不见，各得其正，故“则吉”也。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"睽","guaId":"g38","yaoIdx":23,"position":"：遇雨之吉，群疑亡也。","text":"物三称群，坎为疑，三变坎败，故“群疑亡”矣。","locator":{"book":"周易集解","gua":"睽","pos":"卦辞·彖象"},"citation":"《周易集解》·睽卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":-1,"position":"卦辞","text":"观上反三也。坤，西南卦。五在坤中，坎为月，月生西南，故“利西南”。往得中，谓“西南得朋”也。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞"},"citation":"《周易集解》·蹇卦·卦辞","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":0,"position":"不利东北。","text":"谓三也。艮东北之卦。月消于艮，丧乙灭癸。故“不利东北，其道穷也”。则东北丧朋矣。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":1,"position":"利见大人。","text":"离为见，大人谓五。二得位应五。故“利见大人，往有功也”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":2,"position":"贞吉。","text":"谓五当位正邦，故“贞吉”也。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":3,"position":"：蹇，难也，险在前也。见险而能止，知矣哉","text":"离见坎险。艮为止，观乾为知，故“知矣哉”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":6,"position":"利见大人，往有功也。","text":"大人谓五。二往应五，五多功，故“往有功也”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":8,"position":"蹇之时用大矣哉。","text":"谓坎月生西南而终东北。震象出庚，兑象见丁，乾象盈甲，巽象退辛，艮象消丙，坤象穷乙，丧灭于癸，终则复始，以生万物，故“用大矣”。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":10,"position":"君子以反身修德。","text":"君子谓观。乾坤为身，观上反三，故“反身”。阳在三，进德修业，故“以反身修德”。孔子曰：德之不修，是吾忧也。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":11,"position":"初六：往蹇，来誉。","text":"誉谓二，二多誉也。失位应阴，往历坎险，故“往蹇”。变而得位，以阳承二，故来而誉矣。","locator":{"book":"周易集解","gua":"蹇","pos":"初六"},"citation":"《周易集解》·蹇卦·初六","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":12,"position":"：往蹇来誉，宜待时也。","text":"艮为时，谓变之正以待四也。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":13,"position":"六二：王臣蹇蹇，匪躬之故。","text":"观乾为王；坤为臣，为躬；坎为蹇也。之应涉坤，二五俱坎，故“王臣蹇蹇”。观上之三，折坤之体，臣道得正，故“匪躬之故”。《象》曰：“终无尤也”。","locator":{"book":"周易集解","gua":"蹇","pos":"六二"},"citation":"《周易集解》·蹇卦·六二","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":15,"position":"九三：往蹇，来反。","text":"应正历险，故“往蹇”。反身据二，故“来反”也。","locator":{"book":"周易集解","gua":"蹇","pos":"九三"},"citation":"《周易集解》·蹇卦·九三","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":16,"position":"：往蹇来反，内喜之也。","text":"内，谓二阴也。","locator":{"book":"周易集解","gua":"蹇","pos":"卦辞·彖象"},"citation":"《周易集解》·蹇卦·卦辞·彖象","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":17,"position":"六四：往蹇，来连。","text":"连，辇。蹇，难也。在两坎间，进则无应，故“往蹇”。退初介三，故“来连”也。","locator":{"book":"周易集解","gua":"蹇","pos":"六四"},"citation":"《周易集解》·蹇卦·六四","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":19,"position":"九五：大蹇，朋来。","text":"当位正邦，故“大蹇”。睽兑为朋，故“朋来”也。","locator":{"book":"周易集解","gua":"蹇","pos":"九五"},"citation":"《周易集解》·蹇卦·九五","edition":"jijie"},{"gua":"蹇","guaId":"g39","yaoIdx":21,"position":"上六：往蹇，来硕吉，利见大人。","text":"阴在险上，变失位，故“往蹇”。硕谓三，艮为硕，退来之三，故“来硕”。得位有应，故“吉”也。离为见，大人谓五，故“利见大人”矣。","locator":{"book":"周易集解","gua":"蹇","pos":"上六"},"citation":"《周易集解》·蹇卦·上六","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":-1,"position":"卦辞","text":"临初之四。坤，西南卦。初之四，得坤众。故“利西南，往得众也”。","locator":{"book":"周易集解","gua":"解","pos":"卦辞"},"citation":"《周易集解》·解卦·卦辞","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":0,"position":"无所往，其来复吉。","text":"谓四本从初之四，失位于外，而无所应，故“无所往”。宜来反初，复得正位，故“其来复吉”也。二往之五，四来之初，成屯，体复象，故称“来复吉”矣。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":1,"position":"有攸往，夙吉。","text":"谓二也。夙，早也。离为日，为甲。日出甲上，故早也。九二失正，早往之五，则吉。故“有攸往，夙吉，往有功也”。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":2,"position":"：解，险以动，动而免乎险，解。","text":"险，坎。动，震。解，二月。雷以动之，雨以润之，物咸孚甲，万物生震。震出险上，故“免乎险”也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":10,"position":"：雷雨作，解。君子以赦过宥罪。","text":"君子谓三。伏阳出，成大过。坎为罪人则大过象坏，故“以赦过”。二四失位，皆在坎狱中。三出体乾，两坎不见。震喜兑说，罪人皆出，故以“宥罪”。谓三入则赦过，出则宥罪。公用射隼以解悖，是其义也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":11,"position":"初六：无咎。","text":"与四易位，体震得正，故“无咎”也。","locator":{"book":"周易集解","gua":"解","pos":"初六"},"citation":"《周易集解》·解卦·初六","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":12,"position":"：刚柔之际，义无咎也。","text":"体屯初震，刚柔始交，故“无咎”也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":13,"position":"九二：田获三狐，得黄矢，贞吉。","text":"二称田。田，猎也。变之正，艮为狐。坎为弓。离为黄矢，矢贯狐体。二之五，历三爻。故“田获三狐，得黄矢。”之正得中，故“贞吉”。","locator":{"book":"周易集解","gua":"解","pos":"九二"},"citation":"《周易集解》·解卦·九二","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":14,"position":"：九二贞吉，得中道也。","text":"动得正，故得中道。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":15,"position":"六三：负且乘，","text":"负，倍也。二变时艮为背，谓三以四艮倍五也。五来寇三时，坤为车，三在坤上，故“负且乘”。小人而乘君子之器《象》曰：“亦可丑也”。","locator":{"book":"周易集解","gua":"解","pos":"六三"},"citation":"《周易集解》·解卦·六三","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":16,"position":"致寇至，贞吝。","text":"五之二成坎，坎为寇盗。上位慢五，下暴于二，慢藏悔盗，故“致寇至，贞吝”。《象》曰：“自我致戎，又谁咎也。”","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":17,"position":"：负且乘，亦可丑也。自我致戎，又谁咎也。","text":"临坤为丑也。坤为自我。以离兵伐三，故转寇为戎。艮手招盗，故“谁咎也”。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":18,"position":"九四：解而母，朋至斯孚。","text":"二动时艮为指。四变之坤为母，故“解而母”。临兑为朋，坎为孚。四阳从初，故“朋至斯孚”矣。","locator":{"book":"周易集解","gua":"解","pos":"九四"},"citation":"《周易集解》·解卦·九四","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":20,"position":"六五：君子惟有解，吉。有孚于小人。","text":"君子谓二。之五得正成坎，坎为心。故“君子惟有解，吉”。小人谓五。阴为小人，君子升位，则小人退在二，故“有孚于小人”。坎为孚也。","locator":{"book":"周易集解","gua":"解","pos":"六五"},"citation":"《周易集解》·解卦·六五","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":21,"position":"：君有解，小人退也。","text":"二阳上之五，五阴小人退之二也。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":22,"position":"上六：公用射隼于高庸之上，获之，无不利。","text":"上应在三。公，谓三伏阳也。离为隼。三失位，动出成乾，贯隼入大过，死象故“公用射隼于高庸之上，获之，无不利”也。","locator":{"book":"周易集解","gua":"解","pos":"上六"},"citation":"《周易集解》·解卦·上六","edition":"jijie"},{"gua":"解","guaId":"g40","yaoIdx":23,"position":"：公用射隼，以解悖也。","text":"坎为悖，三出成乾，而坎象坏，故“解悖也”。","locator":{"book":"周易集解","gua":"解","pos":"卦辞·彖象"},"citation":"《周易集解》·解卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":0,"position":"有孚。无吉，无咎。可贞，利有攸往。","text":"泰初之上，损下益上，以据二阴，故“有孚，元吉，无咎”。艮男居上，兑女在下，男女位正，故“可贞利有攸往”矣。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":8,"position":"二簋应有时。","text":"时谓春秋也。损二之五，震二月，益正月，春也。损七月，兑八月，秋也。谓春秋祭祀，以时思之。艮为时，震为应，故“应有时”也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":9,"position":"损刚益柔有时。","text":"谓冬夏也。二五已易成益。坤为柔。谓损。益上之三成既济，坎冬离夏。故“损刚益柔有时”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":10,"position":"损益盈虚，与时偕行。","text":"乾为盈，坤为虚，损刚益柔，故“损益盈虚”。谓泰初之上，损二之五，益上之三，变通趋时，故“与时偕行”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":11,"position":"：山下有泽，损。君子以征忿窒欲。","text":"君子，泰乾。乾阳刚武，为忿。坤阴吝啬，为欲。损乾之初成兑说，故“征忿”。初上据坤，艮为止，故“窒欲也”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":12,"position":"初九：祀事遄往，无咎，酌损之。","text":"祀，祭祀。坤为事，谓二也。遄，速。酌，取也。二失正，初利二速往，合志于五，得正无咎，已得之应，故“遄往无咎酌损之”。《象》曰“上合志也”。祀，旧作巳也。","locator":{"book":"周易集解","gua":"损","pos":"初九"},"citation":"《周易集解》·损卦·初九","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":13,"position":"：祀事遄往，上合志也。","text":"终成既济，谓二上合志于五也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":14,"position":"九二：利贞，征凶，弗损益之。","text":"失位当之正，故“利贞”。征，行也。震为征，失正毁折，故“不征”。之五则凶，二之五成益，小损大益，故“弗损益之”矣。","locator":{"book":"周易集解","gua":"损","pos":"九二"},"citation":"《周易集解》·损卦·九二","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":15,"position":"：九二利贞，中以为志也。","text":"动体离中，故“为志也”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":16,"position":"六三：三人行，则损一人。","text":"泰乾三爻，为三人；震为行，故“三人行”。损初之上，故“则损一人”。","locator":{"book":"周易集解","gua":"损","pos":"六三"},"citation":"《周易集解》·损卦·六三","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":17,"position":"一人行，则得其友。","text":"一人谓泰初之上，损刚益柔，故“一人行”。兑为友，初之上，据坤应兑，故“则得其友”。言致一也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":18,"position":"：一人行，三则疑也。","text":"坎为疑，上益三成坎，故“三则疑”。荀爽曰：一阳在上，则教令行。三阳在下，则民众疑也。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":19,"position":"六四：损其疾，使遄有喜，无咎。","text":"四，谓二也。四得位，远应初。二疾上五，已得承之。谓二之五，三上复。坎为疾也。阳在五称喜。故“损其疾，使遄有喜”。二上体观，得正承五，故“无咎”矣。","locator":{"book":"周易集解","gua":"损","pos":"六四"},"citation":"《周易集解》·损卦·六四","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":20,"position":"：损其疾，亦可喜也。","text":"二上之五，体大观象，故“可喜也”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":21,"position":"六五：或益之十朋之龟，弗克违，元吉。","text":"谓二五已变成益，故“或益之”。坤数十，兑为朋，三上失位，三动离为龟。十谓神灵摄宝文、筮山泽水火之龟也。故“十朋之龟”。三上易位，成既济，故“弗克违，元吉”矣。","locator":{"book":"周易集解","gua":"损","pos":"六五"},"citation":"《周易集解》·损卦·六五","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":23,"position":"上九：弗损益之，无咎，贞吉。","text":"损上益三也。上失正，之三得位，故“弗损益之，无咎，贞吉”。动成既济，故“大得志”。","locator":{"book":"周易集解","gua":"损","pos":"上九"},"citation":"《周易集解》·损卦·上九","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":24,"position":"利有攸往，得臣无家。","text":"谓三往之上，故“利有攸往”。二五已动成益，坤为臣。三变据坤，成家人，故曰“得臣”。动而应三，成既济，则家人坏，故曰“无家”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"损","guaId":"g41","yaoIdx":25,"position":"：弗损益之，大得志也。","text":"谓二五已变，上下益三，成既济定。离坎体正，故“大得志”。","locator":{"book":"周易集解","gua":"损","pos":"卦辞·彖象"},"citation":"《周易集解》·损卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":-1,"position":"卦辞","text":"否上之初也。损上益下，其道大光。二利往坎应五，故“利有攸往，中正有庆”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞"},"citation":"《周易集解》·益卦·卦辞","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":0,"position":"利涉大川。","text":"谓三失正。动成坎，体涣；坎为大川，故“利涉大川”。涣，舟楫象。木道乃行也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":2,"position":"民说无疆。","text":"上之初。坤为无疆，震为喜笑；以贵下贱，大得民，故“说无疆”矣。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":3,"position":"自上下下，其道大光。","text":"乾为大明，以乾照坤，故“其道大光”。或以上之三，离为大光矣。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":4,"position":"利有攸往，中正有庆。","text":"中正谓五，而二应之，乾为庆也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":5,"position":"利涉大川，木道乃行。","text":"谓三动成涣。涣，舟楫象。巽木得水，故“木道乃行”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":6,"position":"益动而巽，日进无疆。","text":"震三动为离，离为日。巽为进，坤为疆。日与巽俱进，故曰“进无疆”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":7,"position":"天施地生，其益无方。","text":"乾下之坤，震为出生，万物出震，故“天施地生”。阳在坤初为无方，日进无疆，故“其益无方”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":8,"position":"凡益之道，与时偕行。","text":"上来益三，四时象正。艮为时，震为行，与损同义，故“与时偕行”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":9,"position":"：风雷，益。君子以见善则迁，有过则改。","text":"君子，谓乾也。上之三，离为见。乾为善，坤为过。坤三进之乾四，故“见善则迁”。乾上之坤初，改坤之过。体复象，复以自知，故“有过则改”也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":10,"position":"初九：利用为大作，元吉，无咎。","text":"大作谓耕播耒耨之利，盖取诸此也。坤为用，乾为大，震为作，故“利用为大作”。体复初得正，朋来无咎，故“元吉，无咎”。震，二月卦，日中星鸟，敬授民时，故以耕播也。","locator":{"book":"周易集解","gua":"益","pos":"初九"},"citation":"《周易集解》·益卦·初九","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":12,"position":"六二：或益之十朋之龟，弗克违，永贞吉。","text":"谓上从外来益初也，故“或益之”。二得正远应，利三之正，已得承之。坤数十，损兑为朋；谓三变离为龟，故“十朋之龟”。坤为永，上之三得正，故“永贞吉”。","locator":{"book":"周易集解","gua":"益","pos":"六二"},"citation":"《周易集解》·益卦·六二","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":13,"position":"王用享于帝，吉。","text":"震称帝。王谓五。否乾为王。体观象。艮为宗庙。三变，折坤牛。体噬嗑食。故“王用享于帝”。得位，故“吉”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":14,"position":"：或益之，自外来也。","text":"乾上称外，来益初也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":15,"position":"六三：益之用凶事，无咎。","text":"坤为事，三多凶。上来益三得正。故“益用凶事，无咎”。","locator":{"book":"周易集解","gua":"益","pos":"六三"},"citation":"《周易集解》·益卦·六三","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":16,"position":"有孚中行，告公用圭。","text":"公谓三，伏阳也。三动体坎，故“有孚”。震为中行，为告，位在中，故曰“中行”。三，公位。乾为圭，乾之三，故“告公用圭”。圭。桓圭也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":17,"position":"：益用凶事，固有之矣。","text":"三上失正当变，是“固有之”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":18,"position":"六四：中行，告公从，","text":"中行谓震位在中。震为行，为从，故曰“中行”。公谓三。三上失位。四利三之正，已得以为实，故曰“告公从”矣。","locator":{"book":"周易集解","gua":"益","pos":"六四"},"citation":"《周易集解》·益卦·六四","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":19,"position":"利用为依迁邦。","text":"坤为邦。迁，从也。三动坤从，故利用为依迁邦也。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":20,"position":"：告公从，以益志也。","text":"坎为志，三之上，有两坎象，故“以益志也”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":21,"position":"九五：有孚惠心，勿问，元吉。","text":"谓三上也。震为问。三上易位，三五体坎，已成既济。坎为心。故“有孚惠心，勿问，元吉”。故《象》：“勿问之矣。”","locator":{"book":"周易集解","gua":"益","pos":"九五"},"citation":"《周易集解》·益卦·九五","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":22,"position":"有孚惠我德。","text":"坤为我，乾为德，三之上体坎，为孚，故“惠我德”。《象》曰“大得志”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":24,"position":"上九：莫益之，","text":"莫，无也。自非上无益初者，唯上当无应故“莫益之”矣。","locator":{"book":"周易集解","gua":"益","pos":"上九"},"citation":"《周易集解》·益卦·上九","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":25,"position":"或击之，","text":"谓上不益初，则以剥灭乾。艮为手，故“或击之”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":26,"position":"立心勿恒，凶。","text":"上体巽，为进退，故“勿恒”。动成坎心，以阴乘阳，故“立心勿恒，凶”矣。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":27,"position":"：莫益之，遍辞也。","text":"遍，周匝也。三体刚凶，故至上应乃益之矣。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"益","guaId":"g42","yaoIdx":28,"position":"或击之，自外来也。","text":"外谓上。上来之三，故曰“自外来也”。","locator":{"book":"周易集解","gua":"益","pos":"卦辞·彖象"},"citation":"《周易集解》·益卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":-1,"position":"卦辞","text":"阳决阴，息卦也。刚决柔，与剥旁通。乾为扬，为王，剥艮为庭，故“扬于王庭”矣。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞"},"citation":"《周易集解》·夬卦·卦辞","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":0,"position":"孚号有厉，","text":"阳在二五称孚。孚，谓五也。二失位，动体巽，巽为号，离为光。不变则危。故“孚号有厉，其危乃光也”。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":1,"position":"告自邑。不利即戎，","text":"阳息动复。刚长成夬。震为告。坤为自邑。夬从复升，坤逆在上，民众消灭。二变时，离为戎。故“不利即戎，所尚乃穷也。”","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":2,"position":"利有攸往。","text":"阳息阴消，君子道长，故“利有攸往，刚长乃终”。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":3,"position":"：夬，决也，刚决柔也。","text":"乾决坤也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":4,"position":"健而说，决而和。","text":"健，乾。说。兑也。以乾阳获阴之和，故“决而和”也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":9,"position":"利有攸往，刚长乃终也。","text":"乾体大成，以决小人。终乾之刚，故乃以终也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":11,"position":"君子以施禄及下，居德则忌。","text":"君子谓乾，乾为施禄。下为剥坤，坤为众臣。以乾应坤，故“施禄及下”。乾为德，艮为居，故“居德则忌”。阳极阴生，谓阳忌阴。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":12,"position":"初九：壮于前趾，往不胜为咎。","text":"夬变大壮，大壮震为趾，位在前，故“壮于前”。刚以应刚，不能克之，往如失位，故“往不胜为咎”。","locator":{"book":"周易集解","gua":"夬","pos":"初九"},"citation":"《周易集解》·夬卦·初九","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":13,"position":"：不胜而往，咎也。","text":"往失位应阳，故咎矣。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":14,"position":"九二：惕号，莫夜有戎，勿恤。","text":"惕，惧也。二失位，故“惕”。变成巽，故“号”。剥坤为“莫夜”。二动成离，离为戎，变而得正，故“有戎”。四变成坎，坎为忧，坎又得正，故“勿恤”。谓成既济定也。","locator":{"book":"周易集解","gua":"夬","pos":"九二"},"citation":"《周易集解》·夬卦·九二","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":15,"position":"：有戎勿恤，得中道也。","text":"动得正应五，故“得中道”。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":20,"position":"九四：臀无肤，其行次且。","text":"二四已变，坎为臀。剥艮为肤，毁灭不见。故“臀无肤”。大壮震为行。坎为破，为曳。故“其行趑趄”也。","locator":{"book":"周易集解","gua":"夬","pos":"九四"},"citation":"《周易集解》·夬卦·九四","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":21,"position":"牵羊悔亡，闻言不信。","text":"兑为羊，二变巽为绳，剥艮手持绳，故“牵羊”。谓四之正，得位承五，故“悔亡”。震为言，坎为耳，震坎象不正，故“闻言不信”也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":22,"position":"：其行次且，位不当也。闻言不信，聪不明也","text":"坎耳离目，折入于兑故“聪不明”矣。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":24,"position":"中行无咎。","text":"苋，说也。苋，读夫子苋尔而笑之苋。睦，和睦也。震为笑。言五得正位，兑为说，故“苋陆夬夬”。大壮震为行，五在上中，动而得正，故“中行无咎”。旧读言苋陆，字之误也。马君、荀氏皆从俗，言苋陆非也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":25,"position":"：中行无咎，中未光也。","text":"在坎阴中，故“未光”也。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":26,"position":"上六：无号，终有凶。","text":"应在于三，三动时体巽，巽为号令；四已变坎，之应历险，巽象不见，故“无号”。位极乘阳，故“终有凶矣”。","locator":{"book":"周易集解","gua":"夬","pos":"上六"},"citation":"《周易集解》·夬卦·上六","edition":"jijie"},{"gua":"夬","guaId":"g43","yaoIdx":27,"position":"：无号之凶，终不可长也。","text":"阴道消灭，故“不可长也”。","locator":{"book":"周易集解","gua":"夬","pos":"卦辞·彖象"},"citation":"《周易集解》·夬卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":-1,"position":"卦辞","text":"消卦也，与复旁通。巽，长女；女壮，伤也。阴伤阳，柔消刚，故“女壮”也。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞"},"citation":"《周易集解》·姤卦·卦辞","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":0,"position":"勿用取女。","text":"阴息剥阳，以柔变刚，故“勿用娶女，不可与长”也。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":7,"position":"后以施命诰四方。","text":"后继体之君。姤阴在下，故称“后”。与泰称后同义也。乾为施，巽为命，为诰。复震二月，东方；姤五月，南方；巽八月，西方；复十一月，北方；皆总在初，故以诰四方也。孔子行夏之时，经用周家之月，夫子传《彖》、《象》以下，皆用夏家月。是故夏为十一月，姤为五月矣。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":8,"position":"初六：系于金柅，贞吉。","text":"柅，谓二也。巽为绳。故“系柅”。乾为金，巽木入金，柅之象也。初四失正，易位乃吉，故“贞吉”矣。","locator":{"book":"周易集解","gua":"姤","pos":"初六"},"citation":"《周易集解》·姤卦·初六","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":10,"position":"羸豕孚蹄遯。","text":"以阴消阳。往谓成坤。遯，子弑父；否，臣弑君。夬时三动，离为见。故“有攸往，见凶”矣。三夬之四。在夬，动而体坎，坎为豕，为孚，巽绳操之，故称“羸”也。巽为舞，为进退，操而舞，故“羸豕孚蹄遯。”以喻姤女望于五阳，如豕蹢躅也。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":11,"position":"：系于金柅，柔道牵也。","text":"阴道柔，巽为绳，牵于二也。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":12,"position":"九二：包有鱼，无咎，不利宾。","text":"巽为白茅，在中称包。《诗》云：白茅包之。鱼谓初阴，巽为鱼；二虽失位，阴阳相承。故“包有鱼，无咎”。宾谓四。乾尊称宾。二据四应，故“不利宾”。或以包为庖厨也。","locator":{"book":"周易集解","gua":"姤","pos":"九二"},"citation":"《周易集解》·姤卦·九二","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":14,"position":"九三：臀无肤，其行次且，厉，无大咎。","text":"夬时动之坎，为臀。艮为肤。二折艮体，故“臀无肤”。复震为行，其象不正，故“其行趑趄”。三得正位，虽则危厉，故“无大咎”矣。","locator":{"book":"周易集解","gua":"姤","pos":"九三"},"citation":"《周易集解》·姤卦·九三","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":15,"position":"：其行次且，行未牵也。","text":"在夬失位，故牵羊。在姤得正，故“未牵也”。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":18,"position":"九五：以杞苞瓜，含章，","text":"杞，杞柳，木名也。巽为杞、为苞。乾圆称瓜。故“以杞包瓜”矣。含章，谓五也。五欲使初四易位，以阴含阳，已得乘之，故曰“含章”。初之四，体兑口，故称“含”也。","locator":{"book":"周易集解","gua":"姤","pos":"九五"},"citation":"《周易集解》·姤卦·九五","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":19,"position":"有陨自天。","text":"陨，落也。乾为天，谓四陨之初，初上承五，故“有陨自天”矣。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":20,"position":"：九五含章，中正也。有陨自天，志不舍命也","text":"巽为命也。欲初之四承已，故“不舍命”矣。","locator":{"book":"周易集解","gua":"姤","pos":"卦辞·彖象"},"citation":"《周易集解》·姤卦·卦辞·彖象","edition":"jijie"},{"gua":"姤","guaId":"g44","yaoIdx":21,"position":"上九：姤其角，吝，无咎。","text":"乾为首，位在首上，故称“角”。动而得正，故“无咎”。","locator":{"book":"周易集解","gua":"姤","pos":"上九"},"citation":"《周易集解》·姤卦·上九","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":-1,"position":"卦辞","text":"观上之四也。观乾为王。假至也。艮为庙，体观享祀，故通。上之四，故“假有庙，致孝享”矣。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞"},"citation":"《周易集解》·萃卦·卦辞","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":0,"position":"利见大人，亨，利贞。","text":"大人谓五。三四失位，利之正。变成离，离为见。故“利见大人，亨，利贞”。聚以正也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":1,"position":"用大牲吉。利有攸往。","text":"坤为牛，故曰“大牲”，四之三，折坤得正，故“用大牲吉”。三往之四，故“利有攸往，顺天命也”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":4,"position":"致孝享也。","text":"享，享祀也。五至初，有观象，谓享坤牛，故“致孝享”矣。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":5,"position":"利见大人亨，聚以正也。","text":"坤为聚，坤三之四，故“聚以正”也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":7,"position":"用大牲吉。利有攸往，顺天命也。","text":"坤为顺，巽为命，三往之四，故“顺天命也”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":8,"position":"观其所聚，而天地万物之情可见矣。","text":"三四易位成离坎。坎月离日，日以见天，月以见地，故“天地之情可见矣”。与大壮、咸、恒同义也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":10,"position":"君子以除戎器，戒不虞。","text":"君子谓五。除，修，戎，兵也，《诗》曰：修尔车马，弓矢戎兵。阳在三四为修。坤为器。三四之正，离为戎兵、甲胄、飞矢。坎为弓弧，巽为绳。艮为石，谓穀甲胄，锻厉矛矢。故“除戎器”也。坎为寇，坤为乱，故“戒不虞”也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":11,"position":"初六：有孚不终，乃乱乃萃。","text":"孚，谓五也。初四易位，五坎中，故“有孚”失正当变，坤为终，故“不终”。萃。聚也。坤为乱为聚，故“乃乱乃萃”。失位不变，则相聚为乱。故《象》曰：“其志乱”也。","locator":{"book":"周易集解","gua":"萃","pos":"初六"},"citation":"《周易集解》·萃卦·初六","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":12,"position":"若号，一握为笑，勿恤，往无咎。","text":"巽为号，艮为手，初称一，故“一握”。初动成震，震为“笑”。四动成坎，坎为“恤”。故“若号一握为笑，勿恤”。初之四得正，故“往无咎”矣。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":13,"position":"：乃乱乃萃，其志乱也。","text":"坎为志，初之四，其“志乱也”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":14,"position":"六二：引吉，无咎。","text":"应巽为绳，艮为手，故“引吉”。得正应五，故“无咎”。利引四之初，使避已，已得之五也。","locator":{"book":"周易集解","gua":"萃","pos":"六二"},"citation":"《周易集解》·萃卦·六二","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":15,"position":"孚乃利用禴。","text":"孚谓五。禴，夏祭也。体观象，故“利用禴”。四之三，故“用大牲”。离为夏，故“禴祭”，《诗》曰：禴祠烝尝，是其义。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":16,"position":"：引吉无咎，中未变也。","text":"二得正，故不变也。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":17,"position":"六三：萃如嗟如，无攸利，往无咎，小吝。","text":"坤为萃，故“萃如”。巽为号，故“嗟如”。失正，故“无攸利”。动得位故“往无咎，小吝”。谓往之四。","locator":{"book":"周易集解","gua":"萃","pos":"六三"},"citation":"《周易集解》·萃卦·六三","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":18,"position":"：往无咎，上巽也。","text":"动之四，故“上巽”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":19,"position":"九四：大吉无咎。《象》曰：大吉无咎，位不","text":"以阳居阴，故“位不当”。动而得正，承五应初，故“大吉”而“无咎”矣。","locator":{"book":"周易集解","gua":"萃","pos":"九四"},"citation":"《周易集解》·萃卦·九四","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":20,"position":"九五：萃有位，无咎，匪孚。元永贞，悔亡。","text":"得位居中，故“有位无咎”。匪孚，谓四也。四变之正，则五体皆正，故“元永贞”与比彖同义。四动之初，故“悔亡”。","locator":{"book":"周易集解","gua":"萃","pos":"九五"},"citation":"《周易集解》·萃卦·九五","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":21,"position":"：萃有位，志未光也。","text":"阳在坎中，故“志未光“。与屯五同义。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":22,"position":"上六：赍资涕洟，无咎。","text":"赍，持。资，赙也。货财丧称赙。自目曰“涕”，自鼻称“洟”。坤为财，巽为进，故“赍资”也。三之四，体离坎。艮为鼻，涕泪流鼻目，故“涕洟”。得位应三，故“无咎”。上体大过，死象，故有“赍资滋洟”之哀。","locator":{"book":"周易集解","gua":"萃","pos":"上六"},"citation":"《周易集解》·萃卦·上六","edition":"jijie"},{"gua":"萃","guaId":"g45","yaoIdx":23,"position":"：赍资涕洟，未安上也。","text":"乘刚远应，故“未安上也”。","locator":{"book":"周易集解","gua":"萃","pos":"卦辞·彖象"},"citation":"《周易集解》·萃卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":0,"position":"元亨。","text":"临初之三，又有临象；刚中而应，故“元亨”也。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":1,"position":"用见大人，勿恤。","text":"谓二当之五，为大人，离为见，坎为恤，二之五得正，故“用见大人勿恤，有庆也”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":2,"position":"南征吉。","text":"离，南方卦，二之五成离，故“南征吉，志行也”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":3,"position":"：柔以时升，","text":"柔谓五，坤也。升谓二。坤邑无君二当升五虚，震兑为春秋；二升，坎离为冬夏。四时象正，故“柔以时升”也。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":6,"position":"南征吉，志行也。","text":"二之五，坎为志。震为行。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":8,"position":"君子以慎德，积小以成高大。","text":"君子谓三。小谓阳息复时。复小，为德之本。至二成临。临者，大也。临初之三，巽为高。二之五，艮为慎。坤为积，故“慎德积小成高大”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":11,"position":"九二：孚乃利用禴，无咎。","text":"禴，夏祭也。孚谓二，之五成坎，为孚；离为夏，故“乃利用禴无咎”矣。","locator":{"book":"周易集解","gua":"升","pos":"九二"},"citation":"《周易集解》·升卦·九二","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":12,"position":"：九二之孚，有喜也。","text":"升五得位，故“有喜”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":14,"position":"：升虚邑，无所疑也。","text":"坎为疑，上得中，故“无所疑也”。","locator":{"book":"周易集解","gua":"升","pos":"卦辞·彖象"},"citation":"《周易集解》·升卦·卦辞·彖象","edition":"jijie"},{"gua":"升","guaId":"g46","yaoIdx":17,"position":"六五：贞吉，升阶。","text":"二之五，故“贞吉”。巽为高，坤为土，震升高，故“升阶”也。","locator":{"book":"周易集解","gua":"升","pos":"六五"},"citation":"《周易集解》·升卦·六五","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":-1,"position":"卦辞","text":"否二之上，乾坤交，故通也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞"},"citation":"《周易集解》·困卦·卦辞","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":2,"position":"有言不信。","text":"震为言，折入兑，故“有言不信，尚口乃穷”。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":7,"position":"有言不信，尚口乃穷也。","text":"兑为口，上变口灭，故“尚口乃穷”。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":9,"position":"君子以致命遂志。","text":"君子谓三，伏阳也。否坤为致，巽为命，坎为志，三入阴中，故“致命遂志”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":16,"position":"六三：困于石，据于蒺藜，","text":"二变正时，三在艮山下，故“困于石”。蒺藜，木名。坎为蒺藜。二变艮手，据坎。故“据蒺藜者”也。","locator":{"book":"周易集解","gua":"困","pos":"六三"},"citation":"《周易集解》·困卦·六三","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":17,"position":"入于其宫，不见其妻，凶。","text":"巽为入。二动艮为宫，兑为妻，谓上无应也。三在阴下，离象毁坏，隐在坤中，死其将至，故“不见其妻，凶”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":20,"position":"九四：来荼荼，困于金车，吝，有终。","text":"来欲之初。荼荼，舒迟也。见险，故“来荼荼”。否乾为金，乾为舆。之应历险，故困于金，车易位得正，故“吝，有终”矣。","locator":{"book":"周易集解","gua":"困","pos":"九四"},"citation":"《周易集解》·困卦·九四","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":23,"position":"九五：劓刖，困于赤绂，","text":"割鼻曰劓。断足曰刖。四动时震为足，艮为鼻。离为兵，兑为刑。故“劓刖”也。赤绂谓二。否乾为朱，故“赤”。坤为绂，二未变应五，故“困于赤绂”也。","locator":{"book":"周易集解","gua":"困","pos":"九五"},"citation":"《周易集解》·困卦·九五","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":24,"position":"乃徐有说，","text":"兑为说，坤为徐，二动应已，故“乃徐有说”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":29,"position":"上六：困于葛藟，于臲兀，","text":"巽为草莽，称葛藟，谓三也。兑为刑人。故“困于葛藟，于臲兀”也。","locator":{"book":"周易集解","gua":"困","pos":"上六"},"citation":"《周易集解》·困卦·上六","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":30,"position":"曰动悔有悔，征吉。","text":"乘阳，故“动悔”。变而失正，故“有悔”。三已变正，已得应之，故“征吉”也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":31,"position":"：困于葛藟，未当也。","text":"谓三未变，当位应上故也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"困","guaId":"g47","yaoIdx":32,"position":"动悔有悔，吉行也。","text":"行谓三，变乃得当位之应，故“吉行”者也。","locator":{"book":"周易集解","gua":"困","pos":"卦辞·彖象"},"citation":"《周易集解》·困卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":0,"position":"改邑不改井，","text":"泰初之五也。坤为邑，乾初之五折坤。故“改邑”。初为旧井，四应甃之，故“不改井”。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":1,"position":"无丧无得，往来井井。","text":"无丧，泰初之五。坤象毁坏，故“无丧”。五来之初，失位无应，故“无得”。坎为通，故“往来井井”。往谓之五，来谓之初也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":2,"position":"汔至，亦未繘井，","text":"巽绳，为繘，汔，几也。谓二也。几至初改，未繘井，未有功也。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":3,"position":"羸其瓶，凶。","text":"羸钩罗也。艮为手，巽为繘，离为瓶，手繘折其中，故“赢其瓶”。体兑毁缺，瓶缺漏，故“凶”矣。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":5,"position":"井养而不穷也。","text":"兑口饮水，坎为通，往来井井，故“养不穷也”。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":10,"position":"未有功也。","text":"谓二未变应五，故“未有功也”。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":13,"position":"君子以劳民劝相。","text":"君子谓泰乾也。坤为民；初上成坎，为劝，故“劳民劝相”。相，相助也。谓以阳助坤矣。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":15,"position":"：井泥不食，下也。旧井无禽，时舍也。","text":"食，用也。初下称泥。巽为木果，无噬嗑食象。下而多泥，故“不食”也。乾为旧，位在阴下，故“旧井无禽，时舍也”。谓时舍于初，非其位也。与乾二同义。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":16,"position":"九二：井谷射鲋，瓮敝漏。","text":"巽为谷，为鲋。小鲜也。离为瓮。瓮瓶毁缺，羸其瓶凶，故“瓮敝漏”也。","locator":{"book":"周易集解","gua":"井","pos":"九二"},"citation":"《周易集解》·井卦·九二","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":22,"position":"：井甃无咎，修井也。","text":"修，治也。以瓦甓垒井称甃。坤为上。初之五成篱，离火烧土，为瓦治象。故曰“井甃无咎，修井也”。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":23,"position":"九五：井冽，寒泉食。","text":"泉自下出称井。周七月，夏之五月，阴气在下。二已变坎，十一月为寒泉。初二已变，体噬嗑食。故“冽寒泉食”矣。","locator":{"book":"周易集解","gua":"井","pos":"九五"},"citation":"《周易集解》·井卦·九五","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":25,"position":"上六：井收勿幕，有孚元吉。","text":"幕，盖也。收，谓以辘轳收繘也。坎为车，应巽绳，为繘。故“井收勿幕”。有孚谓五坎。坎为孚，故“元吉”也。","locator":{"book":"周易集解","gua":"井","pos":"上六"},"citation":"《周易集解》·井卦·上六","edition":"jijie"},{"gua":"井","guaId":"g48","yaoIdx":26,"position":"：元吉在上，大成也。","text":"谓初二已变，成既济定，故“大成也”。","locator":{"book":"周易集解","gua":"井","pos":"卦辞·彖象"},"citation":"《周易集解》·井卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":0,"position":"已日乃孚，元亨利贞，悔亡。","text":"遁上之初，与蒙旁通。悔亡，谓四也。四失正，动得位，故“悔亡”。离为日，孚谓坎。四动体离，五在坎中，故“已日乃孚”。以成既济，乾道变化，各正性命，保合太和，乃利贞，故“元亨利贞，悔亡”矣。与《乾?彖》同义也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":1,"position":"：革，水火相息，","text":"息，长也。离为火，兑为水。《系》曰：润之以风雨。风，巽。雨。兑也。四革之正，坎见，故独于此称水也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":2,"position":"二女同居，其志不相得，曰革。","text":"二女，离兑。体同人象。蒙艮为居，故“二女同居”。四变体两坎象，二女有志。离火志上，兑水志下。故“其志不相得”。坎为志也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":4,"position":"文明以说，大亨以正，革而当，其悔乃亡。","text":"文明谓离。说，兑也。大亨谓乾。四动成既济定，故“大亨以正，革而当位，故悔乃亡”也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":5,"position":"天地革而四时成。","text":"谓五位成。乾为天。蒙坤为地，震春。兑秋。四之正，坎冬离夏，则四时具坤，革而成乾，故“天地革而四时成”也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":6,"position":"汤武革命，顺乎天而应乎人。","text":"汤武谓乾，乾为圣人。天谓五，人谓三。四动，顺五应三，故“顺天应人”。巽为命也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":9,"position":"君子以治历明时。","text":"君子，遁乾也。历象谓日月星辰也。离为明，坎为月。离为日，蒙艮为星。四动成坎离，日月得正，天地革而四时成。故“君子以治历明时”也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":11,"position":"：巩用黄牛，不可以有为也。","text":"得位无应，动而必凶，故“不可以有为也”。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":13,"position":"：已日革之，行有嘉也。","text":"嘉谓五，乾为嘉。四动承五，故“行有嘉”矣。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":16,"position":"：革言三就，又何之矣。","text":"四动成既济定，故“又何之矣”。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":17,"position":"九四：悔亡，有孚，改命吉。","text":"革而当，其悔乃亡。孕谓五也。巽为命。四动五坎改巽，故“改命吉”。四乾为君，进退无恒，在离焚弃，体大过死，传以比桀纣。汤武革命，顺天应人，故“改命吉”也。","locator":{"book":"周易集解","gua":"革","pos":"九四"},"citation":"《周易集解》·革卦·九四","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":18,"position":"：改命之吉，信志也。","text":"四动成坎，故“信志也”。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":19,"position":"九五：大人虎变，未占有孚。","text":"乾为大人，谓五也。蒙坤为虎变。传论汤武以坤臣为君占，视也。离为占。四未之正，五未在坎，故“未占有孚”也。","locator":{"book":"周易集解","gua":"革","pos":"九五"},"citation":"《周易集解》·革卦·九五","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":20,"position":"：大人虎变，其文柄也。","text":"乾为大明，四动成离，故“其文炳也”。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":21,"position":"上六：君子豹变，","text":"蒙艮为君子，为豹。从乾而更。故“君子豹变”也。","locator":{"book":"周易集解","gua":"革","pos":"上六"},"citation":"《周易集解》·革卦·上六","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":22,"position":"小人革面，征凶。居贞吉。","text":"阴称小人也。面谓四。革为离，以顺承五。故“小人革面”。乘阳失正，故“征凶”。得位，故“居贞吉”。蒙艮为居也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":23,"position":"：君子豹变，其文蔚也。","text":"蔚，蔇也。兑校故“其文蔚也”。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"革","guaId":"g49","yaoIdx":24,"position":"小人革面，顺以从君也。","text":"乾，君，谓五也。四变顺五，故“顺以从君也”。干宝曰：君子、大贤，次圣之人。谓若太公周召之徒也。豹，虎之属。蔚，炳之次也。君圣臣贤，殷之顽民，皆改志从化，故曰“小人革面”。天下既定，必倒载干戈，包之以虎皮。将卒之士，使为诸侯，故曰“征凶，居贞吉”。得正有应，君子之象也。","locator":{"book":"周易集解","gua":"革","pos":"卦辞·彖象"},"citation":"《周易集解》·革卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":0,"position":"元吉，亨。","text":"大壮上之初，一屯旁通。天地交，柔进上行，得中应乾五刚，故“元吉，亨”也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":1,"position":"：鼎，象也。以木巽火，亨饪也。","text":"六十四卦，皆观象系辞，而独于鼎言“象”，何也？象事知器，故独言象也。","locator":{"book":"周易集解","gua":"鼎","pos":"象传"},"citation":"《周易集解》·鼎卦·象传","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":2,"position":"圣人亨以享上帝，而大亨以养圣贤。","text":"圣人谓乾。初四易位，体大畜。震为帝，在乾天上，故曰“上帝”体颐象，三动噬嗑食，故“以享上帝”也。大享谓天地养万物，圣人养贤以及万民。贤之能者，称圣人矣。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":3,"position":"巽而耳目聪明，","text":"谓三也。三在巽上，动成坎离，有两坎两离象，乃称“聪明”。日月相推而明生焉，故“巽而耳目聪明”。眇而视，不足以有明。闻言不信，聪不明。皆有一离一坎象故也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":4,"position":"柔进而上行，得中而应乎刚，是以元亨。","text":"柔谓五得上中，应乾五刚。巽为进。震为行。非谓应二刚，与睽五同义也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":6,"position":"君子以正位凝命。","text":"君子谓三也。鼎五爻失正，独三得位，故以正位凝成也。体姤，谓阴始凝，初巽为命，故“君子以正位凝命”也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":7,"position":"初六：鼎颠趾，","text":"趾，足也。应在四。大壮震为足，折入大过。大过，颠也。故“鼎颠趾”也。","locator":{"book":"周易集解","gua":"鼎","pos":"初六"},"citation":"《周易集解》·鼎卦·初六","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":8,"position":"利出否。得妾以其子，无咎。","text":"初阴在下，故“否”。利出之四，故曰“利出”。兑为妾，四变得正成震。震为长子，继世守宗庙，而为祭主。故“得妾以其子，无咎”矣。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":10,"position":"利出否，以从贵也。","text":"出初之四，承乾五，故“以从贵也”。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":11,"position":"九二：鼎有实，我仇有疾，不我能即，吉。","text":"二为实，故鼎有实也。坤为我，谓四也。二据四妇，故相与为仇。谓三变时四体坎，坎为疾，故“我仇有疾”。四之二历险，二动得正，故“不我能即，吉”。","locator":{"book":"周易集解","gua":"鼎","pos":"九二"},"citation":"《周易集解》·鼎卦·九二","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":12,"position":"：鼎有实，慎所之也。","text":"二变之正，艮为慎。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":13,"position":"我仇有疾，终无尤也。","text":"不我能即吉，故“终无无尤也”。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":14,"position":"九三：鼎耳革，其行塞，雉膏不食。","text":"动成两坎，坎为耳，而革在乾，故“鼎耳革”。初四变时，震为行。鼎以耳行，伏坎震，折而入乾，故“其行塞”。离为雉，坎为膏。初四已变，三动体颐。颐中无物，离象不见，故“雉膏不食”。","locator":{"book":"周易集解","gua":"鼎","pos":"九三"},"citation":"《周易集解》·鼎卦·九三","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":15,"position":"方雨，亏悔，终吉。","text":"谓四已变，三动成坤。坤为方，坎为雨，故曰“方雨”。三动亏乾，而失位悔也。终复之正，故“方雨，亏悔，终吉”也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":16,"position":"：鼎耳革，失其义也。","text":"鼎以耳行。耳革行塞，故失其义也。","locator":{"book":"周易集解","gua":"鼎","pos":"卦辞·彖象"},"citation":"《周易集解》·鼎卦·卦辞·彖象","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":17,"position":"九四：鼎折足，覆公餗，其刑渥，凶。","text":"谓四变时震为足，足折入兑故“鼎折足”。兑为刑。渥，大刑也。鼎足折，则公餗覆。言不胜任。象入大过死，凶。故“鼎足折，覆公餗，其刑渥，凶”。","locator":{"book":"周易集解","gua":"鼎","pos":"九四"},"citation":"《周易集解》·鼎卦·九四","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":19,"position":"六五：鼎黄耳，金铉，利贞。","text":"离为黄，三变坎为耳，故“鼎黄耳”。铉谓三，贯鼎两耳。乾为金。故“金铉”。动而得睚，故“利贞”。","locator":{"book":"周易集解","gua":"鼎","pos":"六五"},"citation":"《周易集解》·鼎卦·六五","edition":"jijie"},{"gua":"鼎","guaId":"g50","yaoIdx":21,"position":"上九：鼎玉铉，大吉，无不利。","text":"铉谓三，乾为玉铉。体大有上九：“自天右之。”位贵据五，三动承上，故“大吉，无不利”。谓三亏悔，应上成未济。虽不当位，六位相应，故“刚柔节”。《彖》曰：“巽，耳目聪明”，为此九三发也。","locator":{"book":"周易集解","gua":"鼎","pos":"上九"},"citation":"《周易集解》·鼎卦·上九","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":0,"position":"震来虩虩，","text":"临二之四，天地交，故“通”。虩虩谓四也。来应初命，四变而来应已。四失位多惧，故“虩虩”。之内曰来也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":1,"position":"笑言哑哑，","text":"哑哑笑且言，谓初也。得正有则，故“笑言哑哑，后有则也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":2,"position":"震惊百里，不丧匕鬯。","text":"谓阳从临二。阴为百二十，举其大数，故当震百里也。坎为棘、匕。上震为鬯。坤为丧。二上之坤，成震体坎，得其匕鬯，故“不丧匕鬯”也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":3,"position":"：震，亨，震来虩虩，恐致福也。","text":"惧变承五应初，故“恐致福也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":4,"position":"笑言哑哑，后有则也。","text":"则，法也。坎为则也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":5,"position":"震惊百里，惊远而惧迩也。","text":"远谓四，近谓初。震为百，谓四出惊远。初应惧近也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":6,"position":"出可以守宗庙社稷，以为祭主也。","text":"谓五出之正。震为守，艮为宗庙社稷，长子主祭器，故“以为祭主也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":7,"position":"：洊雷震，君子以恐惧修剩","text":"君子谓临二。二出之坤四，体以修身，坤为身。二之四，以阳照坤，故“以恐惧修时。老子曰：修之身，德乃真也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":8,"position":"初九：震来虩虩，后笑言哑哑，吉。","text":"虩虩谓四也。初位在下，故“后笑言哑哑”。得位，故“吉”也。","locator":{"book":"周易集解","gua":"震","pos":"初九"},"citation":"《周易集解》·震卦·初九","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":9,"position":"：震来虩虩，恐致福也。","text":"阳称福。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":10,"position":"笑言哑哑，后有则也。","text":"得正，故“有则也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":11,"position":"六二：震来厉，亿丧贝，跻于九陵，勿逐，七","text":"厉，危也。乘刚，故“厉”。亿，惜辞也。坤为丧。三动离为蠃蚌，故称“贝”。在艮山下，故称“陵”。震为足，足乘初九故“跻于九陵”。震为逐，谓四已体复象，故“丧贝勿逐”。三动时离为日，震数七，故“七日得者”也。","locator":{"book":"周易集解","gua":"震","pos":"六二"},"citation":"《周易集解》·震卦·六二","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":13,"position":"六三：震苏苏，震行无眚。《象》曰：震苏苏","text":"死而复生，称苏。三死坤中，动出得正，震为生，故“苏苏”。坎为眚，三出得正，坎象不见，故“无眚”。《春秋传》曰：晋获秦谍，六日而苏也。","locator":{"book":"周易集解","gua":"震","pos":"六三"},"citation":"《周易集解》·震卦·六三","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":14,"position":"九四：震遂泥。","text":"坤土得雨为泥。位在坎中，故“遂泥”也。","locator":{"book":"周易集解","gua":"震","pos":"九四"},"citation":"《周易集解》·震卦·九四","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":15,"position":"：震遂泥，未光也。","text":"在坎阴中，与屯五同义，故“未光也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":16,"position":"六五：震往来厉，","text":"往谓乘阳，来谓应阴；失位乘刚，故“往来厉”也。","locator":{"book":"周易集解","gua":"震","pos":"六五"},"citation":"《周易集解》·震卦·六五","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":17,"position":"亿无丧有事。","text":"坤为丧也。事谓祭祀之事。出而体随，王享于西山，则可以守宗庙社稷为祭主，故“无丧有事”也。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":18,"position":"：震往来厉，危行也。","text":"乘刚山顶，故“危行也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":19,"position":"其事在中，大无丧也。","text":"动出得正，故“无丧”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":20,"position":"上六：震索索，视矍矍，","text":"上谓四也。欲之三，隔坎，故“震索索”。三已动，应在离，故“矍矍”者也。","locator":{"book":"周易集解","gua":"震","pos":"上六"},"citation":"《周易集解》·震卦·上六","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":21,"position":"征凶。震不于其躬于其邻，无咎。婚媾有言。","text":"上得位，震为征，故“征凶”。四变时，坤为躬。邻谓五也。四上之五，震东兑西，故称“邻”。之五得正，故“不于其躬于其邻，无咎”。谓三已变，上应三，震为言，故“婚媾有言”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":22,"position":"：震索索，中未得也。","text":"四未之五，故“中未得也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"震","guaId":"g51","yaoIdx":23,"position":"虽凶无咎，畏邻戒也。","text":"谓五正位，已乘之逆，“畏邻戒也”。","locator":{"book":"周易集解","gua":"震","pos":"卦辞·彖象"},"citation":"《周易集解》·震卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":0,"position":"不获其身，行其庭，不见其人，无咎。","text":"观五之三也。艮为多节，故称“背”。观坤为身，观五之三，折坤为背，故“艮其背”。坤象不见，故“不获其身”。震为行人，艮为庭，坎为隐伏，故“行其庭，不见其人”。三得正，故“无咎”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":1,"position":"：艮，止也。","text":"位穷于上，故“止也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":2,"position":"时止则止，时行则行，","text":"时止谓上阳穷止，故“止”。时行谓三体处震，为行也。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":3,"position":"动静不失其时，其道光明。","text":"动谓三，静谓上。艮止则止，震行则行，故不失时。五动成离，故“其道光明”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":4,"position":"艮其止，止其所也。","text":"谓两象各止其所。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":5,"position":"上下敌应，不相与也。","text":"艮其背，背也。两象相背，故“不相与也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":7,"position":"：兼山艮。君子以思不出其位。","text":"君子谓三也。三君子位。震为出。坎为隐伏，为思，故“以思不出其位”也。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":8,"position":"初六：艮其趾，无咎，利永贞。","text":"震为趾，故“艮其趾”矣。失位变得正故“无咎，永贞”也。","locator":{"book":"周易集解","gua":"艮","pos":"初六"},"citation":"《周易集解》·艮卦·初六","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":9,"position":"：艮其趾，未失正也。","text":"动而得正故“未失正也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":10,"position":"六二：艮其腓，不拯其随，其心不快。","text":"巽长，为股。艮小，为腓。拯，取也。随谓下二阴，艮为止，震为动，故“不拯其随”。坎为心，故“其心不快”。","locator":{"book":"周易集解","gua":"艮","pos":"六二"},"citation":"《周易集解》·艮卦·六二","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":11,"position":"：不拯其随，未违听也。","text":"坎为耳，故“未违听也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":12,"position":"九三：艮其限，裂其夤，厉阍心。","text":"限，要带处也。坎为要。五来之三，故“艮其限”。夤，脊肉。艮为背，坎为脊；艮为手。震起艮止，故“裂其夤”。坎为心。厉，危也。艮为阍。阍，守门人。坎盗动门，故“厉阍心”。古阍作熏字。马因言熏灼其心，未闻易道以坎水熏灼人也。荀氏以熏为勋，读作动。皆非也。","locator":{"book":"周易集解","gua":"艮","pos":"九三"},"citation":"《周易集解》·艮卦·九三","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":13,"position":"：艮其限，危阍心也。","text":"坎为心，坎盗动门，故“危阍心也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":14,"position":"六四：艮其身，无咎。","text":"身，腹也。观坤为身，故“艮其身”。得位承五，故“无咎”。或谓妊身也。五动则四体离妇。离为大腹，孕之象也，故“艮其身”。得正承五，而受阳施，故“无咎”。《诗》曰：大任有身，生此文王也。","locator":{"book":"周易集解","gua":"艮","pos":"六四"},"citation":"《周易集解》·艮卦·六四","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":15,"position":"：艮其身，止诸躬也。","text":"艮为止，五动乘四则妊身，故“止诸躬也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":16,"position":"六五：艮其辅，言有孚，悔亡。","text":"辅面颊骨，上颊车者也。三至上，体颐象，艮为止，在坎车上。故“艮其辅”。谓辅车相依。震为言。五失位悔也。动得正，故“言有孚，悔亡”也。","locator":{"book":"周易集解","gua":"艮","pos":"六五"},"citation":"《周易集解》·艮卦·六五","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":17,"position":"：艮其辅，以中正也。","text":"五动之中，故“以正中也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":18,"position":"上九：敦艮，吉。","text":"无应静止，下据二阴，故“敦艮，吉”也。","locator":{"book":"周易集解","gua":"艮","pos":"上九"},"citation":"《周易集解》·艮卦·上九","edition":"jijie"},{"gua":"艮","guaId":"g52","yaoIdx":19,"position":"：敦艮之吉，以厚终也。","text":"坤为厚，阳上据坤，故“以厚终也”。","locator":{"book":"周易集解","gua":"艮","pos":"卦辞·彖象"},"citation":"《周易集解》·艮卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":-1,"position":"卦辞","text":"否三之四。女，谓四。归，嫁也。坤三之四承五，进得位，往有功。反成归妹，兑女归吉。初上失位。故“利贞”，可以正邦也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞"},"citation":"《周易集解》·渐卦·卦辞","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":0,"position":"：渐之进也。女归吉也。","text":"三进四，得位。阴阳体正，故“吉”也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":1,"position":"进得位，往有功也。","text":"功谓五，四进承五，故“往有功”。巽为进也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":2,"position":"进以正，可以正邦也。其位刚得中也。","text":"谓初已变，为家人。四进已正，而上不正。三动成坤，为邦。上来反三。故“进以正，可以正邦”。其位刚得中，与家人道正同义。三在外体之中，故称“得中”。《乾?文言》曰：中不在人，谓三也。此可谓上变既济定者也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":3,"position":"止而巽，动不穷也。","text":"止，艮也。三变震为动。上之三据坤。动震成坎，坎为通。故“动不穷”。往来不穷谓之通。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":4,"position":"：山上有木，渐。君子居贤德善俗。","text":"君子谓否乾。乾为贤德。坤阴小人柔弱，为俗。乾四之坤为艮，为居。以阳善阴。故“以居贤德善俗也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":5,"position":"初六：鸿渐于干，小子厉，有言，无咎。","text":"鸿，大雁也。离五，鸿。渐，进也。小水从山流下称干。艮为山，为小径。坎水流下山。故“鸿渐于干”也。艮为小子。初失位，故“厉”。变得正。三动受上成震，震为言。故“小子厉，有言，无咎”也。","locator":{"book":"周易集解","gua":"渐","pos":"初六"},"citation":"《周易集解》·渐卦·初六","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":6,"position":"：小子之厉，义无咎也。","text":"动而得正，故“义无咎也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":7,"position":"六二：鸿渐于磐，饮食衎衎，不素饱也。","text":"艮为山石。坎为聚，聚石称磐。初已之正，体噬嗑食，坎水阳物，并在颐中，故“饮食衎衎”。得正应五，故“吉”。","locator":{"book":"周易集解","gua":"渐","pos":"六二"},"citation":"《周易集解》·渐卦·六二","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":8,"position":"：饮食衎衎，不素饱也。","text":"素，空也。承三应五，故“不素饱”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":9,"position":"九三：鸿渐于陆，","text":"高平称陆。谓初已变，坎水为平。三动之坤，故“鸿渐于陆”。","locator":{"book":"周易集解","gua":"渐","pos":"九三"},"citation":"《周易集解》·渐卦·九三","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":10,"position":"夫征不复，","text":"谓初已不正。三动成震。震为征、为夫而体复，象坎阳死坤中，坎象不见。故“夫征不复”也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":11,"position":"妇孕不育，凶。","text":"孕，妊娠也。育，生也。巽为妇，离为孕，三动成坤，离毁失位，故“妇孕不育，凶”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":12,"position":"利用御寇。","text":"御，当也。坤为用，巽为高，艮为山，离为戈兵甲胄，坎为震寇。自上御下，三动坤顺，坎象不见。故“利用御寇，顺相保”。保，大也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":13,"position":"：夫征不复，离群丑也。","text":"坤三爻为丑，物三称群也。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":14,"position":"妇孕不育，失其道也。","text":"三动离毁，阳陨坤中，故“失其道也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":15,"position":"利用御寇，顺相保也。","text":"三动坤顺，坎象不见，故以“顺相保也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":16,"position":"六四：鸿渐于木，或得其桷，无咎。","text":"巽为木。桷，椽也。方者谓之桷。巽为交，为长木，艮为小木，坎为脊，离为丽。小木丽长木，巽绳束之，象脊之形，椽桷象也，故“或得其桷”。得位顺五，故“无咎”。四已承五，又顾得三，故“或得其桷”也矣。","locator":{"book":"周易集解","gua":"渐","pos":"六四"},"citation":"《周易集解》·渐卦·六四","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":17,"position":"：或得其桷，顺以巽也。","text":"坤为顺，以巽顺五。案：四居巽，木爻，阴位正直，桷之象也。自二至五，体有离坎。离为飞鸟而居坎水，鸿之象也。鸿随阳鸟，喻女从夫。卦明渐义，爻皆称焉。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":18,"position":"九五：鸿渐于陵，妇三岁不孕，","text":"陵，丘。妇，谓四也，三动受上时，而四体半艮山，故称“陵”。巽为妇，离为孕，坎为岁，三动离坏，故“妇三岁不孕”。","locator":{"book":"周易集解","gua":"渐","pos":"九五"},"citation":"《周易集解》·渐卦·九五","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":19,"position":"终莫之胜，吉。","text":"莫，无。胜，陵也。得正居中，故“莫之胜，吉”。上终变之三，成既济定。坎为心，故《象》曰“得所愿也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":20,"position":"：终莫之胜吉，得所愿也。","text":"上之三，既济定，故“得所愿也”。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":21,"position":"上九：鸿渐于陆，","text":"陆，谓三也。三坎为平，变而成坤，故称“陆”也。","locator":{"book":"周易集解","gua":"渐","pos":"上九"},"citation":"《周易集解》·渐卦·上九","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":22,"position":"其羽可用为仪，吉。","text":"谓三变受成既济，与《家人?彖》同义。上之三得正，离为鸟。故“其羽可用为仪，吉”。三动失位，坤为乱，乾四止坤，《象》曰“不可乱”，《彖》曰“进以正邦”，为此爻发也。三已得位，又变受上权也。孔子曰：可与适道，未可与权，宜可怪焉。","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"渐","guaId":"g53","yaoIdx":23,"position":"：其羽可用为仪吉，不可乱也。","text":"坤为乱，上来正坤。六爻得位，成既济定，故“不可乱也”。干宝曰：处渐高位，断渐之进。顺艮之言，谨巽之全，履坎之通，据离之耀。妇德既终，母教又明。有德而可受，有仪而可象。故曰“其羽可以为仪，不可乱也。”","locator":{"book":"周易集解","gua":"渐","pos":"卦辞·彖象"},"citation":"《周易集解》·渐卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":-1,"position":"卦辞","text":"归，嫁也。兑为妹。泰三之四，坎月离日，俱归妹象。阴阳之义配日月，则天地交而万物通。故以嫁娶也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞"},"citation":"《周易集解》·归妹卦·卦辞","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":0,"position":"征凶，","text":"谓四也。震为征。三之四，不当位，故“征凶”也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":1,"position":"无攸利。","text":"谓三也。四之三，失正无应，以柔乘刚，故“无攸利”也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":2,"position":"：归妹，天地之大义也。","text":"乾天坤地。三之四，天地交。以离日坎月战阴阳，阴阳之义配日月，则万物兴，故“天地之大义”。乾主壬，坤主癸。日月会北。震为玄黄，天地之杂。震东兑西，离南坎北。六十四卦，此象最备四进正卦，故“天地之大义也”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":3,"position":"天地不交而万物不兴。","text":"乾三之坤四。震为兴。天地以离坎交阴阳，故“天地不交则万物不兴”矣。王肃曰：男女交而后人民蕃，天地交然后万物兴，故归妹以及天地交之义也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":4,"position":"归妹，人之终始也。","text":"人始生乾，而终于坤，故“人之终始”，《杂卦》曰：归妹，女之终，谓阴终坤癸，则乾始震庚也。干宝曰：归妹者，衰落之女也。父既没矣，兄主其礼，子续父业，人道所以相终始也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":5,"position":"说以动，所归妹也。","text":"说，兑。动，震也。谓震嫁兑所归必妹也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":9,"position":"君子以永终知敝。","text":"君子，谓乾也。坤为永终，为敝。乾为知。三之四，为永终；四之三，兑为毁折，故“以永终知敝”。崔觐曰：归妹，从之始终也。始则征凶，终则无攸利，故“君子以永终知敝”为戒者也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":10,"position":"初九：归妹以娣，跛而履，征吉。","text":"震为兄，故“嫁妹”。谓三也。初在三下，动而应四，故称“娣”。履，礼也。初九应变成坎，坎为曳，故“跛而履”。应在震，为征。初为娣。变为阴，故“征吉”也。","locator":{"book":"周易集解","gua":"归妹","pos":"初九"},"citation":"《周易集解》·归妹卦·初九","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":11,"position":"：归妹以娣，以恒也。跛而履，吉相承也。","text":"阳得正，故“以恒”。恒动初承二，故“吉相承也”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":12,"position":"九二：眇而视，利幽人之贞。","text":"视，应五也。震上兑下，离正，故“眇而视”。幽人，谓二。初动，二在坎中，故称“幽人”。变得正，震喜兑说，故“利幽人之贞”。与履二同义也。","locator":{"book":"周易集解","gua":"归妹","pos":"九二"},"citation":"《周易集解》·归妹卦·九二","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":13,"position":"：利幽人之贞，未变常也。","text":"常，恒也。乘初未之五，故“未变常也”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":14,"position":"六三：归妹以须，反归以娣。","text":"须，需也。初至五，体需象，故“归妹以须”。娣，谓初也。震为反，反马归也。三失位，四反得正。兑进在四，见初进之，初在兑后，故“反归以娣”。","locator":{"book":"周易集解","gua":"归妹","pos":"六三"},"citation":"《周易集解》·归妹卦·六三","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":15,"position":"：归妹以须，位未当也。","text":"三未变之阳，故“位未当”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":16,"position":"九四：归妹愆期，迟归有时。","text":"愆，过也。谓二变，三动之正，体大过象。坎月离日，为期三变。日月不见。故“愆期”。坎为曳，震为行，行曳，故“迟”也。归谓反三。震春兑秋，坎冬离夏，四时体正，故“归有时”也。","locator":{"book":"周易集解","gua":"归妹","pos":"九四"},"citation":"《周易集解》·归妹卦·九四","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":17,"position":"：愆期之志，有待而行也。","text":"待男行矣。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":18,"position":"六五：帝乙归妹，其君之袂，不如其娣之袂良","text":"三四已正。震为帝，坤为乙，故曰“帝乙”。泰乾为良，为君。乾在下，为小君，则妹也。袂，口袂之饰也。兑为口，乾为衣，故称“袂”。谓三失位无应。娣袂，谓二得中应五，三动成乾，为良，故“其君之袂，不如其娣之袂良”。故《象》曰：“以贵行也”矣。","locator":{"book":"周易集解","gua":"归妹","pos":"六五"},"citation":"《周易集解》·归妹卦·六五","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":19,"position":"月几望，吉。","text":"几，其也。坎月离日，兑西震东，日月象对，对曰“几望”。二之五，四复三，得正，故“吉”也。与小畜、中孚月几望同义也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":20,"position":"：帝乙归妹，不如其娣之袂良也。","text":"三四复正，乾为良。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":21,"position":"其位在中，以贵行也。","text":"三四复，二之五，成既济。五贵，故“以贵行也”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":22,"position":"上六：女承筐无实，","text":"女谓应三，兑三。逢下受上称承。震为筐。以阴应阴，三四复位，坤为虚，故“无实”。《象》曰：“承虚筐也”。","locator":{"book":"周易集解","gua":"归妹","pos":"上六"},"citation":"《周易集解》·归妹卦·上六","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":23,"position":"士刲羊无血，无攸利。","text":"刲，刺也。震为士，兑为羊，离为刀，故“士刲羊”。三四复位成泰，坎象不见，故“无血”。三柔乘刚，故“无攸利”也。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"归妹","guaId":"g54","yaoIdx":24,"position":"：上六无实，承虚筐也。","text":"泰坤为虚，故“承虚筐也”。","locator":{"book":"周易集解","gua":"归妹","pos":"卦辞·彖象"},"citation":"《周易集解》·归妹卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":-1,"position":"卦辞","text":"此卦三阴三阳之例，当从泰二之四。而丰三从噬嗑上来之三，折四于坎狱中而在丰，故“君子以折狱致刑”。阴阳交，故“通”。噬嗑所谓利用狱者，此卦之谓也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞"},"citation":"《周易集解》·丰卦·卦辞","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":0,"position":"王假之，","text":"乾为王。假，至也。谓四宜上至五，动之正成乾，故“王假之，尚大也”。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":1,"position":"勿忧，宜日中。","text":"五动之正，则四变成离。离，日。中，当。五地坎中，坎为忧。故“勿忧，宜日中”。体两离象，照天下也。日中则昃，月盈则食，天地盈虚，与时消息。干宝曰：丰坎宫阴，世在五。以其宜中，而忧其侧也。坎为夜，离为昼，以离变坎，至于天位，日中之象也。圣人德大而心小，既居天位，而戒惧不担勿忧者，劝勉之言也。犹《诗》曰：上帝临尔，无贰尔心。言周德当天人之心，宜居王位，故“宜日中”。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":5,"position":"宜照天下也。","text":"五动成乾，乾为天。四动成两离，重明丽正，故“宜照天下”。谓化成天下也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":7,"position":"月盈则食，","text":"月之行，生震见兑，盈于乾甲，五动成乾，故“月盈”。四变体噬嗑食，故“则食”。此丰其屋，蔀其家也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":8,"position":"天地盈虚，与时消息，而况于人乎，况于鬼神","text":"五息成乾，为盈；四消入坤，为虚，故“天地盈虚”也。丰之既济，四时象具。乾为神人，坤为鬼，鬼神与人，亦随进消息。谓人谋鬼谋，百姓与能，与时消息。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":10,"position":"君子以折狱致刑。","text":"君子谓三。噬嗑四失正，系在坎狱中，故上之三。折四入大过，死象。故“以折狱致刑”。兑折为刑，贲三得正，胡无敢折狱也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":11,"position":"初九，遇其配主，","text":"妃嫔，谓四也。四失位在震，为主；五动体姤遇，故“遇其配主”也。","locator":{"book":"周易集解","gua":"丰","pos":"初九"},"citation":"《周易集解》·丰卦·初九","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":12,"position":"虽旬无咎，往有尚。","text":"谓四失位，变成坤，应初。坤数十，四上之五，成离。离为日。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":13,"position":"：虽旬无咎，过旬灾也。","text":"体大过，故“过旬灾”。四上之五，坎为灾也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":14,"position":"六二：丰其蔀，日中见斗，往得疑疾。","text":"日蔽云中，称蔀。蔀，小，谓四也。二利四之五，故“丰其蔀”。噬嗑离为见，象在上，为日中。艮为斗，斗七星也。噬嗑艮为星，为止，坎为北中，巽为高舞。星止于中而舞者，北斗多象也。离上之三，隐坎云下，故“日中见斗”。四往之五，得正成坎，坎为疑疾，故“往得疑疾”也。","locator":{"book":"周易集解","gua":"丰","pos":"六二"},"citation":"《周易集解》·丰卦·六二","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":15,"position":"有孚发若，吉。","text":"坎为孚，四发之五成坎孚，动而复合闰，故“有孚发若，吉”也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":16,"position":"：有孚发若，信以发志也。","text":"四发之五，坎为志也。《九家易》曰：信着于五，然后乃可发其顺志。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":17,"position":"九三：丰其沛，日中见沫，","text":"日在云下称沛。沛，不明也。沫，小星也。噬嗑离为日，艮为沫。故“日中见沫”。上之三，日入坎云下，故“见沫”也。《九家易》曰：大暗谓之沛。沫，斗杓后小星也。","locator":{"book":"周易集解","gua":"丰","pos":"九三"},"citation":"《周易集解》·丰卦·九三","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":18,"position":"折其右肱，无咎。","text":"日在云下称沛。沛，不明也。沫，小星也。噬嗑离为日，艮为沫。故“日中见沫”。上之三，日入坎云下，故“见沫”也。《九家易》曰：大暗谓之渍。沫，斗杓后小星也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":19,"position":"折其右肱，无咎。","text":"兑为折，为右。噬嗑艮为肱。上来之三，折艮入兑，故“折其右肱”。之三得正，故“无咎”也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":20,"position":"：丰其沛，不可大事也。","text":"利四之阴，故“不可大事”。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":21,"position":"折其右肱，终不可用也。","text":"四死大过，故“终不可用”。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":22,"position":"九四，丰其蔀，","text":"蔀，蔽也。噬嗑离日之坎云中，故“丰其蔀”。《象》曰“位不当也”。","locator":{"book":"周易集解","gua":"丰","pos":"九四"},"citation":"《周易集解》·丰卦·九四","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":23,"position":"日中见斗，","text":"噬嗑日在上，为中。上之三为巽，巽为入。日入坎云下，幽伏不明，故“日中见斗”。《象》曰“幽不明”，是其义也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":24,"position":"遇其夷主，吉。","text":"震为主。四行之正成明夷，则三体震，为夷主，故“遇其夷主，吉”也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":26,"position":"：丰其蔀，位不当也。日中见斗，幽不明也。","text":"离上变入坎云下，故“幽不明”。坎，幽也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":27,"position":"遇其夷主，吉行也。","text":"动体明夷。震为行，故曰“吉行”。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":28,"position":"六五：来章，有庆誉，吉。","text":"在内称来。章，显也。庆谓五。阳出称庆也。誉谓二，二多誉。五发得正，则来应二。故“来章，有庆誉，吉”也。","locator":{"book":"周易集解","gua":"丰","pos":"六五"},"citation":"《周易集解》·丰卦·六五","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":29,"position":"：六五之吉，有庆也。","text":"动而成乾，乾为庆。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":30,"position":"上六：丰其屋，蔀其家。","text":"丰，大。蔀，小也。三至上，体大壮，屋象，故“丰其屋”。谓四五已变，上动成家人。大屋见则家人坏，故“蔀其家”。与泰二同义。故《象》曰：天际祥明，以大壮为屋象故也。","locator":{"book":"周易集解","gua":"丰","pos":"上六"},"citation":"《周易集解》·丰卦·上六","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":31,"position":"窥其户，阒其无人。三岁不觌，凶。","text":"谓从外窥三应。阒，空也。四动时坤为阖。户，阖。故“窥其户”。坤为空虚，三隐伏坎中，故“阒其无人”。《象》曰“自藏也”。四五易位，噬嗑离目，为窥。窥人者，言皆不见。坎为三岁，坎冥在上，离象不见。故“三岁不觌，凶”。干宝曰：在丰之家，居乾之位，乾为屋宇，故曰“丰其屋”。此盖记纣之侈，造为璿室玉台也。蔀其家者，以记纣多倾国之女也。社稷既亡，宫室虚旷，故曰“窥其户，阒其无人”。阒，无人貌也。三者，天地人之数也。凡国于天地有兴亡焉。故王者之亡其家也。必天示其祥，地出其妖，人反其常，非斯三者，亦弗之亡也。故曰“三岁不觌，凶”。然则璿室之成，三年而后亡国矣。案：上应于三，三互离，巽为户，离为目，目而近户，窥之象也。既屋丰家蔀，若窥地户，阒寂无人。震木，数三，故三岁致凶于灾。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"丰","guaId":"g55","yaoIdx":33,"position":"窥其户，阒其无人，自藏也。","text":"谓三隐伏坎中，故“自藏”者也。","locator":{"book":"周易集解","gua":"丰","pos":"卦辞·彖象"},"citation":"《周易集解》·丰卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":-1,"position":"卦辞","text":"贲初之四，否三之五，非乾坤往来也。与噬嗑之丰同义。小，谓柔得贵位而顺刚。丽乎大明。故“旅小亨，旅贞吉”。再言旅者，谓四凶恶，进退无恒，无所容处。故再言旅，恶而愍之。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞"},"citation":"《周易集解》·旅卦·卦辞","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":2,"position":"旅之时义大矣哉。","text":"以离日丽天，县象着明，莫大日月，故义大也。王弼曰：旅者，物失其所居之时也。物失所居，则咸愿有附，岂非智者有为之时？故曰“旅之时义大矣哉”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":4,"position":"君子以明慎用刑，而不留狱。","text":"君子谓三。离为明，艮为慎，兑为刑，坎为狱。贲初之四，狱象不见。故“以明慎用刑，而不留狱”。与丰折狱同义者也。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":6,"position":"：旅琐琐，志穷灾也。","text":"琐琐，最蔽之貌也。失位远应，之正介坎。坎为灾眚，艮手为取，谓三动应坎。坎为志，坤称穷，故曰“志穷灾也”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":8,"position":"：得僮仆贞，终无尤也。","text":"艮为僮仆，得正承三，故“得僮仆贞，而终无尤也”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":9,"position":"九三：旅焚其次，丧其僮仆，贞厉。","text":"离为火，艮为僮仆。三动艮坏，故“焚其次”。坤为丧，三动艮灭入坤，故“丧其僮仆”。动而失正，故“贞厉”矣。","locator":{"book":"周易集解","gua":"旅","pos":"九三"},"citation":"《周易集解》·旅卦·九三","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":10,"position":"：旅焚其次，亦以伤矣。","text":"三动体剥，故伤也。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":11,"position":"以旅与下，其义丧也。","text":"三变成坤。坤为下，为丧，故“其义丧也“。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":12,"position":"九四：旅于处，得其资斧，我心不快。","text":"巽为处。四焚弃，恶人失位远应。故“旅于处”，言无所从也。离为资斧，故“得其资斧”。三动，四坎为心，其位未至，故“我心不快”也。","locator":{"book":"周易集解","gua":"旅","pos":"九四"},"citation":"《周易集解》·旅卦·九四","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":14,"position":"六五：射雉，一矢亡，","text":"三变坎为弓，离为矢，故“射雉”。五变乾体，矢动雉飞，故“一矢亡”矣。","locator":{"book":"周易集解","gua":"旅","pos":"六五"},"citation":"《周易集解》·旅卦·六五","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":15,"position":"终以誉命。","text":"誉谓二。巽为命。五终变成乾，则二来应已，故“终以誉命”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":16,"position":"：终以誉命，上逮也。","text":"逮，及也。谓二上及也。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":17,"position":"上九：鸟焚其巢，旅人先笑后号咷，","text":"离为鸟，为火；巽为木，为高。四失位变震，为筐，巢之象也。今巢象不见，故“鸟焚其巢”。震为笑，震在前，故“先笑”。应在巽，巽为号咷，巽象在后。故“后号咷”。","locator":{"book":"周易集解","gua":"旅","pos":"上九"},"citation":"《周易集解》·旅卦·上九","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":18,"position":"丧牛于易，凶。","text":"谓三动时坤为牛。五动成乾，乾为易。上失三，五动应二。故“丧牛于易”。失位无应故“凶也”。五动成遁，六二：“执之用黄牛之革，”则旅家所丧牛也。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":19,"position":"：以旅在上，其义焚也。","text":"离火焚巢，故“其义焚也”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"旅","guaId":"g56","yaoIdx":20,"position":"丧牛于易，终莫之闻也。","text":"坎耳入兑，故“终莫之闻”。","locator":{"book":"周易集解","gua":"旅","pos":"卦辞·彖象"},"citation":"《周易集解》·旅卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":-1,"position":"卦辞","text":"遁二之四，柔得位而顺五刚，故“小亨”也。大人谓五。离目为见。二失位，利正往应五。故“利有攸往，利见大人”矣。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞"},"citation":"《周易集解》·巽卦·卦辞","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":4,"position":"：随风，巽。君子以申命行事。","text":"君子，谓遁乾也。巽为命，重象，故“申命”。变至三，坤为事，震为行，故“行事”也。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":5,"position":"初六：进退，利武人之贞。","text":"巽为进退。乾为武人。初失位，利之正为乾，故“利武人之贞”矣。","locator":{"book":"周易集解","gua":"巽","pos":"初六"},"citation":"《周易集解》·巽卦·初六","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":7,"position":"利武人之贞，志治也。","text":"动而成乾，乾为大明，故“志治”。乾元用九，天下治，是其义也。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":11,"position":"九三：频巽，吝。","text":"频，頞也。谓二已变。三体坎艮，坎为忧，艮为鼻，故“频巽”。无应在险，故“吝”也。","locator":{"book":"周易集解","gua":"巽","pos":"九三"},"citation":"《周易集解》·巽卦·九三","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":13,"position":"六四：悔亡，田获三品。","text":"田，谓二也。地中称田，失位无应，悔也。欲二之初，已得应之，故“悔亡”。二动得正，处中应五。五多功，故《象》曰“有功也”。二动艮为手，故称“获”。谓艮为狼，坎为豕。艮二之初，离为雉。故“获三品”矣。翟元曰：田获三品，下三爻也：谓初巽为鸡；二兑为羊，三离为雉也。","locator":{"book":"周易集解","gua":"巽","pos":"六四"},"citation":"《周易集解》·巽卦·六四","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":15,"position":"九五：贞吉，悔亡，无不利，无初有终。","text":"得位处中，故“贞吉，悔亡，无不利”也。震巽相薄，雷风无形，当变之震矣。巽究为躁卦，故“无初有终”也。","locator":{"book":"周易集解","gua":"巽","pos":"九五"},"citation":"《周易集解》·巽卦·九五","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":16,"position":"先庚三日，后庚三日，吉。","text":"震，庚也。谓变初至二成离，至三成震，震主庚。离为日，震三爻在前，故“先庚三日”。谓益时也。动四至五成离，终上成震，震三爻在后，故“后庚三日”也。巽初失正，终变成震，得位，故“无初有终”，“吉”。震究为蕃鲜白，谓巽也。巽究为躁卦。躁卦，谓震也。与蛊“先甲三日，后甲三日”同义。五动成蛊，乾成于甲，震成于庚，阴阳天地之始终，故经举甲庚于《蛊?彖》、《巽五》也。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":17,"position":"：九五之吉，位正中也。","text":"居中得正，故“吉”矣。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":18,"position":"上九：巽在床下，","text":"床下，谓初也。穷上反下成震，故“巽在床下”。《象》曰：“上穷也”。明当变穷上而复初也。《九家易》曰：上为宗庙。礼封赏出军，皆先告庙，然后受行。三军之命，将之所专。故曰“巽在床下”也。","locator":{"book":"周易集解","gua":"巽","pos":"上九"},"citation":"《周易集解》·巽卦·上九","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":19,"position":"丧其齐斧，贞凶。","text":"变至三时，离毁入坤。坤为丧，巽为齐，离为斧，故“丧其齐斧”。三变失位故“贞凶”。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":20,"position":"：巽在床下，上穷也。","text":"阳穷上反下，故曰“上穷也”。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"巽","guaId":"g57","yaoIdx":21,"position":"丧其齐斧，正乎凶也。","text":"上应于三，三动失正，故曰“正乎凶也”。","locator":{"book":"周易集解","gua":"巽","pos":"卦辞·彖象"},"citation":"《周易集解》·巽卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":-1,"position":"卦辞","text":"大壮五之三也。刚中而柔外，二失正，动应五承三，故“亨利贞”也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞"},"citation":"《周易集解》·兑卦·卦辞","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":0,"position":"：兑，说也。","text":"兑口，故说也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":1,"position":"刚中而柔外，说以利贞，","text":"刚中谓二五，柔外谓三上也。二、三、四利之正，故“说以利贞”也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":2,"position":"是以顺乎天而应乎人。","text":"大壮乾为天，谓五也。人谓三矣。二变顺五承三，故“顺乎天应乎人”。坤为顺也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":3,"position":"说以先民，民忘其劳；","text":"谓二、四已变成屯。坎为劳，震喜，兑说，坤为民，坎为心，民心喜说，有顺比象，故“忘其劳”也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":4,"position":"说以犯难，民忘其死，","text":"体屯，故“难”也。三至上，体大过死。变成屯，民说无疆。故“民忘其死”。坎心为忘，或以坤为死也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":5,"position":"说之大民劝矣哉。","text":"体比顺象，故劳而不怨。震为喜笑，故人劝也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":6,"position":"：丽泽，兑，君子以朋友讲习。","text":"君子，大壮乾也。阳息见兑，学以聚之，问以辩之。兑二阳同类为朋，伏艮为友，坎为习，震为讲，兑两口对，故“朋友讲习”也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":7,"position":"初九：和兑，吉。","text":"得位，四变应已，故“和兑，吉”矣。","locator":{"book":"周易集解","gua":"兑","pos":"初九"},"citation":"《周易集解》·兑卦·初九","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":8,"position":"：和兑之吉，行未疑也。","text":"四变应初，震为行，坎为疑，故“行未疑”。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":9,"position":"九三：孚兑，吉，悔亡。","text":"孚谓五也。四已变，五在坎中，称孚。二动得位，应之，故“孚兑，吉，悔亡”矣。","locator":{"book":"周易集解","gua":"兑","pos":"九三"},"citation":"《周易集解》·兑卦·九三","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":10,"position":"：孚兑之吉，信志也。","text":"二变应五，谓四已变，坎为志，故“信志也”。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":11,"position":"六三：来兑，凶。","text":"从大壮来，失位，故“来兑，凶”矣。","locator":{"book":"周易集解","gua":"兑","pos":"六三"},"citation":"《周易集解》·兑卦·六三","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":13,"position":"九四：商兑未宁，介疾有喜。","text":"巽为近利市三倍，故称“商兑”。变之坎，水性流。震为行。谓二已变，体比象，故“未宁”与比“不宁方来”同义也。坎为疾，故“介疾”。得位承五，故“有喜”。","locator":{"book":"周易集解","gua":"兑","pos":"九四"},"citation":"《周易集解》·兑卦·九四","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":14,"position":"：九四之喜，有庆也。","text":"阳为庆，谓五也。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":15,"position":"九五：孚于剥，有厉。","text":"孚，谓五也。二四变，体剥象故“孚于剥”。在坎未光，“有厉”也。","locator":{"book":"周易集解","gua":"兑","pos":"九五"},"citation":"《周易集解》·兑卦·九五","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":17,"position":"上六：引兑。","text":"无应乘阳。动而之巽，为绳。艮为手。应在三，三未之正。故“引兑”也。","locator":{"book":"周易集解","gua":"兑","pos":"上六"},"citation":"《周易集解》·兑卦·上六","edition":"jijie"},{"gua":"兑","guaId":"g58","yaoIdx":18,"position":"：上六引兑，未光也。","text":"二四已变而体屯，上三未为离，故“未光也”。","locator":{"book":"周易集解","gua":"兑","pos":"卦辞·彖象"},"citation":"《周易集解》·兑卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":-1,"position":"卦辞","text":"否四之二成坎巽，天地交，故“亨”也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞"},"citation":"《周易集解》·涣卦·卦辞","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":0,"position":"王假有庙，","text":"乾为王。假，至也。否体观。艮为宗庙；乾四之坤二。故“王假有庙，王乃在中也”。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":1,"position":"利涉大川，利贞。","text":"坎为大川。涣，舟楫象。故“涉大川”。乘木有功，二失正，变应五，故利居贞也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":3,"position":"利涉大川，乘木有功也。","text":"巽为木，坎为水，故“乘木有功也”。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":4,"position":"：风行水上，涣。先王以享于帝，立庙。","text":"否乾为先王。享，祭也。震为帝、为祭。艮为庙。四之二，杀坤大牲。故以享帝立庙。谓成既济，有噬嗑食象故也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":5,"position":"初六：用拯马壮，吉。","text":"坎为马。初失正，动体大壮。得位。故“拯马壮吉”，悔亡之矣。","locator":{"book":"周易集解","gua":"涣","pos":"初六"},"citation":"《周易集解》·涣卦·初六","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":6,"position":"：初六之吉，顺也。","text":"承二，故顺也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":7,"position":"九二：涣奔其机，悔亡。","text":"震为奔，坎为棘，为矫輮。震为足。輮棘有足，艮肱据之，凭机之象也。涣宗庙中，故设机。二失位，变得正，故“涣奔其机，悔亡”也。","locator":{"book":"周易集解","gua":"涣","pos":"九二"},"citation":"《周易集解》·涣卦·九二","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":8,"position":"：涣奔其机，得愿也。","text":"动而得位，故“得愿也”。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":11,"position":"六四：涣其群，元吉。","text":"谓二已变成坤，坤三爻称群，得位顺五，故“元吉”也。","locator":{"book":"周易集解","gua":"涣","pos":"六四"},"citation":"《周易集解》·涣卦·六四","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":12,"position":"涣有丘，匪夷所思。","text":"位半艮山，故称丘。匪，非也。夷谓震，四应在初，三变坎为思，故“匪夷所思”也。卢氏曰：自二居四，离其群侣，涣其群民得位承尊，故“元吉”也。互体有艮，艮为山丘。涣群虽则光大，有丘则非平易，故有匪夷之思也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":13,"position":"：涣其群元吉，光大也。","text":"谓三已变成离，故四“光大也”。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":15,"position":"涣王居，无咎。","text":"五为王。艮为居，正位居五，四阴顺命。故“王居无咎，正位也”。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":16,"position":"上九：涣其血，去逖，出，无咎。","text":"应在三。坎为血，为逖。逖，忧也。二变为观，坎象不见。故“其血去逖，出，无咎。”","locator":{"book":"周易集解","gua":"涣","pos":"上九"},"citation":"《周易集解》·涣卦·上九","edition":"jijie"},{"gua":"涣","guaId":"g59","yaoIdx":17,"position":"：涣其血，远害也。","text":"乾为远，坤为害，体遁上，故“远害”也。","locator":{"book":"周易集解","gua":"涣","pos":"卦辞·彖象"},"citation":"《周易集解》·涣卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":-1,"position":"卦辞","text":"泰三之五，天地交也。五当位以节，中正以通，故“节亨”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞"},"citation":"《周易集解》·节卦·卦辞","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":0,"position":"苦节不可贞。","text":"谓上也，应在三。三变成离，火炎上作，苦位在火上，故“苦节”。虽得位乘阳，故“不可贞”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":1,"position":"：节亨，刚柔分而刚得中，","text":"位极于上，乘阳，故“穷”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":2,"position":"说以行险，","text":"兑说，坎险，震为行，故“说以行险”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":3,"position":"当位以节，中正以通，","text":"中正谓五。坎为通也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":4,"position":"天地节而四时成。","text":"泰乾天，坤地；震春，兑秋。坎冬。三动，离为夏。故“天地节而四时成”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":5,"position":"节以制度，不伤财，不害民。","text":"艮手称制。坤数十，数度。坤又为害，为民，为财。二动体剥，剥为伤。三出复位，成既济定，坤剥不见。故“节以制度，不伤财，不害民”。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":7,"position":"君子以制数度，议德行。","text":"君子，泰乾也。艮止为制，坤为度，震为议，为行，乾为德，故“以制数度，议德行。”乾三之五，为“制数度”。坤五之乾，为“议德行”也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":8,"position":"初九：不出户庭，无咎。","text":"泰坤为户，艮为庭，震为出；初得位应四，故“不出户庭，无咎”矣。","locator":{"book":"周易集解","gua":"节","pos":"初九"},"citation":"《周易集解》·节卦·初九","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":9,"position":"：不出户庭，知通塞也。","text":"坎为通，二变坤土壅初为塞。崔觐曰：为节之始，有应所四。四为坎险，不通之象。以节崇塞，虽不通，可谓知通塞矣。户庭，室庭也。慎密守节，故“不出”焉，而无咎也。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":10,"position":"九二：不出门庭，凶。","text":"变而之坤，艮为门庭。二失位不变，出门应五，则凶。故“言不出门庭，凶”矣。","locator":{"book":"周易集解","gua":"节","pos":"九二"},"citation":"《周易集解》·节卦·九二","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":11,"position":"：不出门庭凶，失时极也。","text":"极，中也。未变之正，失时极矣。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":12,"position":"六三：不节若，则嗟若，无咎。","text":"三，节家君子也。失位，故节若。嗟，哀号声。震为音声，为出。三动得正，而体离坎，涕流出目，故“则嗟若”。得位乘二，故“无咎”也。","locator":{"book":"周易集解","gua":"节","pos":"六三"},"citation":"《周易集解》·节卦·六三","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":14,"position":"六四：安节，亨。","text":"二已变，艮止坤安。得正承五，有应于初，故“安节亨”。","locator":{"book":"周易集解","gua":"节","pos":"六四"},"citation":"《周易集解》·节卦·六四","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":16,"position":"九五：甘节，吉。往有尚。","text":"得正居中，坎为美，故“甘节吉”。往谓二。二失正，变往应五，故“往有尚”也。","locator":{"book":"周易集解","gua":"节","pos":"九五"},"citation":"《周易集解》·节卦·九五","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":17,"position":"：甘节之吉，居位中也。","text":"艮为居，五为中，故“居位中也”。","locator":{"book":"周易集解","gua":"节","pos":"卦辞·彖象"},"citation":"《周易集解》·节卦·卦辞·彖象","edition":"jijie"},{"gua":"节","guaId":"g60","yaoIdx":18,"position":"上六：苦节，贞凶，悔亡。","text":"二三变，有两离，火炎上作苦，故“苦节”。乘阳，故“贞凶”。得位，故“悔亡”。干宝曰：《彖》称苦节不可贞，在此爻也。禀险伏之教，怀贪狠之志，以苦节之性，而遇甘节之主，必受其诛，华士、少正卯之爻也。故曰“贞凶”。苦节既凶，甘节志得，故曰“悔亡”。","locator":{"book":"周易集解","gua":"节","pos":"上六"},"citation":"《周易集解》·节卦·上六","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":-1,"position":"卦辞","text":"讼四之初也。坎孚象在中，谓二也，故称“中孚”。此当从四阳二阴之例。遁阴未及三，而大壮阳已至四，故从讼来。二在讼时，体离为鹤。在坎阴中，有“鸣鹤在阴”之义也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞"},"citation":"《周易集解》·中孚卦·卦辞","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":1,"position":"利涉大川。","text":"坎为大川。谓二已化邦，三利出涉坎。得正，体涣。涣，舟楫象。故“利涉大川，乘木舟虚也”。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":2,"position":"利贞。","text":"谓二利之正，而应五也。中孚以利贞，乃应于天也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":4,"position":"乃化邦也。","text":"二化应五成坤，坤为邦，故“化邦”也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":7,"position":"中孚以利贞，乃应乎天也。","text":"讼乾为天，二动应乾，故“乃应乎天也”。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":9,"position":"君子以议狱缓死。","text":"君子，谓乾也。讼坎为狱；震为议，为缓；坤为死。乾四之初，则二出坎狱。兑说震喜，坎狱不见，故“议狱缓死”也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":12,"position":"九二：鸣鹤在阴，其子和之，我有好爵，吾与","text":"靡，共也。震为鸣；讼离为鹤，坎为阴夜，鹤知夜半。故“鸣鹤在阴”。二动成坤，体益。五艮为子，震巽同声者相应，故“其子和之”。坤为身故称“我”。吾，谓五也。离为爵，爵，位也。坤为邦国，五在艮，阍寺庭阙之象。故称“好爵”。五利二变，之正应坎，故“吾与尔靡之”矣。","locator":{"book":"周易集解","gua":"中孚","pos":"九二"},"citation":"《周易集解》·中孚卦·九二","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":13,"position":"：其子和之，中心愿也。","text":"坎为心，动得正应五，故“中心愿也”。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":16,"position":"六四：月几望，马匹亡，无咎。","text":"讼坎为月，离为日。兑西震东。月在兑二，离为震三，日月象对。故“月几望”。乾坎两马匹，初四易位，震为奔走，体遁山中，乾坎不见，故“马匹亡”。初四易位，故“无咎”矣。","locator":{"book":"周易集解","gua":"中孚","pos":"六四"},"citation":"《周易集解》·中孚卦·六四","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":17,"position":"：马匹亡，绝类上也。","text":"讼初之四，体与上绝，故“绝类上”也。","locator":{"book":"周易集解","gua":"中孚","pos":"卦辞·彖象"},"citation":"《周易集解》·中孚卦·卦辞·彖象","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":18,"position":"九五：有孚挛如，无咎。","text":"孚，信也。谓二在坎为孚，巽绳艮手，故“挛”。二使化为邦，得正应已，故“无咎”也。","locator":{"book":"周易集解","gua":"中孚","pos":"九五"},"citation":"《周易集解》·中孚卦·九五","edition":"jijie"},{"gua":"中孚","guaId":"g61","yaoIdx":20,"position":"上九：翰音登于天，贞凶。","text":"巽为鸡，应在震，震为音。翰，高也。巽为高，乾为天。故“翰音登于天”。失位，故“贞凶”。《礼》荐牲，鸡称翰音也。","locator":{"book":"周易集解","gua":"中孚","pos":"上九"},"citation":"《周易集解》·中孚卦·上九","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":-1,"position":"卦辞","text":"晋上之三。当从四阴二阳，临观之例。临阳未至三，而观四已消也；又有飞鸟之象，故知从晋来。杵臼之利，盖取诸此。柔得中而应乾刚，故“亨”。五失正，故利贞。“过以利贞，与时行也。”","locator":{"book":"周易集解","gua":"小过","pos":"卦辞"},"citation":"《周易集解》·小过卦·卦辞","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":0,"position":"可小事，","text":"小谓五。晋坤为事。柔得中。故“可小事”也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":1,"position":"不可大事。","text":"大事，四。刚失位而不中。故“不可大事”也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":2,"position":"飞鸟遗之音，不宜上，宜下，大吉。","text":"离为飞鸟，震为音，艮为止。晋上之三，离去震在，鸟飞而音止。故“飞鸟遗之音”。上阴乘阳，故“不宜上”。下阴顺阳，故“宜下，大吉”。俗说或以卦象二阳在内，四阴在外，有似飞鸟之象，妄矣。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":4,"position":"柔得中，是以小事吉也。","text":"谓五也。阴称小，故“小事吉也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":5,"position":"刚失位而不中，是以不可大事也。","text":"谓四也。阳称大，故“不可大事也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":9,"position":"君子以行过乎恭，","text":"君子，谓三也。上贵三贱，晋上之三，震为行，故“行过乎恭”。谓三致恭以存其位，与谦三同义。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":10,"position":"丧过乎哀，","text":"晋坤为丧，离为目，艮为鼻，坎为涕洟。震为出，涕洟出鼻目：体大过，遭死丧，过乎哀也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":11,"position":"用过乎俭。","text":"坤为财用，为吝啬。艮为止，兑为校小用密止，云不雨。故“用过乎俭”也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":12,"position":"初六：飞鸟以凶。","text":"应四。离为飞鸟。上之三，则四折入，大过死，故“飞鸟以凶”。","locator":{"book":"周易集解","gua":"小过","pos":"初六"},"citation":"《周易集解》·小过卦·初六","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":13,"position":"：飞鸟以凶，不可如何也。","text":"四死大过，故“不可如何也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":14,"position":"六二：过其祖，遇其妣","text":"祖谓祖母，初也。母死称妣。谓三坤为丧，为母，折入大过死，故称“祖”也。妣二过初，故“过其祖”五变，三体姤遇，故遇妣也。","locator":{"book":"周易集解","gua":"小过","pos":"六二"},"citation":"《周易集解》·小过卦·六二","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":15,"position":"不及其君，遇其臣，无咎。","text":"五动为君，晋坎为臣；二之五隔三；艮为止，故“不及其君”止。如承三得正，体姤遇象，故“遇其臣，无咎”也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":16,"position":"：不及其君，臣不可过也。","text":"体大过，下止，舍巽下，故“不可过”。与随三同义。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":17,"position":"九三：弗过防之，从或戕之，凶。","text":"防，防四也。失位从或，而欲折之初。戕，杀也。离为戈兵，三从离上入坤，折四死大过中，故“从或戕之，凶”也。","locator":{"book":"周易集解","gua":"小过","pos":"九三"},"citation":"《周易集解》·小过卦·九三","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":18,"position":"：从或戕之，凶如何也。","text":"三来戕四，故“凶如何也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":21,"position":"：弗过遇之，位不当也。往厉必戒，终不可长","text":"体否上倾，故“终不可长”矣。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":22,"position":"六五：密云不雨，自我西郊。","text":"密，小也。晋坎，在天为云，坠地成雨。上来之三，折坎入兑，小为密。坤为自我。兑为西。五动乾为郊。故“密云不雨，自我西郊”也。","locator":{"book":"周易集解","gua":"小过","pos":"六五"},"citation":"《周易集解》·小过卦·六五","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":23,"position":"公弋取彼在穴。","text":"公谓三也。弋，矰缴射也。坎为弓弹。离为鸟矢。弋无矢也，巽绳连鸟，弋人鸟之象。艮为手，二为穴，手入穴中，故“公弋取彼在穴”也。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":24,"position":"：密云不雨，已上也。","text":"谓三坎水，已之上六，故“已上也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":25,"position":"上六：弗遇过之，飞鸟离之，凶，是谓灾眚。","text":"谓四已变之坤，上得之三，故“弗遇过之”。离为飞鸟，公弋得之，鸟下入艮手而死，故“飞鸟离之凶”。晋坎为灾眚，故“是谓灾眚”矣。","locator":{"book":"周易集解","gua":"小过","pos":"上六"},"citation":"《周易集解》·小过卦·上六","edition":"jijie"},{"gua":"小过","guaId":"g62","yaoIdx":26,"position":"：弗遇过之，已亢之。","text":"飞下称亢。晋上之三，故“已亢也”。","locator":{"book":"周易集解","gua":"小过","pos":"卦辞·彖象"},"citation":"《周易集解》·小过卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":-1,"position":"卦辞","text":"泰五之二。小，谓二也。柔得中。故“亨斜。六爻得位，各正性命，保合大和故“利贞”矣。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞"},"citation":"《周易集解》·既济卦·卦辞","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":0,"position":"初吉，","text":"初，始也。谓泰乾。乾知大始，故称“初”。坤五之乾二，得正处中，故“初吉，柔得中也。”","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":1,"position":"终乱。","text":"泰坤称乱。二上之五，终止于泰，则反成否。子弑其父，臣弑其君天下无邦，终穷成坤，故“乱，其道穷”。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":4,"position":"初吉，柔得中也。","text":"中，谓二。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":5,"position":"终止则乱，其道穷也。","text":"反否终坤，故“其道穷也”。侯果曰：刚得正，柔得中，故“初吉”也。正有终极，济有息止，止则穷乱，故曰“终止则乱，其道穷也”。一曰：殷亡周兴之卦也。成汤应天，初吉也。商辛毒痛，终止也。由止，故物乱而穷也。物不可穷，穷则复始，周受其未济而兴焉。","locator":{"book":"周易集解","gua":"既济","pos":"卦辞·彖象"},"citation":"《周易集解》·既济卦·卦辞·彖象","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":8,"position":"六二：妇丧其佛，勿逐，七日得。","text":"离为妇。泰坤为丧。佛发，谓鬒发也。一名妇人之首饰。坎为玄云，故称发。《诗》曰：鬒发如云。乾为首，坎为美；五取乾二之坤为坎，坎为盗，故“妇丧其佛”。泰震为七，故“勿逐，七日得”。与睽丧马勿逐同义。佛，或作茀。俗说以佛为妇人蔽膝之茀，非也。","locator":{"book":"周易集解","gua":"既济","pos":"六二"},"citation":"《周易集解》·既济卦·六二","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":10,"position":"九三：高宗伐鬼方，三年克之，小人勿用。","text":"高宗，殷王武叮鬼方，国名。乾为高宗，坤为鬼方；乾二之坤五。故“高宗伐鬼方”。坤为年，位在三，故“三年”。坤为小人，二上克五，故“三年克之，小人勿用”。《象》曰：“惫也”。干宝曰：高宗，殷中兴之君。鬼方，北方国也。高宗尝伐鬼方，三年而后克之。离为戈兵，故称“伐”。坎当北方，故称“鬼”。在既济之家，而述先代之功，以明周因于殷，有所弗革也。","locator":{"book":"周易集解","gua":"既济","pos":"九三"},"citation":"《周易集解》·既济卦·九三","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":12,"position":"六四：繻有衣袽，终日戒。","text":"乾为衣，故称“繻”。袽，败衣也。乾二之五，衣象裂坏，故“繻有衣袽”。离为日，坎为盗，在两坎间，故“终日戒”。谓伐鬼方三年乃克。旅人勤劳，衣服皆败，鬼方之民，犹或寇窃，故“终日戒”也。","locator":{"book":"周易集解","gua":"既济","pos":"六四"},"citation":"《周易集解》·既济卦·六四","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":14,"position":"九五：东邻杀牛，不如西邻之禴祭，实受其福","text":"泰震为东，兑为西，坤为牛，震动五杀坤，故“东邻杀牛“。在坎多眚，为阴所乘，故“不如西邻之禴祭”。禴，夏祭也。离为夏。兑动二，体离，明。得正承五，顺三。故“实受其福，吉大来也”。","locator":{"book":"周易集解","gua":"既济","pos":"九五"},"citation":"《周易集解》·既济卦·九五","edition":"jijie"},{"gua":"既济","guaId":"g63","yaoIdx":16,"position":"上六：濡其首，厉。","text":"乾为首，五从二上在坎中，故“濡其首，厉”。位极乘阳，故“何可久”。","locator":{"book":"周易集解","gua":"既济","pos":"上六"},"citation":"《周易集解》·既济卦·上六","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":-1,"position":"卦辞","text":"否二之五也。柔得中，天地交。故“亨”。济，成也。六爻皆划错，故称未济也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞"},"citation":"《周易集解》·未济卦·卦辞","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":0,"position":"小狐汔济，","text":"否艮为小狐。汔，几也。济，济渡。狐济几度，而濡其尾，未出中也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":1,"position":"濡其尾，无攸利。","text":"艮为尾。狐，兽之长尾者也。尾谓二，在坎水中。故“濡其尾”。失位，故“无攸利，不续终也”。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":3,"position":"小狐汔济，未出中也。","text":"谓二未变，在坎中也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":4,"position":"濡其尾，无攸利，不续终也。","text":"否阴消阳，至剥终坤，终止则乱，其道穷也。乾五之二，坤杀不行，故“不续终也”。干宝曰：言禄父不能敬奉天命，以续既终之礼，谓叛而被诛也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":7,"position":"君子以慎辨物居方。","text":"君子，否乾也。艮为慎。辨，别也。物谓乾阳物也，坤阴物也；艮为居，坤为方；乾别五以居坤二。故“以慎辨物居方”也。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":8,"position":"初六：濡其尾，吝。","text":"应在四，故“濡其尾”。失位，故“吝”。","locator":{"book":"周易集解","gua":"未济","pos":"初六"},"citation":"《周易集解》·未济卦·初六","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":11,"position":"：九二贞吉，中以行正也。","text":"谓初已正，二动成震，故“行正”。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":14,"position":"九四：贞吉，悔亡。","text":"动正得位，故吉而悔亡矣。","locator":{"book":"周易集解","gua":"未济","pos":"九四"},"citation":"《周易集解》·未济卦·九四","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":15,"position":"震用伐鬼方，三年有赏于大邦。","text":"变之震，体师：坤为鬼方。故“震用伐鬼方”。坤为年，为大邦，阳称赏，四在坤中，体既济离三，故“三年有赏于大邦”。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":17,"position":"六五：贞吉，无悔。","text":"之正则吉，故“贞吉，无悔”。","locator":{"book":"周易集解","gua":"未济","pos":"六五"},"citation":"《周易集解》·未济卦·六五","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":18,"position":"君子之光，有孚，吉。","text":"动之乾，离为光，故“君子之光”也。孚谓二。二变应已，得有之，故“有孚吉”。坎称孚也。干宝曰：以六居五，周公摄政之象也，故曰“贞吉无悔”。制礼作乐，复子明辟。天下乃明其道，乃信其诚。故“君子之光，有孚，吉”矣。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":19,"position":"：君子之光，其晖吉也。","text":"动之正，乾为大明，故“其晖吉也”。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":20,"position":"上九：有孚于饮酒，无咎。濡其首，有孚失是","text":"坎为孚，谓四也。上之四介四，故“有孚”。饮酒流颐中，故“有孚于饮酒”。终变之正，故“无咎”。乾为首，五动首在酒中，失位，故“濡其首”矣。孚，信。是，正也。六位失正，故“有孚失是”。谓若殷纣沉湎于酒，以失天下也。","locator":{"book":"周易集解","gua":"未济","pos":"上九"},"citation":"《周易集解》·未济卦·上九","edition":"jijie"},{"gua":"未济","guaId":"g64","yaoIdx":21,"position":"：饮酒濡首，亦不知节也。","text":"节，止也。艮为节，饮酒濡首，故“不知节矣”。","locator":{"book":"周易集解","gua":"未济","pos":"卦辞·彖象"},"citation":"《周易集解》·未济卦·卦辞·彖象","edition":"jijie"}],"zhezhongSamples":[{"gua":"讼","guaId":"g06","pos":"集说/总论","text":"道无成而代有终，故曰“无成”。坤三同义也。","locator":{"book":"周易折中","gua":"讼","pos":"总论"},"citation":"《御纂周易折中》·讼卦·总论","edition":"zhezhong"},{"gua":"随","guaId":"g17","pos":"集说/总论","text":"阴随阳，三之上无应，上系于四，失初小子，故“系丈夫，失小子”。","locator":{"book":"周易折中","gua":"随","pos":"总论"},"citation":"《御纂周易折中》·随卦·总论","edition":"zhezhong"},{"gua":"震","guaId":"g51","pos":"集说/总论","text":"可以守宗庙社稷为祭主，故“无丧有事”也。","locator":{"book":"周易折中","gua":"震","pos":"总论"},"citation":"《御纂周易折中》·震卦·总论","edition":"zhezhong"},{"gua":"未济","guaId":"g64","pos":"集说/总论","text":"“孚”，信。“盥”，有威容貌。容止可观，进退可度，则下观其德而顺其化。《诗》曰：“颙颙卬卬，如圭如璋。”君德之义也。","locator":{"book":"周易折中","gua":"未济","pos":"总论"},"citation":"《御纂周易折中》·未济卦·总论","edition":"zhezhong"},{"gua":"未济","guaId":"g64","pos":"集说/总论","text":"圣人“退藏于密”“以神明其德”，故“设教而天下服矣”。","locator":{"book":"周易折中","gua":"未济","pos":"总论"},"citation":"《御纂周易折中》·未济卦·总论","edition":"zhezhong"}],"samples":[{"gua":"乾","guaId":"g01","pos":"九三：君子终日乾乾，夕惕，若厉，无咎。","text":"谓阳息至三，二变成离。离为日，坤为夕。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"},{"gua":"乾","guaId":"g01","pos":"九五：飞龙在天，利见大人。","text":"谓四已变，则五体离。离为飞，五在天，故“飞龙在天，利见大人”也。谓若庖牺观象于天，造作八卦，备物致用，以利天下，故曰“飞龙在天”。天下之所利见也。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"},{"gua":"乾","guaId":"g01","pos":"云行雨施，品物流形。","text":"已成既济，上坎为云，下坎为雨，故“云行雨施”。乾以云雨，流坤之形，万物化成，故曰“品物流形”也。","locator":{"book":"周易集解","gua":"乾","pos":""},"citation":"《周易集解》·乾卦·","edition":"jijie"}]};
